function normalizeBase(v){
  const t = String(v||'negocios').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();
  return t.includes('preco') ? 'precos' : 'negocios';
}
function getActiveProduto(){ return activeProduto === 'Milho' ? 'Milho' : 'Soja'; }
function getActiveBase(){ return activeBase === 'precos' ? 'precos' : 'negocios'; }

function getProductFactor(prodOrDeal){
  const p = typeof prodOrDeal === 'string' ? normalizeProduto(prodOrDeal) : normalizeProduto(prodOrDeal && prodOrDeal.produto);
  return (PRODUCT_CONFIG[p] || PRODUCT_CONFIG.Soja).factor;
}
function getActiveDeals(){
  const p = getActiveProduto();
  const b = getActiveBase();
  const src = b==='precos' ? getPrecosBase() : (state && Array.isArray(state.negocios) ? state.negocios : []);
  const key = `${p}|${b}|${src.length}|${state && state._version ? state._version : 0}`;
  if(_activeDealsCache.key === key && _activeDealsCache.rows) return _activeDealsCache.rows;
  /* grupoProduto: permite que um produto sem contrato próprio (ex. Sorgo) apareça
     agrupado na aba do produto de referência (ex. Milho), preservando seu produto real
     em cada linha. Não afeta Soja/Milho nativos. */
  const rows = src.filter(d => !d.foraEscopo && (normalizeProduto(d.produto) === p || (p==='Milho' && d.grupoProduto==='Milho')));
  _activeDealsCache = {key, rows};
  return rows;
}
