function applyMarketSnapshotToState(s){
  if(!s || s._marketSnapshotId===MARKET_SNAPSHOT_ID) return s;
  s.cbot = Object.assign({}, MARKET_SNAPSHOT.cbot);
  s.cbotMilho = Object.assign({}, MARKET_SNAPSHOT.cbotMilho);
  s.cbotFarelo = Object.assign({}, MARKET_SNAPSHOT.cbotFarelo||{});
  s.cbotOleo = Object.assign({}, MARKET_SNAPSHOT.cbotOleo||{});
  s.dolar = Object.assign({}, MARKET_SNAPSHOT.dolar);
  s.dolarProxies = {};
  // Aplica somente ao vencimento ausente: nunca substitui cotação futura fornecida.
  if(MARKET_SNAPSHOT_ID.startsWith(MARKET_SPOT_PROXY.data) && !Object.prototype.hasOwnProperty.call(MARKET_SNAPSHOT.dolar,MARKET_SPOT_PROXY.mes)){
    s.dolar[MARKET_SPOT_PROXY.mes] = MARKET_SPOT_PROXY.taxa;
    s.dolarProxies[MARKET_SPOT_PROXY.mes] = Object.assign({}, MARKET_SPOT_PROXY);
  }
  if(!s.curva) s.curva = structuredClone(CURVA_DEFAULT);
  Object.keys(s.curva).forEach(function(v){if(!Object.prototype.hasOwnProperty.call(MARKET_SNAPSHOT.cbot,v))delete s.curva[v];});
  Object.keys(MARKET_SNAPSHOT.cbot).forEach(function(v){
    if(!s.curva[v]) s.curva[v]={fobbins:(s.fobbins??FOBBINS_DEFAULT),seaFreight:(s.seaFreight??SEA_FREIGHT_DEFAULT)};
    s.curva[v].cbot=MARKET_SNAPSHOT.cbot[v];
    var mes=CBOT_TO_DOLAR_MES[v]; s.curva[v].cambio=(mes && s.dolar[mes]!=null)?s.dolar[mes]:null;
  });
  if(!s.curvaMilho) s.curvaMilho={};
  Object.keys(s.curvaMilho).forEach(function(v){if(!Object.prototype.hasOwnProperty.call(MARKET_SNAPSHOT.cbotMilho,v))delete s.curvaMilho[v];});
  Object.keys(MARKET_SNAPSHOT.cbotMilho).forEach(function(v){
    if(!s.curvaMilho[v]) s.curvaMilho[v]={fobbins:(s.fobbins??FOBBINS_DEFAULT),seaFreight:0};
    s.curvaMilho[v].cbot=MARKET_SNAPSHOT.cbotMilho[v];
    var mes=CBOT_TO_DOLAR_MES[v]; s.curvaMilho[v].cambio=(mes && s.dolar[mes]!=null)?s.dolar[mes]:null;
  });
  /* Curva corrente e negócios fechados são bases separadas.
     O snapshot diário atualiza state.cbot/state.dolar, mas não reprecifica negócios. */
  brzRestoreDealMarketSnapshots(s.negocios||[]);
  brzApplySoyXRuleToRows(s.negocios||[], s.cbot || MARKET_SNAPSHOT.cbot);
  brzRestoreDealMarketSnapshots(s.negocios||[]);
  s.timestamps = Object.assign({}, s.timestamps||{}, {
    cbot:MARKET_SNAPSHOT.timestamp,
    dolar:(MARKET_SNAPSHOT.dolarTimestamp||MARKET_SNAPSHOT.timestamp)+' · DOLX26 ausente em 04/11 C2; sem proxy spot; 24 vencimentos observados até Nov28'
  });
  s._marketSnapshotId=MARKET_SNAPSHOT_ID;
  return s;
}


