Object.assign(CITY_COORDS, {"Itapiratins": [-8.3838889, -48.1108333], "Itapiratins - TO": [-8.3838889, -48.1108333]});
function haversineKm(a, b){
  if(!a || !b) return null;
  const R = 6371;
  const dLat = (b[0]-a[0]) * Math.PI/180;
  const dLng = (b[1]-a[1]) * Math.PI/180;
  const lat1 = a[0] * Math.PI/180, lat2 = b[0] * Math.PI/180;
  const x = Math.sin(dLat/2)**2 + Math.sin(dLng/2)**2 * Math.cos(lat1) * Math.cos(lat2);
  return 2 * R * Math.asin(Math.sqrt(x));
}

/* Extrai a cidade base do texto de origem.
   Ex: "Rio Verde/GO + 55km sentido Paraúna" → "Rio Verde"
       "MTV + 60km" → "MTV"
       "Bom Jesus/PI" → "Bom Jesus" */
function extractCidadeBase(origemText){
  if(!origemText) return null;
  // BRZ 08/09: exact full-key wins before stripping UF (resolve homônimos como Santa Helena/PR x Santa Helena/MA).
  const _fullCityKey = String(origemText).split(/[+]/)[0].trim();
  if(typeof CITY_COORDS!=='undefined' && CITY_COORDS[_fullCityKey]) return _fullCityKey;
  // Quebra em "+" e pega o primeiro pedaço
  let s = _fullCityKey;
  // Regra BRZ: mesmo em CIF/local detalhado, extrai a origem operacional para calcular TKU até o porto.
  // Ex.: "CIF Palmeirante/TO", "FOB Fazenda X - Tasso Fragoso/MA", "FOB Santana do Araguaia - PA - Armazém Y".
  s = s.replace(/^(cif|fob)\s+/i, '').trim();
  s = s.replace(/^(origem|local)\s*[:\-]\s*/i, '').trim();
  // Remove sufixo /UF (ex: "Jataí/GO + 35km" → "Jataí")
  s = s.replace(/\/[A-Z]{2}.*$/, '').trim();
  // Remove marcas comuns antes da cidade quando houver separador.
  s = s.replace(/^(armaz[eé]m|arm|fazenda)\s+[\w\s.ÁÉÍÓÚÂÊÔÃÕÇáéíóúâêôãõç-]*?\s+-\s*/i, '');
  // Lida com " - " no texto
  if(s.includes(' - ')){
    const parts = s.split(' - ').map(x=>x.trim()).filter(Boolean);
    const ufIdx = parts.findIndex(p => /^[A-Z]{2}$/.test(p));
    if(ufIdx > 0){
      s = parts[ufIdx - 1].trim();
    } else {
      // Se não houver UF isolada, usa o último segmento que não pareça armazém/fazenda.
      const useful = parts.filter(p => !/^(armaz[eé]m|arm|fazenda|faz\.?)/i.test(p));
      s = (useful[useful.length - 1] || parts[parts.length - 1] || s).trim();
    }
  }
  return s;
}

/* Tenta achar coordenada da cidade (busca tolerante a maiúsculas/acentos) */
function getCityCoord(cidade){
  if(!cidade) return null;
  // Correção V22: evita que Rio Negro/PR seja confundido pelo match parcial com Aparecida do Rio Negro/TO.
  try{ var _gc=String(cidade).normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().trim(); if(_gc==='rio negro') return [-26.10583,-49.7975]; }catch(_e){}
  // Match exato
  if(CITY_COORDS[cidade]) return CITY_COORDS[cidade];
  // Match case-insensitive
  const lower = cidade.toLowerCase();
  for(const key in CITY_COORDS){
    if(key.startsWith('_')) continue;
    if(key.toLowerCase() === lower) return CITY_COORDS[key];
  }
  // Match exato normalizado (remove acento) ANTES de substring — evita Guarantã do Norte/MT → Guarantã/SP
  try{
    const norm = x=>String(x).normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().trim();
    const nl=norm(cidade);
    for(const key in CITY_COORDS){ if(key.startsWith('_')) continue; if(norm(key)===nl) return CITY_COORDS[key]; }
  }catch(_e){}
  // Match parcial: a chave está contida na cidade ou vice-versa
  /* FIX 18/09/2026: o match parcial devolvia a PRIMEIRA chave contida no texto, então
     'Lucas do Rio Verde - MT' casava com 'Rio Verde' (GO) e resolvia ~900 km fora, no
     estado errado. Passa a escolher a chave MAIS LONGA que casa, que é a mais específica,
     resolvendo a classe toda do problema (Lucas do Rio Verde, Guarantã do Norte etc.). */
  let _bestKey=null, _bestLen=-1;
  for(const key in CITY_COORDS){
    if(key.startsWith('_')) continue;
    const k = key.toLowerCase();
    if(lower.includes(k) || k.includes(lower)){
      if(k.length > _bestLen){ _bestLen=k.length; _bestKey=key; }
    }
  }
  if(_bestKey) return CITY_COORDS[_bestKey];
  return null;
}

/* Distância em km de uma origem até um porto, usando coords+haversine+road factor.
   Também aceita um "+Xkm" extra no texto da origem. */
function estimateDistanceKm(origemText, porto, corredor){
  const cidade = extractCidadeBase(origemText);
  let coordA = getCityCoord(cidade);
  if(!coordA && corredor && typeof MAP_DATA!=='undefined' && MAP_DATA.corredores && MAP_DATA.corredores[corredor]) coordA = MAP_DATA.corredores[corredor];
  if(!coordA){ var _uf=String(origemText||'').match(/[-\/]\s*([A-Z]{2})\b/); if(_uf && UF_COORDS[_uf[1]]) coordA = UF_COORDS[_uf[1]]; }
  const coordB = CITY_COORDS['_porto_' + porto] || getCityCoord(porto);
  if(!coordA || !coordB) return null;
  let km = haversineKm(coordA, coordB) * ROAD_FACTOR;
  // soma km extra mencionado no texto (+ XX km)
  const extra = String(origemText).match(/\+\s*(\d+)\s*km/i);
  if(extra) km += parseFloat(extra[1]);
  return km;
}

/* Calcula TKU médio (R$/tku) a partir dos fretes já cadastrados, por PORTO.
   Cache estático — recalcula só se a base mudar. */
let _tkuCache = null;
function getTkuMedioPorPorto(){
  // Performance: com histórico longo, calcular TKU médio varrendo todos os fretes travava o navegador.
  // Fallback usado somente quando não há frete histórico exato/anterior para a rota.
  if(_tkuCache) return _tkuCache;
  _tkuCache = {
    'Santos': 0.30,
    'Paranaguá': 0.30,
    'Itaqui': 0.27,
    'Barcarena': 0.27,
    'Rio Grande': 0.30,
    'Miritituba': 0.27,
    'Porto Velho': 0.27
  };
  return _tkuCache;
}

/* Estima frete R$/t para origem→porto que não está cadastrado */
function estimateFreightRodo(origemText, porto, corredor, semana){
  const km = estimateDistanceKm(origemText, porto, corredor);
  if(!km) return null;
  // TKU LOCAL: deriva o TKU do frete cadastrado da origem mais proxima para o mesmo porto
  // (TKU = freteRef / km(refCidade ate porto)) e aplica a distancia total do deal (cidade ate porto + km da fazenda).
  // A referencia segue a SEMANA do negocio (frete da semana do deal, ou anterior mais proxima): TKU dinamico semana a semana.
  const refs = getClosestFreightReferences(origemText, porto, semana || null, corredor);
  if(refs && refs.length){
    const ref = refs[0];
    const kmRefPort = estimateDistanceKm(ref.origemRef, porto);
    if(kmRefPort && ref.freteRefValor != null && ref.freteRefValor > 0){
      const tkuLocal = ref.freteRefValor / kmRefPort;
      return {valor: km * tkuLocal, km, tku: tkuLocal, estimado: true, tkuFonte: 'ref_proxima', refOrigem: ref.origemRef, kmRef: ref.kmReferencia, semanaRef: ref.semana || '', freteRef: ref.freteRefValor};
    }
  }
  // Fallback: TKU medio fixo por porto (so quando nao ha referencia cadastrada).
  const tku = getTkuMedioPorPorto()[porto] || 0.30;
  return {valor: km * tku, km, tku, estimado: true, tkuFonte: 'tku_medio'};
}



