/* V4AR 05/11/2026 · Base de Preços: só a sessão corrente da curva de mercado é
   remarcada e reprecificada, pela régua única (meses.cbot.*) e pelo câmbio de
   cambio.precos (DOL do próprio mês do embarque). Datas anteriores ficam como
   gravadas (M9: histórico conserva o regime da data). Substitui o hardcode V4F
   (Mar-27→H27/DOLH27, Apr-27→K27/DOLJ27). */
function brzSyncPrecoMarketCurves(rows){
  if(!Array.isArray(rows)||typeof state==='undefined'||!state)return rows;
  /* V4AS: data da sessão por brzMarketDate() (ISO do snapshot; dd/mm/aaaa como reserva). */
  var _marketDate=brzMarketDate();
  if(!_marketDate)return rows;
  var baseCambio=String(brzRegraParam('cambio.precos','base','embarque'));
  rows.forEach(function(d){
    if(d.data!==_marketDate)return;
    var info=brzMesesCBOT(d.produto,d.embarque,d.data);
    if(info){ d.vencCBOT=info.venc; d.vencFreteCBOT=info.venc; }
    if(baseCambio==='embarque'){
      var dl=brzDolEmbarque(d.embarque); if(dl) d.vencCambio=dl.venc;
    }else if(baseCambio==='cbot' && typeof CBOT_TO_DOLAR_MES!=='undefined'){
      var mk=CBOT_TO_DOLAR_MES[d.vencCBOT]; if(mk){ var ii=BRZ_MES_PT.indexOf(mk.slice(0,3)); if(ii>=0) d.vencCambio='DOL'+BRZ_LETRA_MES[ii]+mk.slice(3); }
    }
    var prod=(d.produto==='Soja')?'cbot':((d.produto==='Milho'||d.produto==='Sorgo')?'cbotMilho':null);
    if(prod){var c=Number((state[prod]||{})[d.vencCBOT]);if(Number.isFinite(c)&&c>0)d.cbot=c;}
    var dk=brzDolChave(d.vencCambio);
    if(dk){var v=Number((state.dolar||{})[dk]);if(Number.isFinite(v)&&v>0)d.cambio=v;}
  });
  return rows;
}

function getPrecosBase(){
  if(PRECOS_BASE_CACHE) return brzSyncPrecoMarketCurves(PRECOS_BASE_CACHE);
  const el = document.getElementById('dataPrecos');
  try{
    PRECOS_BASE_CACHE = JSON.parse((el && el.textContent) ? el.textContent : '[]');
  }catch(e){
    console.error('Erro ao carregar base de preços:', e);
    PRECOS_BASE_CACHE = [];
  }
  try{
    if(typeof state!=='undefined' && state && state.precosEdits){
      var _ix={}; PRECOS_BASE_CACHE.forEach(function(r){ _ix[r.id]=r; });
      Object.keys(state.precosEdits).forEach(function(k){ if(_ix[k]) Object.assign(_ix[k], state.precosEdits[k]); });
    }
  }catch(_e){}
  /* V4AR: régua não remarca histórico da Base de Preços (M8/M9); só a sessão do dia, em brzSyncPrecoMarketCurves. */
  return brzSyncPrecoMarketCurves(PRECOS_BASE_CACHE);
}
const PRECOS_BASE = { __lazy:true };
const PREMIOS_BASE = (function(){ try{ return JSON.parse(document.getElementById('dataPremios').textContent); }catch(e){ return []; } })();
