const SPREAD_PORTO = brzRegraParam('basis.spreadSoja','porPorto',{'Santos':0,'Paranaguá':-5,'Rio Grande':-2,'Itaqui':-5,'Barcarena':-16});
function _premioMid(o){ if(!o) return null; var of=(o.offer===0||o.offer)?o.offer:null, bd=(o.bid===0||o.bid)?o.bid:null; if(of!=null&&bd!=null) return (of+bd)/2; if(of!=null) return of; if(bd!=null) return bd; return null; }
function premioRecordForDate(date){ var b=getPremiosBase(); if(!b.length) return null; var ex=b.filter(function(r){return r.data===date;}); if(ex.length) return ex[ex.length-1]; var le=b.filter(function(r){return String(r.data)<=String(date);}).sort(function(a,c){return String(a.data)<String(c.data)?-1:1;}); return le.length?le[le.length-1]:null; }
/* V4AS 05/11/2026 · prêmio de papel FOB da soja lido do xlsx diário (dataBasisFOB,
   Soybean Paranaguá, janela mensal F). Papel é cotado contra o contrato de mercado
   (basis.papelSoja); converte para o contrato do registro pelo CBOT do dia. Sem CBOT
   de um dos dois contratos: sem margem (null), nunca valor errado. */
var _brzBFOB=null;
function brzBasisFOBSeries(){ if(_brzBFOB) return _brzBFOB; try{ _brzBFOB=JSON.parse(document.getElementById('dataBasisFOB').textContent).series||{}; }catch(e){ _brzBFOB={}; } return _brzBFOB; }
function _brzAsOf(ser,ymd,maxDias){
  if(!ser||!ser.length) return null; var best=null;
  for(var i=0;i<ser.length;i++){ if(ser[i][0]<=ymd && (!best||ser[i][0]>best[0])) best=ser[i]; }
  if(!best) return null;
  var f=function(n){ n=String(n); return new Date(n.slice(0,4)+'-'+n.slice(4,6)+'-'+n.slice(6,8)+'T12:00:00Z'); };
  return ((f(ymd)-f(best[0]))/864e5>maxDias)?null:best;
}
function brzPapelSojaContrato(e){
  var t=brzRegraParam('basis.papelSoja','contrato',null)||{Jan:'F',Feb:'H',Mar:'H',Apr:'K',May:'K',Jun:'N',Jul:'N',Aug:'Q',Sep:'U',Oct:'X',Nov:'X',Dec:'F+1'};
  var cel=String(t[BRZ_MES_EN[e.mes]]||''); var m=/^([FGHJKMNQUVXZ])(\+1)?$/.exec(cel); if(!m) return null;
  return m[1]+String((e.yy+(m[2]?1:0))%100).padStart(2,'0');
}
function brzPremioSojaPapel(date,porto,embarque,deal){
  var e=brzEmbParse(embarque); if(!e) return undefined;
  var base='Soybean|Paranaguá|F|'+String(e.mes+1).padStart(2,'0')+'-'+(2000+e.yy);
  var S=brzBasisFOBSeries(); if(!S[base+'|bid'] && !S[base+'|offer']) return undefined;
  var ymd=Number(String(date).replace(/-/g,''));
  var b=_brzAsOf(S[base+'|bid'],ymd,7), o=_brzAsOf(S[base+'|offer'],ymd,7);
  if(!b && !o) return null;
  var mid=(b&&o)?(Number(b[1])+Number(o[1]))/2:Number((b||o)[1]);
  var cp=brzPapelSojaContrato(e); if(!cp) return null;
  var cd=(deal&&deal.vencCBOT)?String(deal.vencCBOT):cp, adj=0;
  if(cp!==cd){ var a=brzCbotNaData('Soja',cp,date), c=brzCbotNaData('Soja',cd,date); if(!(a>0&&c>0)) return null; adj=a-c; }
  var sp=SPREAD_PORTO[porto]; if(sp==null) return null;
  return mid+adj+5+sp;
}

function premioBidFOB(date,porto,embarque,deal){ if(!date||!porto||!embarque) return null; if(!(typeof getActiveProduto==='function'&&getActiveProduto()==='Milho')){ var _ps=brzPremioSojaPapel(date,porto,embarque,deal); if(_ps!==undefined) return _ps; } if(typeof getActiveProduto==='function'&&getActiveProduto()==='Milho') return premioBidFOBMilho(date,porto,embarque); var r=premioRecordForDate(date); if(!r||!r.fobPaper) return null; var mid=_premioMid(r.fobPaper[embarque]); if(mid==null) return null; var sp=SPREAD_PORTO[porto]; if(sp==null) return null; return mid+5+sp; }
function premioMilhoRecordForDate(date){ var b=(typeof state!=='undefined'&&state&&state.premiosMilho)?state.premiosMilho:[]; if(!b.length) return null; var ex=b.filter(function(r){return r.data===date;}); if(ex.length) return ex[ex.length-1]; var le=b.filter(function(r){return String(r.data)<=String(date);}).sort(function(a,c){return String(a.data)<String(c.data)?-1:1;}); return le.length?le[le.length-1]:null; }
var MILHO_SPREAD_PORTO=brzRegraParam('basis.spreadMilho','porPorto',null)||{'Santos':0,'Tubar\u00e3o':0,'Paranagu\u00e1':-3,'Itaqui':-3,'Barcarena':-5,'S\u00e3o Francisco do Sul':-3,'Rio Grande':-3,'Itacoatiara':-30,'Santar\u00e9m':-20};
function premioMilhoCargoGroupForPort(porto){
  var p=String(porto||'').trim();
  var map={
    'Santos':'Santos','Tubar\u00e3o':'Santos','Tubarao':'Santos',
    'Paranagu\u00e1':'Paranagu\u00e1','Paranagua':'Paranagu\u00e1',
    'Itaqui':'Norte','Barcarena':'Norte',
    'Santar\u00e9m':'Santar\u00e9m','Santarem':'Santar\u00e9m',
    'Itacoatiara':'Itacoatiara'
  };
  return map[p]||null;
}
function premioMilhoPortValue(rec,porto,embarque){
  if(!rec||!rec.cargo||!porto||!embarque) return null;
  var grupo=premioMilhoCargoGroupForPort(porto);
  var direto=(grupo&&rec.cargo[grupo])?_premioMid(rec.cargo[grupo][embarque]):null;
  if(direto!=null) return direto;
  var santos=rec.cargo['Santos']?_premioMid(rec.cargo['Santos'][embarque]):null;
  var sp=MILHO_SPREAD_PORTO[porto];
  if(santos==null||sp==null) return null;
  return santos+sp;
}
function premioBidFOBMilho(date,porto,embarque){ if(date==="2026-11-10"||date==="2026-11-11") return brzTabCornExactBid(date,porto,embarque); var r=premioMilhoRecordForDate(date); return premioMilhoPortValue(r,porto,embarque); }
/* V4DU · TAB Milho: cotação bid CONFIRMADA da aba Basis FOB na mesma data/porto/janela.
   FH/LH são janelas comerciais separadas, com múltiplos tipos priorizados só dentro
   da mesma janela; nunca fabricar bid via spread teórico Santos→outro porto.
   Quando há somente offer, retornar null em vez de reciclar bid de 04/11. */
function brzTabCornExactBid(date,porto,embarque){
  if(!date||!porto||!embarque) return null;
  var e=brzEmbParse(embarque);if(!e)return null;
  var mo=String(e.mes+1).padStart(2,'0')+'-'+String(2000+e.yy);
  var day=Number(String(date).replace(/-/g,''));
  var _port=(porto==='Tubarão'||porto==='Tubarao')?'Santos':porto; var prefix='Corn|'+_port+'|'; var S=brzBasisFOBSeries(),hits=[];
  ['F','LH','FH'].forEach(function(jan){
    var key=prefix+jan+'|'+mo+'|bid',ser=S[key];
    if(!ser)return;
    for(var i=ser.length-1;i>=0;i--){if(ser[i][0]===day){hits.push(Number(ser[i][1]));break;}if(ser[i][0]<day)break;}
  });
  return hits.length?Math.max.apply(null,hits):null;
}
