function safeStorage(){
  try{
    const s = window.localStorage;
    const k = '__brz_test__';
    s.setItem(k,'1'); s.removeItem(k);
    return s;
  }catch(e){
    return {getItem:()=>null,setItem:()=>{},removeItem:()=>{},clear:()=>{}};
  }
}
const BRZ_STORAGE = safeStorage();
window.addEventListener('error', function(ev){
  try{
    const active = document.querySelector('.screen.active');
    const body = active ? (document.getElementById(active.id + 'Body') || active.querySelector('[id$="Body"]')) : null;
    if(body && !body.innerHTML.trim()){
      body.innerHTML = '<div class="empty" style="color:#b91c1c">Erro ao renderizar: '+ String(ev.message || 'erro desconhecido') +'</div>';
    }
  }catch(_e){}
});

let _currentLang = BRZ_STORAGE.getItem('brzLang') || 'pt';

function t(key){
  const entry = I18N[key];
  if(!entry) return key;
  return entry[_currentLang] || entry.pt || key;
}

function setLang(lang){
  if(lang !== 'pt' && lang !== 'en') return;
  _currentLang = lang;
  try{ BRZ_STORAGE.setItem('brzLang', lang); BRZ_STORAGE.setItem('brz_lang', lang); }catch(e){}
  // Re-render first, then translate static and dynamic content.
  if(typeof renderAll === 'function'){
    try { renderAll(); } catch(e){}
    try { if(typeof renderMapa === 'function' && document.getElementById('mapa')?.classList.contains('active')) renderMapa(); } catch(e){}
  }
  applyI18n();
  // Update toggle button visual
  const ptBtn = document.getElementById('langBtnPt');
  const enBtn = document.getElementById('langBtnEn');
  if(ptBtn) ptBtn.style.background = lang==='pt' ? 'var(--g50)' : 'none';
  if(enBtn) enBtn.style.background = lang==='en' ? 'var(--g50)' : 'none';
  if(ptBtn) ptBtn.style.boxShadow = lang==='pt' ? 'inset 0 0 0 1.5px var(--g700)' : 'none';
  if(enBtn) enBtn.style.boxShadow = lang==='en' ? 'inset 0 0 0 1.5px var(--g700)' : 'none';
}

function applyI18n(){
  // Translate elements with data-i18n
  document.querySelectorAll('[data-i18n]').forEach(el=>{
    const key = el.getAttribute('data-i18n');
    const val = t(key);
    if(val !== undefined) el.innerHTML = val;
  });
  // Translate title attrs with data-i18n-title
  document.querySelectorAll('[data-i18n-title]').forEach(el=>{
    el.setAttribute('title', t(el.getAttribute('data-i18n-title')));
  });
  // Translate placeholders
  document.querySelectorAll('[data-i18n-ph]').forEach(el=>{
    el.setAttribute('placeholder', t(el.getAttribute('data-i18n-ph')));
  });
  // Translate hardcoded/dynamic labels still not covered by data-i18n
  try{ applyLooseI18n(); }catch(e){ console.warn('Loose i18n warning:', e); }
}



