    cbotMilho: {...CBOT_MILHO_DEFAULT},
    curvaMilho: Object.fromEntries(CBOT_MILHO_VENCIMENTOS.map(v=>[v,{cbot:CBOT_MILHO_DEFAULT[v]||0,cambio:DOLAR_DEFAULT[CBOT_TO_DOLAR_MES[v]]||0,fobbins:FOBBINS_DEFAULT,seaFreight:0}])),
    dolar: {...DOLAR_DEFAULT},
    fobbins: FOBBINS_DEFAULT,
    seaFreight: SEA_FREIGHT_DEFAULT,
