/* Validação defensiva para a base histórica de Preços.
   A base importada pode ter linhas com curva/contrato inválido ou resíduos de parser.
   Sem esse filtro, um único ponto fora da escala distorce todos os gráficos e modais dos cards. */
function finiteNum(v){ return Number.isFinite(Number(v)); }
function isReasonableMarketInput(deal){
  /* V4EO: validar operacao multi-janela pelos seus lotes; nao exigir CBOT unica. */
  if(deal&&Array.isArray(deal.lotesEmbarque)&&deal.lotesEmbarque.length>=2){
    const vol=deal.lotesEmbarque.reduce((v,l)=>v+(Number(l.volume)||0),0);
    if(!(vol>0)||Math.abs(vol-(Number(deal.volume)||0))>0.001)return false;
    return deal.lotesEmbarque.every(l=>isReasonableMarketInput(Object.assign({},deal,{
      volume:l.volume,cbot:Number(l.cbot),vencCBOT:l.vencCBOT,
      cambio:Number(l.cambio),lotesEmbarque:null
    })));
  }
  const prod = normalizeProduto(deal && deal.produto);
  const preco = Number(deal && deal.preco);
  const cambio = Number(deal && deal.cambio);
  const cbot = Number(deal && deal.cbot);
  if(!finiteNum(preco) || !finiteNum(cambio) || !finiteNum(cbot)) return false;
  if(preco <= 0 || preco > 300) return false;
  if(cambio <= 0 || cambio > 12) return false;
  if(prod === 'Milho' || prod === 'Sorgo') return cbot >= 150 && cbot <= 900;
  return cbot >= 500 && cbot <= 2500;
}
function isReasonableReplacementResult(deal, calc){
  if(!isReasonableMarketInput(deal) || !calc) return false;
  const fields = ['replacementFOB','replacementBasis','replacementCFR','_priceCbu','_freightCbu','_fobbinsCbu'];
  if(fields.some(k => !finiteNum(calc[k]))) return false;
  const basis = Number(calc.replacementBasis);
  const fob = Number(calc.replacementFOB);
  const cfr = Number(calc.replacementCFR);
  if(Math.abs(basis) > 1000) return false;
  if(fob <= 0 || fob > 4000) return false;
  if(cfr <= 0 || cfr > 4500) return false;
  return true;
}


