  // ===== GOIÁS — liquidação exclusivamente via Santos =====
  'GO Sul':          [{porto:'Santos',modal:'T'},{porto:'Santos',modal:'T+R',transbordo:'Rio Verde'}],
  'GO Sudoeste':     [{porto:'Santos',modal:'T'},{porto:'Santos',modal:'T+R',transbordo:'Rio Verde'}],
