function brzEvoAudit(id){ var d=document.getElementById('eva-'+id); var b=document.getElementById('evab-'+id); if(!d)return; var sh=(d.style.display==='none'); d.style.display=sh?'':'none'; if(b)b.classList.toggle('on',sh); }
function brzEvoToggle(id){ var d=document.getElementById('evd-'+id); var b=document.getElementById('evb-'+id); if(!d)return; var sh=(d.style.display==='none'); d.style.display=sh?'':'none'; if(b)b.innerHTML=sh?'\u25be':'\u25b8'; }
function setAnaliseBase(b){ analiseBase=b; if(b==='negocios'){analiseRankAll=true;analiseHiddenRows={};} analiseVenc=null; analiseOrigem=null; analiseData=null; analiseCompareData=null; _aggCache={k:null,v:null}; renderAnalise(); }
