      var focusE=visE[0]; (function(){ var _bn=-1; visE.forEach(function(e){ var c=0; _dts.forEach(function(r){ var o=(r.fobPaper||{})[e]; if(o&&(o.offer!=null||o.bid!=null))c++; }); if(c>_bn){_bn=c;focusE=e;} }); })();
