    h+='<tr><td>'+e+'</td><td>'+fmt(o?o.offer:null)+'</td><td>'+fmt(o?o.bid:null)+'</td>'+midCell(mid)+'<td>'+dlt(mid,midP)+'</td><td>'+dlt(mid,midW)+'</td></tr>';
