  var _ib=(typeof indicadoresBase!=='undefined'?indicadoresBase:'precos');
  var src; try{ src=(_ib==='negocios'?(((typeof state!=='undefined'&&state.negocios)||[]).filter(function(d){return !d.foraMercado;})):getPrecosBase()); }catch(e){ src=[]; }
  var _ap=getActiveProduto(); var soja=src.filter(function(d){return normalizeProduto(d.produto)===_ap;});
  if(!soja.length){ w.innerHTML='<div class="idc-wrap"><div class="idc-card">Sem base de preços para indicadores.</div></div>'; return; }
  var F=(typeof getProductFactor==='function'?getProductFactor(_ap):2.2046);

  function nf(v,d){ if(v==null||v===''||isNaN(v))return '—'; var m=Math.pow(10,d||0); return (Math.round(v*m)/m).toLocaleString('pt-BR',{minimumFractionDigits:d||0,maximumFractionDigits:d||0}); }
  function sg(v,d){ if(v==null||isNaN(v))return '<span class="muted">—</span>'; var c=v>0?'pos':(v<0?'neg':'zero'); return '<span class="'+c+'">'+(v>0?'+':'')+nf(v,d)+'</span>'; }
  function shortO(o){ try{ return (typeof aShort==='function')?aShort(o):o; }catch(e){ return o; } }
  function vkey(e){ try{ return (typeof aVencKey==='function')?aVencKey(e):0; }catch(x){ return 0; } }
  function pctile(arr,val){ if(!arr||!arr.length)return null; var c=0; for(var i=0;i<arr.length;i++) if(arr[i]<=val)c++; return 100*c/arr.length; }
  function cashBasis(d){ return priceCbu(d.preco,d.cambio,F)-Number(d.cbot); }
  function fobBasis(pr,ca,cb,fr,fb,Ff){ return priceCbu(pr,ca,Ff)+freightCbu(fr,ca,Ff)+usdTCbu(fb,Ff)-Number(cb); }

  function embOf(d){ return d.embarque||(typeof embFromVenc==='function'?embarqueInferido(d):null); }
  var dates=Array.from(new Set(soja.map(function(d){return d.data;}))).sort();
  var _ti=(indicadoresDate&&dates.indexOf(indicadoresDate)>=0)?dates.indexOf(indicadoresDate):(dates.length-1);
  var today=dates[_ti], prev=_ti>0?dates[_ti-1]:null;
  var fmtToday=String(today).split('-').reverse().join('/');
  var day=soja.filter(function(d){return d.data===today&&d.cbot&&d.cambio;});

  var _idcMilho=(typeof getActiveProduto==='function'&&getActiveProduto()==='Milho');
  var rec=null; try{ rec=_idcMilho?premioMilhoRecordForDate(today):premioRecordForDate(today); }catch(e){}
  function midFor(emb){ try{ if(_idcMilho){ return (rec&&rec.cargo&&rec.cargo['Santos'])?_premioMid(rec.cargo['Santos'][emb]):null; } return (rec&&rec.fobPaper)?_premioMid(rec.fobPaper[emb]):null; }catch(e){ return null; } }
  function widthFor(emb){ try{ var o=rec&&rec.fobPaper&&rec.fobPaper[emb]; if(!o)return null; if(o.offer==null||o.bid==null)return null; return o.offer-o.bid; }catch(e){ return null; } }

  // ===== montar células e linhas por origem =====
  var cells={}, origRows={};
  day.forEach(function(d){
    var pc; try{pc=computePortComparison(d);}catch(e){return;}
    (pc.results||[]).forEach(function(r){
      if(!r.best||r.best.replacementBasis==null||isNaN(r.best.replacementBasis))return;
      var porto=r.porto, emb=embOf(d); if(!emb)return;
      var prem; try{prem=premioBidFOB(today,porto,emb);}catch(e){prem=null;}
      if(prem==null)return;
      var repl=r.best.replacementBasis, margin=prem-repl;
      var oid=String(d.id||d.origem)+'|'+porto+'|'+emb;
      var row={oid:oid,deal:d,best:r.best,porto:porto,emb:emb,prem:prem,mid:midFor(emb),repl:repl,margin:margin,balcao:(r.best.fonteFrete==='porto_origem')};
      (origRows[porto+'||'+emb]=origRows[porto+'||'+emb]||[]).push(row);
      cells[porto]=cells[porto]||{}; var cur=cells[porto][emb];
      if(!cur||margin>cur.margin)cells[porto][emb]=row;
    });
  });

  var embsAll=Array.from(new Set(day.map(function(d){return embOf(d);}))).filter(Boolean).sort(function(a,b){return vkey(a)-vkey(b);});
  var visEmbs=embsAll.filter(function(e){return !idcState.hidden[e];});
  if(!visEmbs.length){ visEmbs=embsAll.slice(); idcState.hidden={}; }
  var portos=Object.keys(cells).sort(function(a,b){
    function mx(p){ var m=-1e9; visEmbs.forEach(function(e){ var c=cells[p]&&cells[p][e]; if(c&&c.margin>m)m=c.margin; }); return m; }
    return mx(b)-mx(a);
  });
  function cellAt(p,e){ return (cells[p]&&cells[p][e])||null; }

  // selecção válida
  if(!idcState.porto||!cellAt(idcState.porto,idcState.emb)||idcState.hidden[idcState.emb]){
    var bs=null; portos.forEach(function(p){ visEmbs.forEach(function(e){ var c=cellAt(p,e); if(c&&(!bs||c.margin>bs.m)) bs={p:p,e:e,m:c.margin}; }); });
    if(bs){ idcState.porto=bs.p; idcState.emb=bs.e; } else { idcState.porto=portos[0]||null; idcState.emb=visEmbs[0]||null; }
    idcState.oid=null;
  }

