/* ═══════════════════════════════════════════════════════
   CURVA DE MERCADO — CBOT (7 vencimentos) + Dólar (mensal)
═══════════════════════════════════════════════════════ */
function brzMercadoContratoOrdem(v){
  var m=/^([FGHJKMNQUVXZ])(\d{2})$/.exec(String(v||''));
  var months={F:1,G:2,H:3,J:4,K:5,M:6,N:7,Q:8,U:9,V:10,X:11,Z:12};
  return m?((2000+Number(m[2]))*100+months[m[1]]):0;
}
function brzMercadoVencimentos(curveKey){
  /* Dinâmico: exibir SOMENTE os contratos efetivamente enviados no snapshot vigente. */
  var current=(MARKET_SNAPSHOT&&MARKET_SNAPSHOT[curveKey])||{};
  return Object.keys(current)
    .filter(function(k){return brzMercadoContratoOrdem(k)>202610;})
    .sort(function(a,b){return brzMercadoContratoOrdem(a)-brzMercadoContratoOrdem(b);});
}
function brzMercadoDolarMeses(){
  var captured=(MARKET_SNAPSHOT&&MARKET_SNAPSHOT.dolar)||{}, names=['Jan','Fev','Mar','Abr','Mai','Jun','Jul','Ago','Set','Out','Nov','Dez'];
  var keys=Object.keys(captured);
  // Inclui a proxy na tabela sem alterar o livro das 23 cotações DOL B3 observadas.
  if(MARKET_SPOT_PROXY && !Object.prototype.hasOwnProperty.call(captured,MARKET_SPOT_PROXY.mes))keys.push(MARKET_SPOT_PROXY.mes);
  return keys.filter(function(k){
    var m=names.indexOf(k.slice(0,3));return m>=0&&(/^\d{2}$/.test(k.slice(3)));
  }).sort(function(a,b){return (2000+Number(a.slice(3)))*12+names.indexOf(a.slice(0,3))-(2000+Number(b.slice(3)))*12-names.indexOf(b.slice(0,3));});
}
function renderMarketCurve(){
  // Garante state.cbot e state.dolar
  if(!state.cbot) state.cbot = {...CBOT_DEFAULT};
  if(!state.cbotMilho) state.cbotMilho = {...CBOT_MILHO_DEFAULT};
  if(!state.curvaMilho) state.curvaMilho = {};
  if(!state.dolar) state.dolar = {...DOLAR_DEFAULT};
  const cbotStore = state.cbot || {};
  const cbotDefaultStore = CBOT_DEFAULT;

  // Badges de freshness no topo
  const freshBox = document.getElementById('mercadoFreshness');
  if(freshBox){
    freshBox.innerHTML =
      freshnessBadge('cbot', 'CBOT') +
      freshnessBadge('dolar', 'Dólar') +
      freshnessBadge('fobbins', 'Fobbins/Sea');
  }

  // Todas as subcurvas sao lidas do estado vigente; nenhum prazo depende de lista estatica.
  var curveTables=[
    {key:'cbot',id:'cbotBody',title:'CBOT Soja',step:'0.125'},
    {key:'cbotMilho',id:'cbotMilhoBody',title:'CBOT Milho',step:'0.125'},
    {key:'cbotFarelo',id:'cbotFareloBody',title:'CBOT Farelo',step:'0.1'},
    {key:'cbotOleo',id:'cbotOleoBody',title:'CBOT Óleo',step:'0.01'}
  ];
  var monthText={F:'Jan',G:'Fev',H:'Mar',J:'Abr',K:'Mai',M:'Jun',N:'Jul',Q:'Ago',U:'Set',V:'Out',X:'Nov',Z:'Dez'};
  curveTables.forEach(function(spec){
    var body=document.getElementById(spec.id);if(!body)return;
    var store=state[spec.key]||{},snap=(MARKET_SNAPSHOT&&MARKET_SNAPSHOT[spec.key])||{};
    body.innerHTML=brzMercadoVencimentos(spec.key).map(function(v){
      var val=store[v],fromOld=!Object.prototype.hasOwnProperty.call(snap,v);
      var month=monthText[v.slice(0,1)]+'/'+v.slice(1);
      return '<tr><th>'+v+(fromOld?' <small title="Ultima leitura historica, nao atualizada na captura C5/C4" style="color:var(--muted);font-weight:400">Hist.</small>':'')+'</th>'+
        '<td style="text-align:left;font-size:11px;color:var(--muted)">'+month+'</td>'+
        '<td><input type="number" step="'+spec.step+'" data-venc="'+v+'" data-curva="'+spec.key+'" value="'+(val!=null?val:'')+'" placeholder="—"></td></tr>';
    }).join('');
  });
  var dolarBody=document.getElementById('dolarBody');
  if(dolarBody){dolarBody.innerHTML=brzMercadoDolarMeses().map(function(k){
    var val=(state.dolar||{})[k];
    var proxy=state.dolarProxies&&state.dolarProxies[k];
    var tag=proxy?' <small style="display:block;font-weight:700;color:var(--amber);font-size:10px" title="USD/BRL spot 30/10 às 17h; não é cotação DOLX26 da B3">PROXY SPOT · NÃO B3</small>':(k==='Out28'&&MARKET_SNAPSHOT_ID.startsWith('2026-11-03')?' <small style="display:block;font-weight:700;color:var(--amber);font-size:10px" title="Último valor B3 de 30/10, não recebeu cotação 03/11">ÚLTIMA 30/10 · NÃO ATUALIZADA</small>':'');
    return '<tr><th>'+k.slice(0,3)+'/'+k.slice(3)+tag+'</th><td><input type="number" step="0.0001" data-mes="'+k+'" data-curva="dolar" value="'+(val!=null?val:'')+'" placeholder="—"'+(proxy?' title="Proxy USD/BRL spot 5,4571, 30/10/2026 17:00:01; não representa DOLX26 negociado"':'')+'></td></tr>';
  }).join('');}
  var notice=document.getElementById('brzProxyFxNotice');
  if(notice){
    var proxyActive=state.dolarProxies&&state.dolarProxies.Nov26;
    notice.textContent=proxyActive?
      'Nov/26: R$ 5,4571 é proxy do USD/BRL comercial spot de 30/10 às 17h. Não é preço negociado DOLX26, PTAX ou liquidação. Dez/26: DOLZ26 B3 R$ 5,4775. Negócios históricos permanecem travados.':
      '03/11 C3: DOLX26 ausente, sem proxy spot atual. DOLZ26 B3 R$ 5,5235; DOLF27 B3 R$ 5,5530. Ago28/Set28 são C1 de 03/11 e Out28 é 30/10 (carry-forward não atualizado na C3). Negócios históricos preservados.';
  }

  // Globais
  const gf = document.getElementById('globalFobbins');
  const gs = document.getElementById('globalSea');
  if(gf) gf.value = state.fobbins ?? FOBBINS_DEFAULT;
  if(gs) gs.value = state.seaFreight ?? SEA_FREIGHT_DEFAULT;
  try{ renderSeaMatrixHint(); }catch(e){}
}

function seaMatrixInfo(){
  try{
    const ofp = state.oceanFreightPorto; if(!ofp) return null;
    const days = Object.keys(ofp).filter(k=>/^\d{4}-\d{2}-\d{2}$/.test(k)).sort();
    if(!days.length) return null;
    const day = days[days.length-1];
    const dest = Object.keys(ofp[day])[0]; if(!dest) return null;
    const tbl = ofp[day][dest]; const vals=[];
    Object.keys(tbl).forEach(p=>{ if(p==='Paranagua') return; const t=tbl[p]; Object.keys(t).forEach(v=>{ if(typeof t[v]==='number') vals.push(t[v]); }); });
    if(!vals.length) return null;
    vals.sort((a,b)=>a-b);
    const med = vals.length%2 ? vals[(vals.length-1)/2] : (vals[vals.length/2-1]+vals[vals.length/2])/2;
    return {day, dest, med: Math.round(med*10)/10, n: vals.length};
  }catch(e){ return null; }
}
function renderSeaMatrixHint(){
  const el = document.getElementById('seaMatrixHint'); if(!el) return;
  const inf = seaMatrixInfo();
  if(!inf){ el.innerHTML='sem matriz por porto \u00b7 este valor \u00e9 usado direto'; return; }
  const cur = n(document.getElementById('globalSea')?.value);
  const diff = cur ? Math.round((inf.med-cur)*10)/10 : null;
  el.innerHTML = 'matriz por porto ATIVA ('+inf.day+') \u00b7 mediana '+String(inf.med).replace('.',',')+' US$/t'
    +(diff!==null&&Math.abs(diff)>=3?' <span style="color:#b91c1c;font-weight:700">\u0394 '+(diff>0?'+':'')+String(diff).replace('.',',')+' vs fallback</span>':'')
    +' \u00b7 <a href="#" onclick="var i=seaMatrixInfo(); if(i){document.getElementById(\'globalSea\').value=i.med; renderSeaMatrixHint();} return false" style="color:var(--teal,#0d9488);font-weight:600">usar mediana</a>'
    +' \u00b7 rotas usam a matriz; este campo \u00e9 s\u00f3 fallback';
}
function saveMarketCurve(){
  if(!state.cbot) state.cbot = {};
  if(!state.cbotMilho) state.cbotMilho = {};
  if(!state.curva) state.curva = {};
  if(!state.curvaMilho) state.curvaMilho = {};
  if(!state.dolar) state.dolar = {};

  [['cbot','cbotBody'],['cbotMilho','cbotMilhoBody'],['cbotFarelo','cbotFareloBody'],['cbotOleo','cbotOleoBody']].forEach(function(p){
    if(!state[p[0]])state[p[0]]={};
    document.querySelectorAll('#'+p[1]+' input[data-curva="'+p[0]+'"]').forEach(function(inp){
      var value=inp.value.trim();state[p[0]][inp.dataset.venc]=value===''?null:Number(value);
    });
  });
  document.querySelectorAll('#dolarBody input[data-curva="dolar"]').forEach(function(inp){
    var value=inp.value.trim(),k=inp.dataset.mes,newVal=value===''?null:Number(value);
    // Uma alteração manual no vencimento estimado revoga seu rótulo de proxy original.
    if(state.dolarProxies&&state.dolarProxies[k]&&newVal!==state.dolarProxies[k].taxa)delete state.dolarProxies[k];
    state.dolar[k]=newVal;
  });
  state.fobbins = n(document.getElementById('globalFobbins')?.value) || FOBBINS_DEFAULT;
  state.seaFreight = n(document.getElementById('globalSea')?.value) || SEA_FREIGHT_DEFAULT;

  // Nao apagar vencimentos nao exibidos: legados e 2028 fazem parte do historico.
  Object.keys(state.cbot).forEach(function(v){
    var curve=(state.curva[v]=state.curva[v]||{});
    curve.cbot=state.cbot[v]||0;
    curve.cambio=state.dolar[CBOT_TO_DOLAR_MES[v]]||0;
    curve.fobbins=state.fobbins;curve.seaFreight=state.seaFreight;
  });
  Object.keys(state.cbotMilho).forEach(function(v){
    var curve=(state.curvaMilho[v]=state.curvaMilho[v]||{});
    curve.cbot=state.cbotMilho[v]||0;
    curve.cambio=state.dolar[CBOT_TO_DOLAR_MES[v]]||0;
    curve.fobbins=state.fobbins;curve.seaFreight=0;
  });

  setCurveTimestamp('cbot');
  setCurveTimestamp('dolar');
  setCurveTimestamp('fobbins');

  persist();
  renderAll();
  alert('Curvas salvas. Soja, milho, farelo, óleo e dólar sincronizados com a paridade de exportação.');
}

/* ═══════════════════════════════════════════════════════
   FRETES
═══════════════════════════════════════════════════════ */
var afOrigemSel=null;
function setAfOrigem(o){ afOrigemSel=o; renderAnaliseFrete(); }
function renderAnaliseFrete(){
  var body=document.getElementById('analiseFreteBody'); if(!body) return;
  var portos=['Santos','Paranaguá','Itaqui','Barcarena'];
  var fv=state.fretesRodo.filter(function(f){return portos.indexOf(f.destino)>=0 && f.semana;});
  var hist={}, wc={};
  fv.forEach(function(f){ wc[f.semana]=(wc[f.semana]||0)+1; (hist[f.origem]=hist[f.origem]||{}); (hist[f.origem][f.destino]=hist[f.origem][f.destino]||{}); var pp=hist[f.origem][f.destino][f.semana]; hist[f.origem][f.destino][f.semana]=(pp==null)?f.valor:Math.min(pp,f.valor); });
  var allWeeks=Object.keys(wc).sort(); var latest=allWeeks[allWeeks.length-1]||null;
  var denseWeeks=allWeeks.filter(function(w){return wc[w]>=100;});
  var prevDense=denseWeeks.length>=2?denseWeeks[denseWeeks.length-2]:(allWeeks.length>=2?allWeeks[allWeeks.length-2]:null);

  // P1: frete % do replacement FOB
  var prod=(typeof getActiveProduto==='function')?getActiveProduto():'Soja'; var p1rows=[];
  try{
    var precos=getPrecosBase().filter(function(d){return normalizeProduto(d.produto)===prod && d.cbot && d.cambio;});
    var datas=Object.keys(precos.reduce(function(a,d){a[d.data]=1;return a;},{})).sort(); var dCur=datas[datas.length-1];
    var cur=precos.filter(function(d){return d.data===dCur;}); var agg={};
    cur.forEach(function(d){ var pc; try{pc=computePortComparison(d);}catch(e){return;} var bp=pc.bestPort,best=null; (pc.results||[]).forEach(function(r){if(r.porto===bp)best=r.best;}); if(!best||!best.replacementFOB||best._freightCbu==null) return; var share=best._freightCbu/best.replacementFOB*100; (agg[d.origem]=agg[d.origem]||{shares:[],frete:best.freteTotal,porto:bp}); agg[d.origem].shares.push(share); });
    Object.keys(agg).forEach(function(o){ var s=agg[o].shares,avg=s.reduce(function(a,b){return a+b;},0)/s.length; p1rows.push({origem:o,porto:agg[o].porto,frete:agg[o].frete,share:avg}); });
    p1rows=p1rows.filter(function(r){return r.share>0.5;}); p1rows.sort(function(a,b){return b.share-a.share;});
  }catch(e){ p1rows=[]; }
  var p1max=p1rows.length?Math.max.apply(null,p1rows.map(function(r){return Math.abs(r.share);})):1;
  var p1html=p1rows.slice(0,20).map(function(r){ var w=Math.max(2,Math.abs(r.share)/p1max*100); return '<div style="display:flex;align-items:center;gap:8px;margin-bottom:5px;font-size:11.5px"><div style="width:150px;flex:none;color:var(--navy-ink);font-weight:600;white-space:nowrap;overflow:hidden;text-overflow:ellipsis">'+r.origem+'</div><div style="flex:1;background:var(--g100);border-radius:4px;height:18px;position:relative"><div style="width:'+w.toFixed(1)+'%;height:100%;background:var(--teal);border-radius:4px"></div></div><div style="width:130px;flex:none;text-align:right;color:var(--g700)"><b>'+r.share.toFixed(1)+'%</b> <span class="a-mut" style="font-size:10px">R$'+money(r.frete)+' \u00b7 '+String(r.porto).slice(0,4)+'</span></div></div>'; }).join('') || '<div class="a-mut" style="font-size:12px">sem dados de pre\u00e7os para o produto ativo</div>';

  // P2: volatilidade CV%
  var volRows=[];
  Object.keys(hist).forEach(function(o){ portos.forEach(function(p){ var h=hist[o][p]; if(!h) return; var ws=Object.keys(h).sort(); var rec=ws.slice(-26).map(function(s){return h[s];}); if(rec.length<4) return; var mean=rec.reduce(function(a,b){return a+b;},0)/rec.length; if(mean<=0) return; var sd=Math.sqrt(rec.reduce(function(a,b){return a+(b-mean)*(b-mean);},0)/rec.length); volRows.push({rota:o+' \u2192 '+p,cv:sd/mean*100,n:rec.length,min:Math.min.apply(null,rec),max:Math.max.apply(null,rec)}); }); });
  volRows.sort(function(a,b){return b.cv-a.cv;});
  var volHtml='<table class="a-table" style="font-size:11.5px"><thead><tr><th>Rota</th><th class="r">CV%</th><th class="r">M\u00edn\u2013M\u00e1x</th><th class="r">sem</th></tr></thead><tbody>'+volRows.slice(0,15).map(function(r){return '<tr><td>'+r.rota+'</td><td class="r"><b>'+r.cv.toFixed(1)+'%</b></td><td class="r">'+money(r.min)+'\u2013'+money(r.max)+'</td><td class="r a-mut">'+r.n+'</td></tr>';}).join('')+'</tbody></table>';

  // P3: spread entre portos no tempo
  var origensMulti=Object.keys(hist).filter(function(o){return Object.keys(hist[o]).length>=2;}).sort();
  if(!afOrigemSel || origensMulti.indexOf(afOrigemSel)<0) afOrigemSel=origensMulti[0]||null;
  var spreadSel='<select onchange="setAfOrigem(this.value)">'+origensMulti.map(function(o){return '<option value="'+String(o).replace(/"/g,'')+'"'+(o===afOrigemSel?' selected':'')+'>'+o+'</option>';}).join('')+'</select>';
  var spreadHtml='';
  if(afOrigemSel){
    var H3=hist[afOrigemSel]; var wkUni={}; portos.forEach(function(p){ if(H3[p]) Object.keys(H3[p]).forEach(function(s){wkUni[s]=1;}); });
    var wks=Object.keys(wkUni).sort().slice(-10).reverse();
    spreadHtml='<table class="a-table" style="font-size:11.5px"><thead><tr><th>Semana</th>'+portos.map(function(p){return '<th class="r">'+p.slice(0,4)+'</th>';}).join('')+'<th class="r">Spread</th><th>Melhor</th></tr></thead><tbody>'+wks.map(function(s){ var vals={},best=Infinity,bestP=null,pres=[]; portos.forEach(function(p){ var r=(H3[p]&&_valAsOf(H3[p],s)); if(r){vals[p]=r.valor;pres.push(r.valor); if(r.valor<best){best=r.valor;bestP=p;}} }); var spr=pres.length>=2?(Math.max.apply(null,pres)-Math.min.apply(null,pres)):null; return '<tr><td class="a-mut">'+s+'</td>'+portos.map(function(p){return '<td class="r"'+(p===bestP?' style="color:var(--teal);font-weight:700"':'')+'>'+(vals[p]!=null?money(vals[p]):'\u00b7')+'</td>';}).join('')+'<td class="r"><b>'+(spr!=null?money(spr):'\u00b7')+'</b></td><td class="a-mut">'+(bestP||'\u00b7')+'</td></tr>'; }).join('')+'</tbody></table>';
  } else spreadHtml='<div class="a-mut" style="font-size:12px">sem origem com 2+ portos</div>';

  // P4: troca de melhor porto
  var switches=[];
  if(prevDense&&latest){ Object.keys(hist).forEach(function(o){ var H4=hist[o]; var bestAt=function(wk){var b=Infinity,bp=null; portos.forEach(function(p){var r=H4[p]&&_valAsOf(H4[p],wk); if(r&&r.valor<b){b=r.valor;bp=p;}}); return bp;}; var a=bestAt(prevDense),b=bestAt(latest); if(a&&b&&a!==b) switches.push({origem:o,de:a,para:b}); }); }
  var switchHtml=switches.length?('<div style="font-size:11.5px">'+switches.map(function(s){return '<div style="padding:4px 0;border-bottom:1px solid var(--g100)"><b>'+s.origem+'</b>: '+s.de+' \u2192 <span style="color:var(--teal);font-weight:700">'+s.para+'</span></div>';}).join('')+'</div>'):'<div class="a-mut" style="font-size:12px">nenhuma troca entre '+(prevDense||'\u2014')+' e '+(latest||'\u2014')+'</div>';

  // P5: staleness
  var wkIndex={}; allWeeks.forEach(function(w,i){wkIndex[w]=i;}); var latIdx=allWeeks.length-1; var stale=[],encerradas=0; Object.keys(hist).forEach(function(o){ portos.forEach(function(p){ var h=hist[o][p]; if(!h) return; var ws=Object.keys(h).sort(); var last=ws[ws.length-1]; var behind=latIdx-(wkIndex[last]||0); if(behind>26){ encerradas++; } else if(behind>=3) stale.push({rota:o+' \u2192 '+p,ultima:last,atras:behind}); }); });
  stale.sort(function(a,b){return b.atras-a.atras;});
  var staleHtml=stale.length?('<table class="a-table" style="font-size:11.5px"><thead><tr><th>Rota</th><th>\u00daltima</th><th class="r">sem atr\u00e1s</th></tr></thead><tbody>'+stale.slice(0,20).map(function(r){return '<tr><td>'+r.rota+'</td><td class="a-mut">'+r.ultima+'</td><td class="r"><b style="color:'+(r.atras>=8?'#DC2626':'#D97706')+'">'+r.atras+'</b></td></tr>';}).join('')+'</tbody></table>'+(stale.length>20?'<div class="a-mut" style="font-size:11px;margin-top:4px">+'+(stale.length-20)+' rotas</div>':'')+(encerradas?'<div class="a-mut" style="font-size:10.5px;margin-top:4px">'+encerradas+' rotas hist\u00f3ricas encerradas (>26 sem) ocultas</div>':'')):'<div class="a-mut" style="font-size:12px">todas atualizadas nas \u00faltimas 3 semanas</div>';

  body.style.padding='0';
  body.innerHTML=''
    +'<div class="section"><div class="sec-title">Frete % do replacement FOB<span class="sec-sub">'+prod+' \u00b7 por origem \u00b7 top 20</span></div><div style="padding:4px 2px">'+p1html+'</div><div class="a-mut" style="font-size:10.5px;margin-top:6px">% = frete (\u00a2/bu) \u00f7 FOB de reposi\u00e7\u00e3o flat (\u00a2/bu) no melhor porto. Maior = log\u00edstica pesa mais na conta.</div></div>'
    +'<div class="a-grid2">'
      +'<div class="section"><div class="sec-title">Ranking de volatilidade<span class="sec-sub">CV% \u00b7 at\u00e9 26 sem \u00b7 top 15</span></div>'+volHtml+'</div>'
      +'<div class="section"><div class="sec-title">Troca de melhor porto<span class="sec-sub">'+(prevDense||'\u2014')+' \u2192 '+(latest||'\u2014')+'</span></div>'+switchHtml+'</div>'
    +'</div>'
    +'<div class="section"><div class="sec-title">Spread entre portos no tempo<span class="sec-sub">por origem \u00b7 \u00faltimas 10 sem</span> '+spreadSel+'</div>'+spreadHtml+'</div>'
    +'<div class="section"><div class="sec-title">Staleness<span class="sec-sub">rotas ativas sem update h\u00e1 3+ sem</span></div>'+staleHtml+'</div>';
}

/* ===== Sub-aba: Análise Diária — frete & originação (v3, pele Reposição) ===== */
var briefCmp=1, briefMetric='basisCFR';


/* ===== Sub-aba: Análise Diária — Dashboard de Frete & Originação (v4, dados reais aBestRoute/aAllRoutes) ===== */
var fdS={mar:0,int:0,camb:5.20,cbot:1120}, fdBase={mar:0,int:0,camb:5.20,cbot:1120};
var fdSelEmb=null, fdSelPort=null, fdModel=null, fdRefDate='', fdRefDatePrev=null, fdModelCache={};
