  var wk=[]; if(deals.length){
    var w0=new Date(D.hoje+'T00:00:00'); var dow=(w0.getDay()+6)%7; w0.setDate(w0.getDate()-dow); // segunda da semana atual
    for(var i=7;i>=0;i--){ var st=new Date(w0.getTime()); st.setDate(st.getDate()-7*i);
      var en=new Date(st.getTime()); en.setDate(en.getDate()+6);
      var s=st.toISOString().slice(0,10), e=en.toISOString().slice(0,10);
      var vol=0,n=0; deals.forEach(function(x){ if(x.data>=s&&x.data<=e){ vol+=x.vol; n++; } });
      wk.push({lb:s.slice(8)+'/'+s.slice(5,7),vol:vol,n:n});
    }
  }
  var med=wk.length?wk.slice(0,7).reduce(function(s,w){return s+w.vol;},0)/7:0;
  var ult=wk.length?wk[wk.length-1].vol:0;
  var sub3=wk.length?('\u00faltima semana '+(ult>=1000?(Math.round(ult/100)/10)+'k':Math.round(ult))+' t'+(med>0?(' \u00b7 '+(ult>=med?'+':'')+Math.round((ult-med)/med*100)+'% vs m\u00e9dia 7 semanas'):'')):'';
  var g3=brzSvgWeeks(wk,470,160);
  // ── estrutura por embarque ──
  var eb={}; deals.forEach(function(x){ var o=(eb[x.emb]=eb[x.emb]||{vol:0,w:0,v:0}); o.vol+=x.vol; o.w+=x.bas*x.vol; o.v+=x.vol; });
  var rows=Object.keys(eb).map(function(e){ return {emb:e,vol:eb[e].vol,bas:eb[e].v?eb[e].w/eb[e].v:null}; });
  try{ rows.sort(function(a,b){return aVencKey(a.emb)-aVencKey(b.emb);}); }catch(e){}
  var topE=rows.slice().sort(function(a,b){return b.vol-a.vol;})[0];
  var volT=deals.reduce(function(s,x){return s+x.vol;},0);
