function setFreightSubTab(t){
  freightTab = t;
  // Atualiza tabs visuais
  document.querySelectorAll('#fretesTabsBar .tab').forEach(x=>x.classList.remove('active'));
  const tabBtn = document.getElementById('fTab-'+t);
  if(tabBtn) tabBtn.classList.add('active');

  // Mostra/esconde os 4 wrappers de conteúdo
  ['rodo','buscar','ferro','ocean','inland','indices','series','sazonal','arbns','analise','brief'].forEach(k => {
    let elId;
    if(k==='rodo' || k==='ferro' || k==='buscar') elId = 'fretesTabContent-'+k;
    else if(k==='ocean') elId = 'oceanFreightBody';
    else if(k==='inland') elId = 'inlandFreightBody'; else if(k==='indices') elId = 'indicesFreteBody'; else if(k==='series') elId = 'seriesFreteBody'; else if(k==='sazonal') elId = 'sazonalFreteBody'; else if(k==='arbns') elId = 'arbNSBody';
    else if(k==='analise') elId = 'analiseFreteBody'; else elId = 'briefFreteBody';
    const el = document.getElementById(elId);
    if(el) el.style.display = (k===t) ? 'block' : 'none';
  });

  // Toolbar dinâmica
  const toolbar = document.getElementById('fretesToolbar');
  if(toolbar){
    if(t==='rodo'){
      toolbar.innerHTML = `
        <button class="btn primary" onclick="openFreightDrawer()">+ Frete Rodo</button>
        <button class="btn" onclick="exportCSV('fretesRodo')">CSV</button>`;
    } else if(t==='buscar'){
      toolbar.innerHTML = '';
    } else if(t==='ferro'){
      toolbar.innerHTML = `<button class="btn" onclick="exportCSV('fretesFerro')">CSV</button>`;
    } else if(t==='ocean'){
      toolbar.innerHTML = `
        <button class="btn primary" onclick="saveOceanFreight()">Salvar Matriz</button>
        <button class="btn" onclick="resetOceanFreight()">↻ Restaurar Default</button>`;
    } else if(t==='indices'){ toolbar.innerHTML = '<button class="btn primary" onclick="brzReportStudio()">Report</button>'; } else if(t==='inland' || t==='analise' || t==='brief' || t==='series' || t==='sazonal' || t==='arbns'){ toolbar.innerHTML = ''; }
  }

  // Renderiza conteúdo da aba ativa
  if(t==='buscar'){
    setupBuscarFreteUI();
    renderBuscarFrete();
  } else if(t==='rodo' || t==='ferro'){
    if(t==='rodo' && rodoCompareMode){
      const tbl = document.getElementById('rodoTable');
      const cmp = document.getElementById('rodoCompareWrap');
      if(tbl) tbl.style.display = 'none';
      if(cmp) cmp.style.display = 'block';
    }
    renderFreights();
  } else if(t==='ocean'){
    renderOceanFreight();
  } else if(t==='inland'){ renderInlandFreight(); } else if(t==='indices'){ renderIndicesFrete(); } else if(t==='series'){ renderSeriesFrete(); } else if(t==='sazonal'){ renderSazonalFrete(); } else if(t==='arbns'){ renderArbNS(); } else if(t==='analise'){
    renderAnaliseFrete();
  } else if(t==='brief'){
    renderBriefFrete();
  }
}

