/* ═══ BUSCAR FRETE: consulta operacional por origem/destino ═══ */
var buscarFreteChartBrush = null;  // {start:0,end:1} — filtro de período visível no gráfico de frete
var buscarFreteBrushDrag = null;
function safeHtml(v){
  return String(v ?? '').replace(/[&<>"]/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c]));
}
function normalizeTextBR(v){
  return String(v||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().replace(/[^a-z0-9]+/g,' ').trim();
}
function latestRodoWeek(){
  return [...new Set((state.fretesRodo||[]).map(f=>f.semana).filter(Boolean))].sort().reverse()[0] || '';
}
let _candidateOriginsCache = null;
function getBuscarFreteCandidateOrigins(){
  if(_candidateOriginsCache) return _candidateOriginsCache;
  const set = new Set();
  (state.fretesRodo||[]).forEach(f=>{ if(f.origem) set.add(f.origem); });
  Object.keys(CITY_COORDS||{}).forEach(k=>{ if(!k.startsWith('_')) set.add(k); });
  _candidateOriginsCache = [...set].sort((a,b)=>a.localeCompare(b,'pt-BR'));
  return _candidateOriginsCache;
}
function setupBuscarFreteUI(){
  const destSel = document.getElementById('buscarFreteDestino');
  const semSel = document.getElementById('buscarFreteSemana');
  const list = document.getElementById('buscarFreteOrigemList');
  if(destSel){
    const atual = destSel.value || '';
    const main = ['Santos','Paranaguá','Barcarena','São Luis','Itaqui','Miritituba','Aratu','Ilhéus','Barra dos Coqueiros','São Francisco do Sul','Imbituba','Rio Grande'];
    const all = [...new Set((state.fretesRodo||[]).map(f=>f.destino).filter(Boolean))];
    const destinos = [...main.filter(d=>all.some(x=>normalizeTextBR(x)===normalizeTextBR(d))), ...all.filter(d=>!main.some(m=>normalizeTextBR(m)===normalizeTextBR(d))).sort((a,b)=>a.localeCompare(b,'pt-BR'))];
    destSel.innerHTML = `<option value="">Selecione o destino/porto</option>` + destinos.map(d=>`<option value="${safeHtml(d)}">${safeHtml(d)}</option>`).join('');
    if(atual && destinos.includes(atual)) destSel.value = atual;
  }
  if(semSel){
    const atual = semSel.value || '';
    const semanas = [...new Set((state.fretesRodo||[]).map(f=>f.semana).filter(Boolean))].sort().reverse();
    semSel.innerHTML = `<option value="">Semana mais recente</option>` + semanas.map(s=>`<option value="${safeHtml(s)}">${safeHtml(s)}</option>`).join('');
    if(atual && semanas.includes(atual)) semSel.value = atual;
  }
  if(list){
    list.innerHTML = getBuscarFreteCandidateOrigins().map(o=>`<option value="${safeHtml(o)}"></option>`).join('');
  }
}
function clearBuscarFrete(){
  const origem = document.getElementById('buscarFreteOrigem');
  const destino = document.getElementById('buscarFreteDestino');
  const semana = document.getElementById('buscarFreteSemana');
  if(origem) origem.value = '';
  if(destino) destino.value = '';
  if(semana) semana.value = '';
  buscarFreteChartBrush = null;
  renderBuscarFrete();
}
function getFreteRodoReference(origem, destino, semana){
  const normOrig = normalizeTextBR(extractCidadeBase(origem) || origem);
  const normDest = normalizeTextBR(destino);
  let pool = (state.fretesRodo||[]).filter(f => normalizeTextBR(extractCidadeBase(f.origem)||f.origem) === normOrig && normalizeTextBR(f.destino) === normDest);
  if(!pool.length) return null;
  pool.sort((a,b)=>String(b.semana).localeCompare(String(a.semana)));
  if(semana){
    const exact = pool.find(f=>f.semana === semana);
    if(exact) return {...exact, origemRef: exact.origem, tipoBusca:'Frete cadastrado'};
    const before = pool.find(f=>String(f.semana) < String(semana));
    if(before) return {...before, origemRef: before.origem, tipoBusca:'Frete cadastrado · semana anterior'};
  }
  const latest = pool[0];
  return {...latest, origemRef: latest.origem, tipoBusca:'Frete cadastrado'};
}
let _closestRefCache = new Map();
let _candidateRefsCache = null;
function getCandidateRefsResolved(){
  if(_candidateRefsCache) return _candidateRefsCache;
  const seen = new Set(); const out = [];
  getBuscarFreteCandidateOrigins().forEach(refOrig=>{
    const cidadeRef = extractCidadeBase(refOrig)||refOrig;
    const nk = normalizeTextBR(cidadeRef);
    if(seen.has(nk)) return; seen.add(nk);
    const coordRef = getCityCoord(cidadeRef);
    if(!coordRef) return;
    out.push({origem:refOrig, cidadeKey:freightCityFromOrigem(refOrig), coord:coordRef});
  });
  _candidateRefsCache = out;
  return out;
}
function getClosestFreightReferences(origem, destino, semana, corredor){
  const cidade = extractCidadeBase(origem) || origem;
  let coordOrig = getCityCoord(cidade);
  if(!coordOrig && corredor && typeof MAP_DATA!=='undefined' && MAP_DATA.corredores && MAP_DATA.corredores[corredor]) coordOrig = MAP_DATA.corredores[corredor];
  if(!coordOrig){ var _uf = String(origem||'').match(/[-\/]\s*([A-Z]{2})\b/); if(_uf && UF_COORDS[_uf[1]]) coordOrig = UF_COORDS[_uf[1]]; }
  if(!coordOrig) return [];
  const latestWeek = semana || latestRodoWeek();
  const memoKey = String(origem) + '|' + destino + '|' + latestWeek + '|' + (corredor||'');
  if(_closestRefCache.has(memoKey)) return _closestRefCache.get(memoKey);
  const idx = ensureFreightRodoIndex();
  const kmPorto = estimateDistanceKm(origem, destino);
  const tku = getTkuMedioPorPorto()[destino] || 0.30;
  const candidates = [];
  getCandidateRefsResolved().forEach(c=>{
    const arr = idx.byKey.get(destino + '|' + c.cidadeKey);
    if(!arr || !arr.length) return;
    const match = latestWeek ? (arr.find(f=>weekCompare(f.semana, latestWeek) <= 0) || arr[0]) : arr[0];
    if(!match) return;
    /* 09/11/2026: referência vizinha também precisa ser recente (mesmo limite da rota exata, frete.rodoSemana.maxSemanasAtras) */
    if(latestWeek){ const _mx=Number((typeof brzRegraParam==='function')?brzRegraParam('frete.rodoSemana','maxSemanasAtras',8):8); const _id=weeksBetweenIso(match.semana, latestWeek); if(Number.isFinite(_mx) && _mx>0 && Number.isFinite(_id) && _id>_mx) return; }
    candidates.push({
      origemRef: match.origem || c.origem,
      destino,
      valor: (kmPorto ? kmPorto * tku : null),
      semana: match.semana || latestWeek,
      tipoBusca: 'TKU estimado',
      kmPorto, tku,
      kmReferencia: haversineKm(coordOrig, c.coord) || 0,
      freteRefValor: match.valor
    });
  });
  const result = candidates.sort((a,b)=>a.kmReferencia-b.kmReferencia).slice(0,3);
  _closestRefCache.set(memoKey, result);
  return result;
}
function getFreteRodoHistory(origem, destino){
  const normOrig = normalizeTextBR(extractCidadeBase(origem) || origem);
  const normDest = normalizeTextBR(destino);
  const pool = (state.fretesRodo||[]).filter(f => normalizeTextBR(extractCidadeBase(f.origem)||f.origem) === normOrig && normalizeTextBR(f.destino) === normDest);
  return pool.slice().sort((a,b)=>String(a.semana).localeCompare(String(b.semana)));
}
function getBestReferenceOriginForHistory(origem, destino, semana){
  const refs = getClosestFreightReferences(origem, destino, semana || latestRodoWeek());
  return refs && refs.length ? refs[0].origemRef : '';
}
function getEstimatedTkuHistory(origem, destino, semana){
  const refOrig = getBestReferenceOriginForHistory(origem, destino, semana);
  if(!refOrig) return {refOrig:'', rows:[]};
  const refHist = getFreteRodoHistory(refOrig, destino);
  const kmOrigPort = estimateDistanceKm(origem, destino);
  const kmRefPort = estimateDistanceKm(refOrig, destino);
  if(!kmOrigPort || !kmRefPort || !refHist.length) return {refOrig, rows:[]};
  const rows = refHist.map(f=>{
    const tku = n(f.valor) / kmRefPort;
    return {
      semana: f.semana,
      valor: kmOrigPort * tku,
      tipo: 'TKU estimado',
      origemRef: refOrig,
      freteRefValor: f.valor,
      tku
    };
  });
  return {refOrig, rows};
}
function buildBuscarFreteHistory(origem, destino, semana){
  if(!origem || !destino) return {tipo:'', origemRef:'', rows:[]};
  const exact = getFreteRodoHistory(origem, destino);
  if(exact.length){
    return {tipo:'Frete cadastrado', origemRef: exact[0].origem, rows: exact.map(f=>({semana:f.semana, valor:n(f.valor), tipo:'Frete cadastrado', origemRef:f.origem}))};
  }
  const est = getEstimatedTkuHistory(origem, destino, semana);
  return {tipo:'TKU estimado', origemRef: est.refOrig, rows: est.rows};
}
function formatWeekShort(w){
  const m = String(w||'').match(/^(\d{4})-S(\d{1,2})$/);
  return m ? `S${m[2]}/${String(m[1]).slice(2)}` : String(w||'');
}
function weekToDateLabel(w){
  const m = String(w||'').match(/^(\d{4})-S(\d{1,2})$/);
  if(!m) return '';
  const year = Number(m[1]);
  const week = Number(m[2]);
  const jan4 = new Date(Date.UTC(year, 0, 4));
  const jan4Day = jan4.getUTCDay() || 7;
  const monday = new Date(jan4);
  monday.setUTCDate(jan4.getUTCDate() - jan4Day + 1 + (week - 1) * 7);
  const dd = String(monday.getUTCDate()).padStart(2,'0');
  const mm = String(monday.getUTCMonth()+1).padStart(2,'0');
  const yy = String(monday.getUTCFullYear()).slice(2);
  return `${dd}/${mm}/${yy}`;
}

function resetBuscarFreteBrush(){
  buscarFreteChartBrush = null;
  renderBuscarFrete();
}
function clamp01(v){ return Math.max(0, Math.min(1, v)); }
function getBuscarFreteBrushFraction(ev){
  const el = document.querySelector('.buscar-frete-brush-control');
  if(!el) return 0;
  const rect = el.getBoundingClientRect();
  const clientX = ev.touches && ev.touches.length ? ev.touches[0].clientX : ev.clientX;
  return clamp01((clientX - rect.left) / Math.max(1, rect.width));
}
function startBuscarFreteBrushDrag(ev, mode, len){
  if(!len || len < 2) return;
  ev.preventDefault();
  ev.stopPropagation();
  const brush = buscarFreteChartBrush || {start:0, end:1};
  buscarFreteBrushDrag = {
    mode,
    len,
    startX: getBuscarFreteBrushFraction(ev),
    start: brush.start,
    end: brush.end
  };
  document.body.style.cursor = mode === 'body' ? 'grabbing' : 'ew-resize';
  window.addEventListener('mousemove', moveBuscarFreteBrushDrag);
  window.addEventListener('mouseup', endBuscarFreteBrushDrag);
  window.addEventListener('touchmove', moveBuscarFreteBrushDrag, {passive:false});
  window.addEventListener('touchend', endBuscarFreteBrushDrag);
}
function moveBuscarFreteBrushDrag(ev){
  if(!buscarFreteBrushDrag) return;
  ev.preventDefault();
  const d = buscarFreteBrushDrag;
  const fx = getBuscarFreteBrushFraction(ev);
  const delta = fx - d.startX;
  const minSpan = Math.min(0.08, 2 / Math.max(2, d.len - 1));
  let start = d.start;
  let end = d.end;
  if(d.mode === 'left'){
    start = clamp01(Math.min(end - minSpan, d.start + delta));
  }else if(d.mode === 'right'){
    end = clamp01(Math.max(start + minSpan, d.end + delta));
  }else{
    const span = end - start;
    start = clamp01(d.start + delta);
    end = start + span;
    if(end > 1){ end = 1; start = 1 - span; }
    if(start < 0){ start = 0; end = span; }
  }
  buscarFreteChartBrush = {start, end};
  renderBuscarFrete();
}
function endBuscarFreteBrushDrag(){
  buscarFreteBrushDrag = null;
  document.body.style.cursor = '';
  window.removeEventListener('mousemove', moveBuscarFreteBrushDrag);
  window.removeEventListener('mouseup', endBuscarFreteBrushDrag);
  window.removeEventListener('touchmove', moveBuscarFreteBrushDrag);
  window.removeEventListener('touchend', endBuscarFreteBrushDrag);
}
function renderBuscarFreteChart(origemRaw, destino, semana){
  const wrap = document.getElementById('buscarFreteChartWrap');
  if(!wrap) return;
  if(!destino || !origemRaw){
    wrap.innerHTML = `<div class="tc navy-bar" style="padding:16px 18px;background:var(--card)"><div class="tc-h">Comportamento histórico do frete</div><p>Selecione destino e origem para visualizar a evolução acumulada da praça/destino.</p></div>`;
    return;
  }
  const hist = buildBuscarFreteHistory(origemRaw, destino, semana);
  const rowsAll = (hist.rows||[]).filter(r=>isFinite(n(r.valor)) && n(r.valor)>0).sort((a,b)=>String(a.semana).localeCompare(String(b.semana)));
  if(!rowsAll.length){
    wrap.innerHTML = `<div class="tc amb-bar" style="padding:16px 18px;background:var(--card)"><div class="tc-h">Comportamento histórico do frete</div><p>Sem histórico suficiente para montar o gráfico dessa origem/destino.</p></div>`;
    return;
  }
  const baseRows = rowsAll.slice(-52);
  const activeBrush = buscarFreteChartBrush || {start:0, end:1};
  let startIdx = Math.floor(activeBrush.start * (baseRows.length - 1));
  let endIdx = Math.ceil(activeBrush.end * (baseRows.length - 1));
  startIdx = Math.max(0, Math.min(baseRows.length - 1, startIdx));
  endIdx = Math.max(startIdx, Math.min(baseRows.length - 1, endIdx));
  const rows = baseRows.slice(startIdx, endIdx + 1);
  const vals = rows.map(r=>n(r.valor));
  const first = vals[0], last = vals[vals.length-1];
  const min = Math.min(...vals), max = Math.max(...vals);
  const acc = last - first;
  const pct = first ? (acc/first)*100 : 0;
  const padL=48, padR=16, padT=18, padB=48, W=920, H=312;
  const yMin = Math.max(0, min - Math.max(8,(max-min)*0.15));
  const yMax = max + Math.max(8,(max-min)*0.15);
  const x = i => padL + (rows.length===1 ? (W-padL-padR)/2 : i*(W-padL-padR)/(rows.length-1));
  const y = v => H-padB - ((v-yMin)/(yMax-yMin || 1))*(H-padT-padB);
  const pts = rows.map((r,i)=>`${x(i).toFixed(1)},${y(n(r.valor)).toFixed(1)}`).join(' ');
  const areaPts = `${padL},${H-padB} ${pts} ${x(rows.length-1).toFixed(1)},${H-padB}`;
  const yTicks = [0,0.25,0.5,0.75,1].map(t=> yMin + (yMax-yMin)*t);
  const labelIdx = rows.length <= 10 ? rows.map((_,i)=>i) : [0, Math.floor(rows.length*.25), Math.floor(rows.length*.5), Math.floor(rows.length*.75), rows.length-1];
  const mW = 920, mH = 54, mPadX = 8, mPadY = 7;
  const baseVals = baseRows.map(r=>n(r.valor));
  const bMin = Math.min(...baseVals), bMax = Math.max(...baseVals);
  const bx = i => mPadX + (baseRows.length===1 ? (mW-2*mPadX)/2 : i*(mW-2*mPadX)/(baseRows.length-1));
  const by = v => mH-mPadY - ((v-bMin)/(bMax-bMin || 1))*(mH-2*mPadY);
  const miniPts = baseRows.map((r,i)=>`${bx(i).toFixed(1)},${by(n(r.valor)).toFixed(1)}`).join(' ');
  const brushStartPct = ((buscarFreteChartBrush?buscarFreteChartBrush.start:0)*100).toFixed(3);
  const brushEndPct = ((buscarFreteChartBrush?buscarFreteChartBrush.end:1)*100).toFixed(3);
  const brushWidthPct = (((buscarFreteChartBrush?buscarFreteChartBrush.end:1)-(buscarFreteChartBrush?buscarFreteChartBrush.start:0))*100).toFixed(3);
  const tipoTag = hist.tipo.includes('TKU') ? 'amber' : 'green';
  const fonte = hist.tipo.includes('TKU') ? `TKU estimado com referência em ${safeHtml(hist.origemRef || 'praça próxima')}` : `Frete real cadastrado para ${safeHtml(hist.origemRef || origemRaw)}`;
  const accCls = acc > 0 ? 'dn' : acc < 0 ? 'up' : 'amb';
  const accTxt = `${acc>=0?'+':''}${money(acc)} R$/t (${pct>=0?'+':''}${pct.toFixed(1).replace('.',',')}%)`;
  wrap.innerHTML = `
    <div class="tc navy-bar" style="padding:16px 18px;background:var(--card);margin-top:0">
      <div style="display:flex;justify-content:space-between;gap:14px;align-items:flex-start;flex-wrap:wrap;margin-bottom:12px">
        <div>
          <div class="tc-h" style="margin-bottom:4px">Comportamento histórico do frete</div>
          <p style="margin:0;color:var(--g500);font-size:12px">${safeHtml(origemRaw)} → ${safeHtml(destino)} · ${fonte}</p>
        </div>
        <span class="tag ${tipoTag}">${safeHtml(hist.tipo)}</span>
      </div>
      <div class="kpi-strip" style="margin-bottom:14px">
        <div class="kpi b"><div class="nm">Frete atual</div><div class="vl">R$ ${money(last)} <span class="un">/t</span></div><div class="ch" style="color:var(--g500);font-weight:600">${safeHtml(rows[rows.length-1].semana)}</div></div>
        <div class="kpi n"><div class="nm">Variação acumulada</div><div class="vl ${accCls}">${acc>=0?'+':''}${money(acc)} <span class="un">R$/t</span></div><div class="ch ${accCls}">${accTxt}</div></div>
        <div class="kpi g"><div class="nm">Mínima</div><div class="vl">R$ ${money(min)} <span class="un">/t</span></div><div class="ch" style="color:var(--g500);font-weight:600">últimas ${rows.length} semanas</div></div>
        <div class="kpi a"><div class="nm">Máxima</div><div class="vl">R$ ${money(max)} <span class="un">/t</span></div><div class="ch" style="color:var(--g500);font-weight:600">últimas ${rows.length} semanas</div></div>
      </div>
      <div style="width:100%;overflow-x:auto;border:1px solid var(--g200);border-radius:8px;background:var(--card);padding:8px 6px">
        <svg viewBox="0 0 ${W} ${H}" width="100%" height="312" role="img" aria-label="Histórico de frete">
          <defs>
            <linearGradient id="buscarFreteAreaGrad" x1="0" x2="0" y1="0" y2="1">
              <stop offset="0%" stop-color="var(--teal)" stop-opacity="0.18"/>
              <stop offset="100%" stop-color="var(--teal)" stop-opacity="0.02"/>
            </linearGradient>
          </defs>
          ${yTicks.map(v=>`<line x1="${padL}" x2="${W-padR}" y1="${y(v).toFixed(1)}" y2="${y(v).toFixed(1)}" stroke="var(--chart-grid)"/><text x="${padL-8}" y="${(y(v)+4).toFixed(1)}" text-anchor="end" font-size="10" fill="var(--g500)">R$ ${money(v)}</text>`).join('')}
          <line x1="${padL}" x2="${W-padR}" y1="${H-padB}" y2="${H-padB}" stroke="var(--g300)"/>
          <line x1="${padL}" x2="${padL}" y1="${padT}" y2="${H-padB}" stroke="var(--g300)"/>
          <polygon points="${areaPts}" fill="url(#buscarFreteAreaGrad)"/>
          <polyline points="${pts}" fill="none" stroke="var(--teal)" stroke-width="3" stroke-linecap="round" stroke-linejoin="round"/>
          ${rows.map((r,i)=>`<circle cx="${x(i).toFixed(1)}" cy="${y(n(r.valor)).toFixed(1)}" r="3.2" fill="var(--teal)"><title>${safeHtml(formatWeekShort(r.semana))}${weekToDateLabel(r.semana) ? ' · ' + safeHtml(weekToDateLabel(r.semana)) : ''} · R$ ${money(r.valor)}/t</title></circle>`).join('')}
          ${labelIdx.map(i=>`<text x="${x(i).toFixed(1)}" y="${H-26}" text-anchor="middle" font-size="10" fill="var(--g500)"><tspan x="${x(i).toFixed(1)}" dy="0">${safeHtml(formatWeekShort(rows[i].semana))}</tspan><tspan x="${x(i).toFixed(1)}" dy="13" fill="var(--g400)">${safeHtml(weekToDateLabel(rows[i].semana))}</tspan></text>`).join('')}
        </svg>
      </div>
      <div style="border:1px solid var(--g200);border-radius:8px;background:#F8FAFC;padding:7px 9px;margin-top:10px">
        <div style="display:flex;justify-content:space-between;gap:10px;align-items:center;margin-bottom:5px">
          <div style="font-size:10px;color:var(--g500);font-weight:700;letter-spacing:.6px;text-transform:uppercase">Período visível</div>
          <div style="font-size:10px;color:var(--g400);font-style:italic">Arraste a janela ou as laterais para filtrar o histórico do frete</div>
        </div>
        <div class="buscar-frete-brush-control" style="position:relative;height:54px;background:var(--card);border-radius:7px;overflow:hidden;cursor:grab;touch-action:none" onmousedown="startBuscarFreteBrushDrag(event,'body',${baseRows.length})" ontouchstart="startBuscarFreteBrushDrag(event,'body',${baseRows.length})">
          <svg viewBox="0 0 ${mW} ${mH}" width="100%" height="54" aria-label="Filtro de período do frete">
            <polyline points="${miniPts}" fill="none" stroke="var(--teal)" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" opacity=".85"/>
          </svg>
          <div style="position:absolute;left:0;top:0;bottom:0;width:${brushStartPct}%;background:rgba(241,245,249,.72);pointer-events:none"></div>
          <div style="position:absolute;left:${brushEndPct}%;top:0;bottom:0;width:${(100-Number(brushEndPct)).toFixed(3)}%;background:rgba(241,245,249,.72);pointer-events:none"></div>
          <div style="position:absolute;top:2px;bottom:2px;left:${brushStartPct}%;width:${brushWidthPct}%;border:2px solid var(--teal);background:rgba(13,148,136,.08);border-radius:5px;box-shadow:0 0 0 1px rgba(255,255,255,.75) inset;cursor:grab" onmousedown="startBuscarFreteBrushDrag(event,'body',${baseRows.length})" ontouchstart="startBuscarFreteBrushDrag(event,'body',${baseRows.length})">
            <div title="Arraste o início" style="position:absolute;left:-5px;top:-2px;bottom:-2px;width:10px;cursor:ew-resize;background:var(--teal);border-radius:4px;box-shadow:0 1px 4px rgba(0,0,0,.18)" onmousedown="startBuscarFreteBrushDrag(event,'left',${baseRows.length})" ontouchstart="startBuscarFreteBrushDrag(event,'left',${baseRows.length})"></div>
            <div title="Arraste o fim" style="position:absolute;right:-5px;top:-2px;bottom:-2px;width:10px;cursor:ew-resize;background:var(--teal);border-radius:4px;box-shadow:0 1px 4px rgba(0,0,0,.18)" onmousedown="startBuscarFreteBrushDrag(event,'right',${baseRows.length})" ontouchstart="startBuscarFreteBrushDrag(event,'right',${baseRows.length})"></div>
          </div>
        </div>
        <div style="display:flex;justify-content:space-between;align-items:center;margin-top:5px;font-size:10px;color:var(--g500)">
          <span>${formatWeekShort(baseRows[0].semana)} · ${weekToDateLabel(baseRows[0].semana)}</span>
          <button class="btn small" onclick="resetBuscarFreteBrush()">Resetar</button>
          <span>${formatWeekShort(baseRows[baseRows.length-1].semana)} · ${weekToDateLabel(baseRows[baseRows.length-1].semana)}</span>
        </div>
      </div>
      <div style="font-size:11px;color:var(--g500);margin-top:10px;line-height:1.45">Leitura: alta acumulada indica frete mais caro para essa praça/destino; queda acumulada indica melhora logística. Quando a rota não tem frete cadastrado, o gráfico usa TKU estimado a partir da referência mais próxima e da semana correspondente.</div>
    </div>`;
}

function renderBuscarFrete(){
  setupBuscarFreteUI();
  const body = document.getElementById('buscarFreteBody');
  if(!body) return;
  const origemRaw = (document.getElementById('buscarFreteOrigem')?.value || '').trim();
  const destino = (document.getElementById('buscarFreteDestino')?.value || '').trim();
  const semana = (document.getElementById('buscarFreteSemana')?.value || '').trim() || latestRodoWeek();
  if(!destino){
    body.innerHTML = `<tr><td colspan="8" class="empty">Selecione um destino/porto para consultar o frete.</td></tr>`;
    renderBuscarFreteChart(origemRaw, destino, semana);
    return;
  }
  if(!origemRaw){
    const recentes = (state.fretesRodo||[]).filter(f=>f.destino===destino && (!semana || f.semana===semana)).slice().sort((a,b)=>a.origem.localeCompare(b.origem)).slice(0,80);
    body.innerHTML = recentes.length ? recentes.map(f=>`<tr>
      <td style="font-weight:600">—</td>
      <td>${safeHtml(f.origem)}</td>
      <td><span class="tag neutral">${safeHtml(f.destino)}</span></td>
      <td class="num"><b>R$ ${money(f.valor)}</b></td>
      <td><span class="tag green">${safeHtml(f.semana)}</span></td>
      <td><span class="tag blue">Frete cadastrado</span></td>
      <td class="num">—</td>
      <td style="font-size:11px;color:var(--g500)">Origem cadastrada para o destino/porto e semana selecionada.</td>
    </tr>`).join('') : `<tr><td colspan="8" class="empty">Nenhum frete cadastrado para esse destino na semana selecionada.</td></tr>`;
    renderBuscarFreteChart(origemRaw, destino, semana);
    return;
  }
  const exact = getFreteRodoReference(origemRaw, destino, semana);
  let rows = [];
  if(exact){
    const km = estimateDistanceKm(origemRaw, destino);
    rows.push({
      origemBuscada: origemRaw,
      origemRef: exact.origemRef || exact.origem,
      destino,
      valor: exact.valor,
      semana: exact.semana,
      tipoBusca: exact.tipoBusca || 'Frete cadastrado',
      kmPorto: km,
      tku: km ? exact.valor/km : null,
      leitura: exact.semana===semana ? 'Frete real encontrado para a rota.' : 'Frete real encontrado em semana anterior disponível.'
    });
  } else {
    rows = getClosestFreightReferences(origemRaw, destino, semana).map((r,i)=>({
      origemBuscada: origemRaw,
      origemRef: r.origemRef,
      destino,
      valor: r.valor,
      semana: r.semana,
      tipoBusca: i===0 ? 'TKU estimado · recomendado' : 'TKU estimado',
      kmPorto: r.kmPorto,
      tku: r.tku,
      leitura: `Referência próxima: ${Math.round(r.kmReferencia)} km da origem buscada. Frete cadastrado da referência: R$ ${money(r.freteRefValor)}/t.`
    }));
  }
  renderBuscarFreteChart(origemRaw, destino, semana);
  body.innerHTML = rows.length ? rows.map(r=>{
    const tipoClass = r.tipoBusca.includes('TKU') ? 'amber' : 'green';
    const distTxt = r.kmPorto ? `${Math.round(r.kmPorto).toLocaleString('pt-BR')} km · TKU ${money(r.tku)}` : '—';
    return `<tr>
      <td style="font-weight:600">${safeHtml(r.origemBuscada)}</td>
      <td>${safeHtml(r.origemRef)}</td>
      <td><span class="tag neutral">${safeHtml(r.destino)}</span></td>
      <td class="num"><b>R$ ${money(r.valor)}</b></td>
      <td><span class="tag neutral">${safeHtml(r.semana || '—')}</span></td>
      <td><span class="tag ${tipoClass}">${safeHtml(r.tipoBusca)}</span></td>
      <td class="num">${safeHtml(distTxt)}</td>
      <td style="font-size:11px;color:var(--g500);white-space:normal;min-width:260px">${safeHtml(r.leitura)}</td>
    </tr>`;
  }).join('') : `<tr><td colspan="8" class="empty">Origem sem coordenada ou sem referência próxima suficiente. Cadastre a praça ou adicione coordenada para habilitar TKU.</td></tr>`;
}

// State global pra filtros e paginação da aba rodo
let rodoPage = 1;
const RODO_PAGE_SIZE = 50;
let rodoCompareMode = false;

function clearRodoFilters(){
  document.getElementById('rodoFiltSemana').value = '';
  document.getElementById('rodoFiltDestino').value = '';
  document.getElementById('rodoFiltOrigem').value = '';
  document.getElementById('rodoSortBy').value = 'origem';
  rodoPage = 1;
  renderFreights();
}

function rodoChangePage(p){
  rodoPage = p;
  renderFreights();
}

function toggleCompareWeeks(){
  rodoCompareMode = !rodoCompareMode;
  renderFreights();
}

function renderFreights(){
  // ═══ Popular selects de filtro ═══
  const semanasUnicas = [...new Set(state.fretesRodo.map(f=>f.semana))].sort().reverse();
  const destinosUnicos = [...new Set(state.fretesRodo.map(f=>f.destino))].sort();

  const fSemana = document.getElementById('rodoFiltSemana');
  const fDestino = document.getElementById('rodoFiltDestino');
  if(fSemana && !fSemana.dataset.populated){
    fSemana.innerHTML = `<option value="">Todas semanas (${semanasUnicas.length})</option>` +
      semanasUnicas.map(s=>`<option value="${s}">${s}</option>`).join('');
    fSemana.dataset.populated = '1';
  }
  if(fDestino && !fDestino.dataset.populated){
    fDestino.innerHTML = `<option value="">Todos destinos</option>` +
      destinosUnicos.map(d=>`<option value="${d}">${d}</option>`).join('');
    fDestino.dataset.populated = '1';
  }

  // ═══ Stats bar ═══
  const totalFretes = state.fretesRodo.length;
  const statsHtml = `
    <div class="kpi n" style="min-width:140px">
      <div class="nm">Total fretes</div>
      <div class="vl">${totalFretes}</div>
    </div>
    <div class="kpi b" style="min-width:150px">
      <div class="nm">Semanas</div> <div class="vl">${semanasUnicas.length} <small style="font-size:12px;color:var(--g500)">de ${(function(){function M(s){var a=String(s).split('-S'),y=+a[0],w=+a[1];var j=new Date(Date.UTC(y,0,4));var m=new Date(j);m.setUTCDate(j.getUTCDate()-((j.getUTCDay()+6)%7)+(w-1)*7);return m;}return semanasUnicas.length?Math.round((M(semanasUnicas[0])-M(semanasUnicas[semanasUnicas.length-1]))/6048e5)+1:0;})()}</small></div>
      <div style="font-size:10px;color:var(--g500);margin-top:3px;font-weight:500">${semanasUnicas[semanasUnicas.length-1]} → ${semanasUnicas[0]}</div>
    </div>
    <div class="kpi a" style="min-width:130px">
      <div class="nm">Destinos</div>
      <div class="vl">${destinosUnicos.length}</div>
    </div>
    <div class="kpi g" style="min-width:150px">
      <div class="nm">Semana atual</div>
      <div class="vl">${semanasUnicas[0]||'—'}</div>
      <div style="font-size:10px;color:var(--g500);margin-top:3px;font-weight:500">${state.fretesRodo.filter(f=>f.semana===semanasUnicas[0]).length} fretes</div>
    </div>
  `;
  const statsBox = document.getElementById('rodoStats');
  if(statsBox){
    statsBox.style.gap = '10px';
    statsBox.innerHTML = statsHtml;
  }

  // ═══ Aplicar filtros ═══
  const fSem = (fSemana?.value || '').trim();
  const fDest = (fDestino?.value || '').trim();
  const fOrig = (document.getElementById('rodoFiltOrigem')?.value || '').trim().toLowerCase();
  const sortBy = document.getElementById('rodoSortBy')?.value || 'origem';

  let rodo = [...state.fretesRodo];
  if(fSem) rodo = rodo.filter(f => f.semana === fSem);
  if(fDest) rodo = rodo.filter(f => f.destino === fDest);
  if(fOrig) rodo = rodo.filter(f => f.origem.toLowerCase().includes(fOrig));

  // ═══ Ordenar ═══
  rodo.sort((a,b)=>{
    switch(sortBy){
      case 'destino':     return a.destino.localeCompare(b.destino) || a.origem.localeCompare(b.origem);
      case 'valor_asc':   return a.valor - b.valor;
      case 'valor_desc':  return b.valor - a.valor;
      case 'semana_desc': return b.semana.localeCompare(a.semana) || a.origem.localeCompare(b.origem);
      case 'semana_asc':  return a.semana.localeCompare(b.semana) || a.origem.localeCompare(b.origem);
      default:            return a.origem.localeCompare(b.origem) || a.destino.localeCompare(b.destino);
    }
  });

  // ═══ Modo Comparação de Semanas ═══
  const compareWrap = document.getElementById('rodoCompareWrap');
  const tableElem = document.getElementById('rodoTable');
  if(rodoCompareMode){
    if(tableElem) tableElem.style.display = 'none';
    document.getElementById('rodoPagination').innerHTML = '';
    if(compareWrap){
      compareWrap.style.display = 'block';
      compareWrap.innerHTML = renderCompareWeeks(semanasUnicas);
    }
    return;
  } else {
    if(tableElem) tableElem.style.display = '';
    if(compareWrap) compareWrap.style.display = 'none';
  }

  // ═══ Paginação ═══
  const totalFiltrado = rodo.length;
  const totalPages = Math.max(1, Math.ceil(totalFiltrado/RODO_PAGE_SIZE));
  if(rodoPage > totalPages) rodoPage = 1;
  const ini = (rodoPage-1)*RODO_PAGE_SIZE;
  const pag = rodo.slice(ini, ini+RODO_PAGE_SIZE);

  // ═══ Render Tabela ═══
  document.getElementById('rodoBody').innerHTML = pag.length ? pag.map(f=>{
    const isCurrentWeek = f.semana === semanasUnicas[0];
    const semanaBadge = isCurrentWeek
      ? `<span class="tag" style="background:var(--greenbg);color:var(--green);font-weight:700">${f.semana}</span>`
      : `<span class="tag neutral">${f.semana}</span>`;
    return `<tr>
      <td>${semanaBadge}</td>
      <td style="font-weight:600">${f.origem}</td>
      <td><span class="tag neutral">${f.destino}</span></td>
      <td class="num"><input type="number" step="0.01" value="${f.valor}" onchange="updateRodoFreight('${f.id}',this.value)" style="width:74px;border:1px solid var(--line);border-radius:8px;padding:4px 6px;text-align:right;font-variant-numeric:tabular-nums"></td>
      <td style="font-size:11px;color:var(--muted)">${f.obs||''}</td>
      <td><button class="btn small danger" onclick="deleteFreight('${f.id}','Rodoviário')">×</button></td>
    </tr>`;
  }).join('') : `<tr><td colspan="6" class="empty">Nenhum frete corresponde aos filtros aplicados</td></tr>`;

  // ═══ Paginação UI ═══
  const pagBox = document.getElementById('rodoPagination');
  if(pagBox){
    if(totalFiltrado <= RODO_PAGE_SIZE){
      pagBox.innerHTML = `<span style="color:var(--muted)">${totalFiltrado} ${totalFiltrado===1?'frete':'fretes'}</span>`;
    } else {
      let nav = `<span style="color:var(--muted);margin-right:14px">Mostrando ${ini+1}–${Math.min(ini+RODO_PAGE_SIZE,totalFiltrado)} de <b>${totalFiltrado}</b></span>`;
      nav += `<button class="btn small" ${rodoPage<=1?'disabled':''} onclick="rodoChangePage(${rodoPage-1})">‹ Anterior</button>`;
      // Páginas próximas
      const startP = Math.max(1, rodoPage-2);
      const endP = Math.min(totalPages, rodoPage+2);
      for(let p=startP; p<=endP; p++){
        if(p === rodoPage){
          nav += `<button class="btn small primary" style="margin:0 3px">${p}</button>`;
        } else {
          nav += `<button class="btn small" style="margin:0 3px" onclick="rodoChangePage(${p})">${p}</button>`;
        }
      }
      nav += `<button class="btn small" ${rodoPage>=totalPages?'disabled':''} onclick="rodoChangePage(${rodoPage+1})">Próxima ›</button>`;
      pagBox.innerHTML = nav;
    }
  }

  // ═══ Ferro matrix (sem mudanças) ═══
  const meses = ['Jan','Fev','Mar','Abr','Mai','Jun','Jul','Ago','Set','Out','Nov','Dez'];
  let html = '<table class="matrix"><thead><tr><th style="text-align:left">Praça (Origem)</th>';
  meses.forEach(m=>html+=`<th>${m}</th>`);
  html += '</tr></thead><tbody>';
  let currentRegion = '';
  state.fretesFerro.forEach(f=>{
    if(f.regiao !== currentRegion){
      html += `<tr class="reg-sep"><th colspan="${meses.length+1}">${f.regiao}</th></tr>`;
      currentRegion = f.regiao;
    }
    html += `<tr><th>${f.origem}</th>`;
    meses.forEach(m=>{
      html += `<td><input type="number" step="0.01" value="${f.meses[m]||''}" onchange="updateFerroFreight('${f.id}','${m}',this.value)"></td>`;
    });
    html += '</tr>';
  });
  html += '</tbody></table>';
  html += '<div style="margin-top:10px;font-size:11px;color:var(--muted)">Taci — Terminal Rondonópolis. Valores em R$/t para o destino de cada bloco (Rumo → Santos · VLI → Itaqui). Editáveis e mensais.</div>';
  document.getElementById('ferroWrap').innerHTML = html;
}

/* Renderiza comparação semana a semana */
function renderCompareWeeks(semanas){
  if(semanas.length < 2){
    return `<div style="padding:20px;text-align:center;color:var(--muted);font-size:12px">Apenas uma semana cadastrada. Compare quando tiver pelo menos 2 semanas.</div>`;
  }
  const ultima = semanas[0];
  const anterior = semanas[1];

  // Cruza fretes (mesma origem + destino) entre ultima e anterior
  const fretesUlt = state.fretesRodo.filter(f=>f.semana===ultima);
  const fretesAnt = state.fretesRodo.filter(f=>f.semana===anterior);
  const idxAnt = {};
  fretesAnt.forEach(f=>{ idxAnt[`${f.origem.toLowerCase()}|${f.destino.toLowerCase()}`] = f; });

  // Coleta rotas com par de dados
  const comparacoes = [];
  fretesUlt.forEach(f=>{
    const key = `${f.origem.toLowerCase()}|${f.destino.toLowerCase()}`;
    const ant = idxAnt[key];
    if(ant){
      const delta = f.valor - ant.valor;
      comparacoes.push({
        origem: f.origem, destino: f.destino,
        valorUlt: f.valor, valorAnt: ant.valor, delta,
        pct: ant.valor ? (delta/ant.valor*100) : 0
      });
    }
  });

  comparacoes.sort((a,b)=>Math.abs(b.delta)-Math.abs(a.delta));

  // Resumo
  const altas = comparacoes.filter(c=>c.delta>0).length;
  const quedas = comparacoes.filter(c=>c.delta<0).length;
  const iguais = comparacoes.filter(c=>c.delta===0).length;
  const novas = fretesUlt.length - comparacoes.length;

  // Top altas e top quedas
  const topAltas = comparacoes.filter(c=>c.delta>0).slice(0,5);
  const topQuedas = comparacoes.filter(c=>c.delta<0).reverse().slice(0,5);

  const rowsHtml = comparacoes.map(c=>{
    const cor = c.delta>0?'var(--red)':c.delta<0?'var(--green)':'var(--muted)';
    const sym = c.delta>0?'▲':c.delta<0?'▼':'=';
    return `<tr>
      <td style="font-weight:600">${c.origem}</td>
      <td><span class="tag neutral">${c.destino}</span></td>
      <td class="num">${money(c.valorAnt)}</td>
      <td class="num">${money(c.valorUlt)}</td>
      <td class="num" style="color:${cor};font-weight:700">${sym} ${c.delta>=0?'+':''}${money(c.delta)}</td>
      <td class="num" style="color:${cor}">${c.delta>=0?'+':''}${c.pct.toFixed(1)}%</td>
    </tr>`;
  }).join('');

  return `
    <div style="margin-bottom:18px">
      <div class="sec-title" style="margin-bottom:14px">Comparando ${anterior} → ${ultima}<span class="sec-sub">${comparacoes.length} rotas analisadas</span></div>
      <div class="kpi-strip">
        <div class="kpi n"><div class="nm">Comparáveis</div><div class="vl">${comparacoes.length}</div></div>
        <div class="kpi r"><div class="nm">▲ Altas</div><div class="vl">${altas}</div></div>
        <div class="kpi g"><div class="nm">▼ Quedas</div><div class="vl">${quedas}</div></div>
        <div class="kpi"><div class="nm">= Sem mudança</div><div class="vl">${iguais}</div></div>
        <div class="kpi a"><div class="nm">+ Rotas novas</div><div class="vl">${novas}</div></div>
      </div>
    </div>

    ${topAltas.length ? `
    <div style="display:grid;grid-template-columns:1fr 1fr;gap:14px;margin-bottom:18px">
      <div class="tc red-bar">
        <div class="tc-h"><span class="tag red">▲ Top 5 Maiores Altas</span></div>
        ${topAltas.map(c=>`<div style="font-size:12px;padding:7px 0;border-bottom:1px solid var(--g200);display:flex;justify-content:space-between;color:var(--g700)"><span>${c.origem.split('/')[0]} → ${c.destino}</span><span class="num" style="color:var(--red);font-weight:700">+R$ ${money(c.delta)} <span style="opacity:.7;font-weight:500">(+${c.pct.toFixed(1)}%)</span></span></div>`).join('')}
      </div>
      <div class="tc grn-bar">
        <div class="tc-h"><span class="tag green">▼ Top 5 Maiores Quedas</span></div>
        ${topQuedas.map(c=>`<div style="font-size:12px;padding:7px 0;border-bottom:1px solid var(--g200);display:flex;justify-content:space-between;color:var(--g700)"><span>${c.origem.split('/')[0]} → ${c.destino}</span><span class="num" style="color:var(--green);font-weight:700">${money(c.delta)} <span style="opacity:.7;font-weight:500">(${c.pct.toFixed(1)}%)</span></span></div>`).join('')}
      </div>
    </div>` : ''}

    <div style="background:var(--card);border:1px solid var(--g200);border-radius:8px;overflow:hidden">
      <div style="padding:12px 16px;background:var(--g50);font-size:11px;font-weight:700;color:var(--navy-ink);letter-spacing:.4px;text-transform:uppercase;border-bottom:1px solid var(--g200)">Todas as ${comparacoes.length} rotas comparadas</div>
      <div style="max-height:500px;overflow-y:auto">
        <table class="table" style="font-size:12px">
          <thead style="position:sticky;top:0;z-index:1">
            <tr><th>Origem</th><th>Destino</th><th class="num">${anterior}</th><th class="num">${ultima}</th><th class="num">Δ R$/t</th><th class="num">Δ %</th></tr>
          </thead>
          <tbody>${rowsHtml}</tbody>
        </table>
      </div>
    </div>
  `;
}
function updateRodoFreight(id, val){
  const f = state.fretesRodo.find(x=>x.id===id); if(f) f.valor = n(val); persist();
}
function updateFerroFreight(id, mes, val){
  const f = state.fretesFerro.find(x=>x.id===id); if(f) f.meses[mes] = n(val); persist();
}
function openFreightDrawer(){
  document.getElementById('freightForm').innerHTML = `
    <div class="field"><label>Semana</label><input name="semana" value="2026-S22"></div>
    <div class="field"><label>Destino (porto)</label><select name="destino"><option>Santos</option><option>Paranaguá</option><option>Itaqui</option><option>Barcarena</option></select></div>
    <div class="field full"><label>Origem (cidade/UF)</label><input name="origem" required placeholder="Ex: Rio Verde/GO"></div>
    <div class="field"><label>Valor R$/t</label><input name="valor" type="number" step="0.01" required></div>
    <div class="field"><label>Obs.</label><input name="obs" value="Trans"></div>`;
  openDrawer('freightDrawer');
}
function saveFreight(e){
  e.preventDefault();
  const fd = new FormData(e.target);
  const f = {id:uid('r'), tipo:'Rodoviário', semana:fd.get('semana'), origem:fd.get('origem'), destino:fd.get('destino'), valor:n(fd.get('valor')), obs:fd.get('obs')};
  state.fretesRodo.unshift(f);
  persist(); closeDrawers(); renderAll();
}
function deleteFreight(id, tipo){
  if(!confirm('Excluir frete?')) return;
  if(tipo==='Rodoviário') state.fretesRodo = state.fretesRodo.filter(x=>x.id!==id);
  persist(); renderAll();
}

/* ═══════════════════════════════════════════════════════
   DEAL DRAWER (editar)
═══════════════════════════════════════════════════════ */
const dealFields = ['data','produto','safra','origem','comprador','vendedor','retirada','volume','preco','precoOrig','vencCBOT','cbot','vencCambio','cambio','premio','corredor'];
function openDealDrawer(id){
  editDealId = id;
  const d = getActiveDeals().find(x=>x.id===id) || {};
  document.getElementById('dealDrawerTitle').textContent = 'Editar Negócio';
  const labels = {data:'Data',produto:'Produto',safra:'Safra',origem:'Origem',comprador:'Comprador',vendedor:'Vendedor',retirada:'Retirada',volume:'Volume (t)',preco:'Preço R$/sc',precoOrig:'Preço Original (display)',vencCBOT:'Venc. CBOT',cbot:'CBOT (USc/bu)',vencCambio:'Venc. Câmbio',cambio:'Câmbio R$/USD',premio:'Basis Porto (¢/bu)',corredor:'Corredor'};
  const numFields = ['volume','preco','cbot','cambio','premio'];
  document.getElementById('dealForm').innerHTML = dealFields.map(f=>`
    <div class="field ${['origem','vendedor','precoOrig'].includes(f)?'full':''}">
      <label>${labels[f]||f}</label>
      <input name="${f}" type="${numFields.includes(f)?'number':f==='data'?'date':'text'}" step="0.001" value="${d[f]??''}">
    </div>`).join('');
  openDrawer('dealDrawer');
}
function saveDeal(e){
  e.preventDefault();
  const fd = new FormData(e.target);
  const obj = {};
  dealFields.forEach(f=>obj[f] = fd.get(f));
  ['volume','preco','cbot','cambio','premio'].forEach(f=>obj[f] = n(obj[f]));
  if(editDealId){
    var _base = getActiveBase()==='precos' ? getPrecosBase() : ((state&&state.negocios)||[]);
    var _rec = _base.find(function(x){ return x.id===editDealId; });
    if(_rec){
      Object.assign(_rec, obj);
      if(getActiveBase()!=='precos'){
        _rec.cbotFechamento=n(obj.cbot);
        _rec.cambioFechamento=n(obj.cambio);
        _rec.marketSnapshotLocked=true;
        _rec.marketSnapshotTime=_rec.marketSnapshotTime||new Date().toISOString();
        _rec.marketSnapshotSource='Edição manual do negócio';
      }
      brzApplySoyXRuleToDeal(_rec, (state&&state.cbot)||MARKET_SNAPSHOT.cbot);
      brzRestoreDealMarketSnapshot(_rec);
    }
    if(getActiveBase()==='precos'){
      state.precosEdits = state.precosEdits || {};
      state.precosEdits[editDealId] = Object.assign({}, state.precosEdits[editDealId], obj);
    }
  }
  persist(); closeDrawers(); renderAll();
}

/* ═══════════════════════════════════════════════════════
   CURVA DE PREÇOS POR REGIÃO (SVG NATIVO)
═══════════════════════════════════════════════════════ */
let curvaSelectedCorredores = new Set();
let curvaSafraFilter = 'disponivel'; // 'disponivel', '25_26', '26_27', 'todos'

/* Normaliza qualquer string de safra para um bucket canônico */
function normalizeSafra(s){
  if(!s) return 'outro';
  const t = String(s).toLowerCase().replace(/\s/g,'');
  if(t.includes('disp')) return 'disponivel';
  if(t.includes('26/27')||t.includes('2026/2027')||t==='2027') return '26_27';
  if(t.includes('25/26')||t.includes('2025/2026')||t==='2026') return '25_26';
  if(t.includes('24/25')||t.includes('2024/2025')||t==='2025') return '24_25';
  return 'outro';
}
function safraLabel(key){ return brzSafraLabel(key); } /* V4AV */
function normalizeSafraDeal(d){ return brzSafraKeyDeal(d); } /* V4AV */


function curvaEstadoFromCorredor(c){
  if(!c) return '';
  const m = String(c).trim().match(/^([A-Z]{2})(?:\s|$)/);
  if(m) return m[1];
  const uf = String(c).trim().toUpperCase();
  return uf.length === 2 ? uf : 'BR';
}
let curvaEstadoFilter = 'GO';
let curvaNivel = 'estado_corridor'; // estado_corridor | estados | corredores
let curvaHiddenSeries = new Set();
let curvaPeriodo = 'todos';

function curvaSeriesKeySafe(v){ return String(v||'').replace(/'/g,'&#39;'); }
function curvaSeriesLabelForState(uf){ return `Média ${uf}`; }
function curvaDealBucketValue(k){
  if(!k || !k.count) return null;
  // Curva de Preços: usar preço absoluto da série no dia.
  // Quando há mais de um registro no mesmo dia/corredor, usa o último registro carregado.
  if(Number.isFinite(Number(k.lastPrice))) return Number(k.lastPrice);
  if(Number.isFinite(Number(k.sumSimple)) && k.count) return Number(k.sumSimple) / Number(k.count);
  return null;
}
function curvaPeriodCutoff(){
  if(curvaPeriodo === '30d') return 30;
  if(curvaPeriodo === '60d') return 60;
  if(curvaPeriodo === '90d') return 90;
  return null;
}
function curvaApplyPeriod(deals){
  const days = curvaPeriodCutoff();
  if(!days || !deals.length) return deals;
  const maxDate = deals.map(d=>d.data).filter(Boolean).sort().slice(-1)[0];
  if(!maxDate) return deals;
  const maxTs = new Date(maxDate+'T00:00:00').getTime();
  const minTs = maxTs - days*24*60*60*1000;
  return deals.filter(d => new Date(d.data+'T00:00:00').getTime() >= minTs);
}
function curvaDownsample(points, maxPoints=260){
  if(!Array.isArray(points) || points.length <= maxPoints) return points || [];
  const out = [];
  const step = (points.length - 1) / (maxPoints - 1);
  for(let i=0;i<maxPoints;i++) out.push(points[Math.round(i*step)]);
  return out;
}
function renderCurva(){
  const produtoAtivo = getActiveProduto();
  const baseAtiva = getActiveBase();
  if(curvaSafraFilter!=='todos' && curvaSafraFilter!=='disponivel' && brzSafraLista(getActiveDeals()).indexOf(curvaSafraFilter)<0) curvaSafraFilter = 'todos';

  const wrap = document.getElementById('chartWrap');
  const headEl = document.getElementById('curvaHead');
  const bodyEl = document.getElementById('curvaBody');
  if(!wrap || !headEl || !bodyEl) return;

  let curvaBaseDeals = getActiveDeals().filter(d => d && d.data && n(d.preco) > 0 && n(d.preco) < 1000);
  curvaBaseDeals = curvaSafraFilter === 'todos' ? curvaBaseDeals : curvaBaseDeals.filter(d => brzSafraMatch(d, curvaSafraFilter));
  curvaBaseDeals = curvaApplyPeriod(curvaBaseDeals);

  const stateSet = new Set(curvaBaseDeals.map(d=>curvaEstadoFromCorredor(d.corredor)).filter(Boolean));
  const states = [...stateSet].sort();
  if(curvaEstadoFilter !== 'todos' && !states.includes(curvaEstadoFilter)){
    curvaEstadoFilter = states.includes('GO') ? 'GO' : (states[0] || 'todos');
  }
  const dealsScope = curvaEstadoFilter === 'todos' ? curvaBaseDeals : curvaBaseDeals.filter(d => curvaEstadoFromCorredor(d.corredor) === curvaEstadoFilter);

  const safras = ['disponivel'].concat(brzSafraLista(getActiveDeals())).concat(['todos']);
  const stateOptions = ['<option value="todos">Todos os estados</option>'].concat(states.map(uf=>`<option value="${uf}" ${curvaEstadoFilter===uf?'selected':''}>${estadoNome(uf)} (${uf})</option>`)).join('');
  const nivelOptions = curvaEstadoFilter === 'todos'
    ? `<button class="btn small ${curvaNivel==='estados'?'primary':''}" onclick="setCurvaNivel('estados')">Referência por estado</button><button class="btn small ${curvaNivel==='corredores'?'primary':''}" onclick="setCurvaNivel('corredores')">Corredores</button>`
    : `<button class="btn small ${curvaNivel==='estado_corridor'?'primary':''}" onclick="setCurvaNivel('estado_corridor')">Estado + corredores</button><button class="btn small ${curvaNivel==='corredores'?'primary':''}" onclick="setCurvaNivel('corredores')">Só corredores</button>`;
  document.getElementById('curvaToolbar').innerHTML = `
    <div class="field" style="min-width:270px"><label>Safra</label><div style="display:flex;gap:6px;flex-wrap:wrap">${safras.map(s=>`<button class="btn small ${curvaSafraFilter===s?'primary':''}" onclick="setCurvaSafra('${s}')">${safraLabel(s)}</button>`).join('')}</div></div>
    <div class="field" style="min-width:190px"><label>Estado</label><select onchange="setCurvaEstado(this.value)">${stateOptions}</select></div>
    <div class="field" style="min-width:260px"><label>Visualização</label><div style="display:flex;gap:6px;flex-wrap:wrap">${nivelOptions}</div></div>
    <div class="field" style="min-width:210px"><label>Período</label><div style="display:flex;gap:6px;flex-wrap:wrap"><button class="btn small ${curvaPeriodo==='30d'?'primary':''}" onclick="setCurvaPeriodo('30d')">30d</button><button class="btn small ${curvaPeriodo==='60d'?'primary':''}" onclick="setCurvaPeriodo('60d')">60d</button><button class="btn small ${curvaPeriodo==='90d'?'primary':''}" onclick="setCurvaPeriodo('90d')">90d</button><button class="btn small ${curvaPeriodo==='todos'?'primary':''}" onclick="setCurvaPeriodo('todos')">Tudo</button></div></div>`;

  if(!dealsScope.length){
    wrap.innerHTML = `<div class="empty">Sem preços para ${produtoAtivo} · ${safraLabel(curvaSafraFilter)}.</div>`;
    headEl.innerHTML = '';
    bodyEl.innerHTML = '<tr><td colspan="8" class="empty">Sem dados</td></tr>';
    return;
  }

  const colors = ['#1A3A5C','#0D9488','#B5963E','#D97706','#7C3AED','#2563EB','#DC2626','#059669','#EC4899','#14B8A6'];
  const dates = [...new Set(dealsScope.map(d=>d.data).filter(Boolean))].sort();
  const dateIdx = new Map(dates.map((d,i)=>[d,i]));
  const addBucket = (obj, key, d) => {
    if(!obj[key]) obj[key] = Object.create(null);
    const date = d.data;
    if(!obj[key][date]) obj[key][date] = {sumVol:0, vol:0, sumSimple:0, count:0, min:Infinity, max:-Infinity, lastPrice:null, lastVol:0};
    const k = obj[key][date];
    const price = n(d.preco), vol = n(d.volume);
    if(!Number.isFinite(price) || price <= 0 || price > 1000) return;
    k.sumVol += price * vol;
    k.vol += vol;
    k.sumSimple += price;
    k.count += 1;
    k.lastPrice = price;
    k.lastVol = vol;
    if(price < k.min) k.min = price;
    if(price > k.max) k.max = price;
  };

  const grouped = Object.create(null);
  dealsScope.forEach(d=>{
    const uf = curvaEstadoFromCorredor(d.corredor);
    const corr = d.corredor || uf || 'Sem corredor';
    if(curvaEstadoFilter === 'todos'){
      if(curvaNivel === 'corredores') addBucket(grouped, corr, d);
      else addBucket(grouped, curvaSeriesLabelForState(uf), d);
    } else {
      if(curvaNivel === 'estado_corridor') addBucket(grouped, curvaSeriesLabelForState(curvaEstadoFilter), d);
      addBucket(grouped, corr, d);
    }
  });

  let keys = Object.keys(grouped);
  const volByKey = Object.create(null);
  keys.forEach(k=>{ volByKey[k] = Object.values(grouped[k]).reduce((s,b)=>s+(b.vol||0),0); });
  keys.sort((a,b)=>{
    const aAvg = a.startsWith('Média '), bAvg = b.startsWith('Média ');
    if(aAvg && !bAvg) return -1;
    if(!aAvg && bAvg) return 1;
    return (volByKey[b]||0) - (volByKey[a]||0) || a.localeCompare(b);
  });
  if(curvaEstadoFilter === 'todos' && curvaNivel === 'corredores') keys = keys.slice(0,8);
  if(curvaEstadoFilter !== 'todos' && curvaNivel === 'corredores') keys = keys.slice(0,10);

  const series = keys.map((key, idx)=>{
    const rawPoints = dates.map(date=>{
      const k = grouped[key][date];
      const preco = curvaDealBucketValue(k);
      return k && preco !== null && Number.isFinite(preco) && preco > 0 && preco < 1000 ? {date, preco, vol:k.vol, count:k.count, min:k.min, max:k.max} : null;
    }).filter(Boolean);
    return {key, color: colors[idx % colors.length], hidden: curvaHiddenSeries.has(key), points: curvaDownsample(rawPoints, baseAtiva==='precos' ? 220 : 320), rawPoints};
  }).filter(s=>s.rawPoints.length);

  const visibleSeries = series.filter(s=>!s.hidden);
  const allPoints = visibleSeries.flatMap(s=>s.points.map(p=>p.preco)).filter(v=>Number.isFinite(v) && v>0 && v<1000);
  if(!allPoints.length){
    wrap.innerHTML = '<div class="empty">Selecione pelo menos uma série na legenda.</div>';
    bodyEl.innerHTML = '<tr><td colspan="8" class="empty">Selecione uma série</td></tr>';
    return;
  }

  const latestDate = dates[dates.length-1];
  const latestBuckets = visibleSeries.map(s=>({key:s.key, p:(s.rawPoints||s.points).filter(p=>p.date===latestDate).slice(-1)[0]})).filter(x=>x.p);
  const avgLatest = latestBuckets.length ? latestBuckets.reduce((sum,x)=>sum+x.p.preco,0)/latestBuckets.length : null;
  const bestLatest = latestBuckets.slice().sort((a,b)=>a.p.preco-b.p.preco)[0];
  const worstLatest = latestBuckets.slice().sort((a,b)=>b.p.preco-a.p.preco)[0];
  const totalVol = dealsScope.reduce((s,d)=>s+n(d.volume),0);
  const kpiHtml = `<div class="kpi-strip" style="padding:0 0 14px 0">
    <div class="kpi b"><div class="nm">Referência atual</div><div class="vl">${avgLatest!==null?'R$ '+money(avgLatest):'—'}</div><div class="ch" style="color:var(--g500);font-weight:600">${latestDate?fmtDate(latestDate):'—'} · R$/sc</div></div>
    <div class="kpi g"><div class="nm">Menor preço</div><div class="vl">${bestLatest?'R$ '+money(bestLatest.p.preco):'—'}</div><div class="ch" style="color:var(--g500);font-weight:600">${bestLatest?bestLatest.key:'—'}</div></div>
    <div class="kpi a"><div class="nm">Maior preço</div><div class="vl">${worstLatest?'R$ '+money(worstLatest.p.preco):'—'}</div><div class="ch" style="color:var(--g500);font-weight:600">${worstLatest?worstLatest.key:'—'}</div></div>
    <div class="kpi n"><div class="nm">Base filtrada</div><div class="vl">${dealsScope.length}</div><div class="ch" style="color:var(--g500);font-weight:600">registros de preço</div></div>
  </div>`;

  const W = 980, H = 330, PADL = 62, PADR = 24, PADT = 28, PADB = 48;
  const minP = Math.floor(Math.min(...allPoints) - 1);
  const maxP = Math.ceil(Math.max(...allPoints) + 1);
  const denom = Math.max(maxP-minP, 1);
  const xScale = i => PADL + (i*(W-PADL-PADR)/(Math.max(dates.length-1,1)));
  const yScale = p => H - PADB - ((p-minP)/denom)*(H-PADT-PADB);
  let svg = `<svg viewBox="0 0 ${W} ${H}" style="width:100%;height:auto;max-height:360px;font-family:Inter,system-ui,-apple-system,Arial,sans-serif">`;
  svg += `<text x="${PADL}" y="18" font-size="13" font-weight="800" fill="var(--navy)">${produtoAtivo} · Preço R$/sc ${curvaEstadoFilter==='todos'?'por estado':('em '+estadoNome(curvaEstadoFilter))}</text>`;
  for(let i=0;i<=5;i++){
    const y = PADT + i*(H-PADT-PADB)/5;
    const v = maxP - i*denom/5;
    svg += `<line x1="${PADL}" y1="${y}" x2="${W-PADR}" y2="${y}" stroke="var(--line)" stroke-width="1"/>`;
    svg += `<text x="${PADL-9}" y="${y+4}" text-anchor="end" font-size="10" fill="var(--muted)">R$ ${v.toFixed(0)}</text>`;
  }
  const xLabelStep = Math.max(1, Math.ceil(dates.length/8));
  dates.forEach((d,i)=>{
    if(i%xLabelStep!==0 && i!==dates.length-1) return;
    const dd = new Date(d+'T00:00:00');
    const lab = `${String(dd.getDate()).padStart(2,'0')}/${String(dd.getMonth()+1).padStart(2,'0')}`;
    svg += `<text x="${xScale(i)}" y="${H-PADB+22}" text-anchor="middle" font-size="10" fill="var(--muted)">${lab}</text>`;
  });
  visibleSeries.forEach(s=>{
    let path = '';
    s.points.forEach((p,i)=>{ const idx = dateIdx.get(p.date) ?? 0; const x=xScale(idx), y=yScale(p.preco); path += `${i===0?'M':'L'}${x.toFixed(1)},${y.toFixed(1)} `; });
    svg += `<path d="${path}" fill="none" stroke="${s.color}" stroke-width="${s.key.startsWith('Média ')?3.0:2.0}" stroke-linejoin="round" stroke-linecap="round" opacity="${s.key.startsWith('Média ')?1:.9}"/>`;
    const pointStep = Math.max(1, Math.ceil(s.points.length/45));
    s.points.forEach((p,pi)=>{ if(pi % pointStep !== 0 && pi !== s.points.length-1) return; const idx=dateIdx.get(p.date) ?? 0; const x=xScale(idx), y=yScale(p.preco); svg += `<circle cx="${x.toFixed(1)}" cy="${y.toFixed(1)}" r="3.1" fill="${s.color}" stroke="#fff" stroke-width="1.3"><title>${s.key} · ${fmtDate(p.date)} · R$ ${money(p.preco)}/sc · ${p.count} registros</title></circle>`; });
  });
  svg += '</svg>';
  const legend = series.map(s=>`<label class="${s.hidden?'off':''}" onclick="toggleCurvaSerie('${curvaSeriesKeySafe(s.key)}')"><span class="dot" style="background:${s.color}"></span>${s.key}</label>`).join('');
  const leitura = `<div class="tc navy-bar" style="margin-top:12px"><div class="tc-h">Leitura da curva</div><p>${curvaEstadoFilter!=='todos' ? `A curva mostra o preço em <strong>${estadoNome(curvaEstadoFilter)}</strong> por corredor/região.` : `A curva compara o preço por estado na base filtrada.`} ${bestLatest?`No último ponto, o menor preço ficou em <strong>${bestLatest.key}</strong>, com <strong>R$ ${money(bestLatest.p.preco)}/sc</strong>.`:''} ${worstLatest?`A ponta mais alta ficou em <strong>${worstLatest.key}</strong>, com <strong>R$ ${money(worstLatest.p.preco)}/sc</strong>.`:''}</p></div>`;
  wrap.innerHTML = `<div style="padding:18px 28px 12px">${kpiHtml}<div class="chartWrap" style="border:1px solid var(--g200);border-radius:10px;padding:12px;background:var(--card)">${svg}<div class="chartLegend">${legend}</div></div>${leitura}</div>`;

  const colsCv = [
    {f:'date', label:'Data', num:false},
    {f:'serie', label:curvaEstadoFilter==='todos'?'Estado/Corredor':'Referência/Corredor', num:false},
    {f:'preco', label:'Preço R$/sc', num:true},
    {f:'vol', label:'Volume (t)', num:true},
    {f:'count', label:'Registros', num:true},
    {f:'min', label:'Mín.', num:true},
    {f:'max', label:'Máx.', num:true}
  ];
  headEl.innerHTML = '<tr>' + colsCv.map(c=>`<th class="${c.num?'num ':''}th-sort ${curvaSortField===c.f?curvaSortDir:''}" onclick="sortCurva('${c.f}')">${c.label}</th>`).join('') + '</tr>';
  const rows = [];
  visibleSeries.forEach(s=>(s.rawPoints||s.points).forEach(p=>rows.push({serie:s.key, ...p})));
  if(curvaSortField){
    const dir = curvaSortDir === 'asc' ? 1 : -1;
    const numFields = new Set(['preco','vol','count','min','max']);
    rows.sort((a,b)=>{ let va=a[curvaSortField], vb=b[curvaSortField]; if(numFields.has(curvaSortField)){va=n(va);vb=n(vb);} else {va=String(va||'');vb=String(vb||'');} return va<vb?-1*dir:va>vb?1*dir:0; });
  } else rows.sort((a,b)=>b.date.localeCompare(a.date)||a.serie.localeCompare(b.serie));
  const curvaRowsLimit = baseAtiva==='precos' ? 350 : 800;
  const rowsView = rows.slice(0, curvaRowsLimit);
  bodyEl.innerHTML = (rowsView.map(r=>`<tr><td>${fmtDate(r.date)}</td><td>${r.serie}</td><td class="num"><b>R$ ${money(r.preco)}</b></td><td class="num">${tons(r.vol)}</td><td class="num">${r.count}</td><td class="num">R$ ${money(r.min)}</td><td class="num">R$ ${money(r.max)}</td></tr>`).join('') + (rows.length>curvaRowsLimit ? `<tr><td colspan="7" class="empty">Mostrando ${curvaRowsLimit} de ${rows.length} linhas. Use os filtros para refinar a leitura.</td></tr>` : '')) || '<tr><td colspan="7" class="empty">Sem dados</td></tr>';
}

