function embarqueEfetivo(dl){
  var k=String(dl&&dl.id); if(_embEffCache.has(k)) return _embEffCache.get(k);
  var v=(dl&&dl.embarque)||((typeof embarqueInferido==='function')?(embarqueInferido(dl)||''):'');
  _embEffCache.set(k,v); return v;
}

/* Extrai sigla do estado de um corredor. Convenção dos corredores: "XX <região>"
   onde XX = sigla de 2 letras. Ex: "GO Sul" → "GO". */
function corrToEstado(corredor){
  if(!corredor) return '';
  const m = String(corredor).match(/^([A-Z]{2})\s/);
  return m ? m[1] : 'XX';
}

/* Nome completo do estado a partir da sigla */
function estadoNome(sigla){
  const nomes = {
    GO:'Goiás', MA:'Maranhão', MS:'Mato Grosso do Sul', MT:'Mato Grosso',
    PA:'Pará', PI:'Piauí', PR:'Paraná', SC:'Santa Catarina', TO:'Tocantins',
    BA:'Bahia', MG:'Minas Gerais', RS:'Rio Grande do Sul'
  };
  return nomes[sigla] || sigla;
}

/* Agrupa lista de corredores por estado. Retorna [{estado, sigla, regioes:[corr,...]}] ordenado. */
function agruparCorredoresPorEstado(corredores){
  const grupos = {};
  corredores.forEach(c=>{
    const sigla = corrToEstado(c);
    if(!grupos[sigla]) grupos[sigla] = [];
    grupos[sigla].push(c);
  });
  return Object.keys(grupos).sort().map(sigla=>({
    sigla,
    estado: estadoNome(sigla),
    regioes: grupos[sigla].sort()
  }));
}

/* Renderiza grupo de chips por estado (estilo accordion).
   ctx = 'fechamento' | 'negocios'  — define qual estado de expansão e qual Set usar */
function renderCorrPorEstado(ctx, corrs, countByCorr){
  const grupos = agruparCorredoresPorEstado(corrs);
  const expanded = ctx === 'fechamento' ? fechamentoEstadosExpandidos : negociosEstadosExpandidos;
  const filtro   = ctx === 'fechamento' ? fechamentoFiltroCorr : negociosFiltroCorr;
  const toggleEstadoFn = ctx === 'fechamento' ? 'toggleFechamentoEstado' : 'toggleNegociosEstado';
  const toggleCorrFn   = ctx === 'fechamento' ? 'toggleFechamentoCorr' : 'toggleNegociosCorr';
  const toggleAllFn    = ctx === 'fechamento' ? 'toggleFechamentoEstadoAll' : 'toggleNegociosEstadoAll';

  return grupos.map(g=>{
    const isExp = expanded.has(g.sigla);
    const totalDeals = g.regioes.reduce((acc,r)=>acc+(countByCorr[r]||0),0);
    const selecCount = g.regioes.filter(r=>filtro.has(r)).length;
    const allSelected = selecCount === g.regioes.length && g.regioes.length > 0;
    const someSelected = selecCount > 0 && !allSelected;
    // Cor do botão do estado: primário se TUDO selecionado, intermediário se PARCIAL
    const btnBg = ctx === 'negocios'
      ? (allSelected || someSelected ? '#ECFDF5' : '#fff')
      : (allSelected ? 'var(--teal)' : someSelected ? '#0EA5E910' : '#fff');
    const btnColor = ctx === 'negocios'
      ? (allSelected || someSelected ? 'var(--teal-dark)' : 'var(--g900)')
      : (allSelected ? '#fff' : 'var(--g900)');
    const btnBorder = (allSelected || someSelected) ? 'var(--teal)' : 'var(--g200)';

    return `<div style="display:inline-flex;flex-direction:column;gap:5px;margin-right:4px;margin-bottom:5px;vertical-align:top">
      <div style="display:inline-flex;border:1px solid ${btnBorder};border-radius:6px;overflow:hidden;background:${btnBg}">
        <button onclick="${toggleAllFn}('${g.sigla}')" style="border:0;background:transparent;padding:5px 10px;font-size:11px;font-weight:700;color:${btnColor};cursor:pointer;letter-spacing:.2px" title="Marcar/desmarcar todas as regiões de ${g.estado}">
          ${g.sigla}${selecCount>0?` <span style="font-weight:500;opacity:.8">(${selecCount}/${g.regioes.length})</span>`:''}
        </button>
        <button onclick="${toggleEstadoFn}('${g.sigla}')" style="border:0;background:transparent;padding:5px 8px;font-size:11px;font-weight:600;color:${btnColor};cursor:pointer;border-left:1px solid ${allSelected && ctx !== 'negocios'?'rgba(255,255,255,.3)':'var(--g200)'}" title="${isExp?'Recolher':'Expandir'} regiões de ${g.estado}">
          ${isExp?'▴':'▾'}
        </button>
      </div>
      ${isExp ? `
      <div style="display:flex;flex-wrap:wrap;gap:4px;padding:6px 8px;background:var(--g50);border:1px dashed var(--g200);border-radius:6px;max-width:340px">
        ${g.regioes.map(r=>{
          const sub = r.replace(/^[A-Z]{2}\s/,'');
          const isSel = filtro.has(r);
          const cnt = countByCorr[r] || 0;
          const isDisabled = cnt === 0 && !isSel;
          return `<button onclick="${isDisabled?'':toggleCorrFn+'(\''+r.replace(/'/g,"\\'")+'\')'}"
            style="border:1px solid ${isSel?'var(--teal)':'var(--g200)'};background:${isSel?'var(--greenbg)':'var(--card)'};color:${isSel?'var(--teal-dark)':'var(--g700)'};border-radius:4px;padding:3px 8px;font-size:10.5px;font-weight:600;cursor:${isDisabled?'not-allowed':'pointer'};opacity:${isDisabled?0.3:1};filter:${isDisabled?'grayscale(0.4)':'none'}"
            title="${isDisabled?'Sem negócios com os filtros atuais':''}">${sub} <span style="opacity:.65;font-weight:500">(${cnt})</span></button>`;
        }).join('')}
      </div>
      ` : ''}
    </div>`;
  }).join('');
}


