function renderOceanCornAddendum(body, editedWeek){
  if(!body || !state.oceanFreightCornMonthly) return;
  const day = state.oceanFreightCornMonthly[editedWeek];
  if(!day) return;
  /* V4AW: meses, destinos e portos derivados do dia */
  const _mset={}; Object.keys(day).forEach(function(dst){ Object.keys(day[dst]||{}).forEach(function(p){ Object.keys(day[dst][p]||{}).forEach(function(m){ if(m!=='CONT') _mset[m]=1; }); }); });
  const MONTHS = ['CONT'].concat(Object.keys(_mset).sort(function(a,b){ return brzEmbOrdem(a)-brzEmbOrdem(b); }));
  const order = Object.keys(day).map(function(dst){ return {dest:dst, ports:Object.keys(day[dst]||{})}; });
  let blocks='';
  order.forEach(function(gr){
    const src=day[gr.dest]||{};
    const available=gr.ports.filter(p=>src[p]&&Object.keys(src[p]).length);
    if(!available.length) return;
    let head='<th style="position:sticky;left:0;background:var(--navy);z-index:2;text-align:left;min-width:150px">Porto → '+gr.dest+'</th>';
    MONTHS.forEach(m=>{head+='<th style="text-align:center;min-width:76px">'+m+'</th>';});
    let rows='';
    available.forEach(function(p){
      let row='<td style="position:sticky;left:0;background:var(--g50);z-index:1;font-weight:700;color:var(--navy-ink)">'+p+'</td>';
      MONTHS.forEach(function(m){
        const v=src[p][m];
        row+='<td style="text-align:right;padding:7px 8px;font-size:11.5px;font-variant-numeric:tabular-nums;color:var(--g700)">'+(typeof v==='number'?money(v):'—')+'</td>';
      });
      rows+='<tr>'+row+'</tr>';
    });
    blocks+='<div style="margin-top:14px"><div style="font-size:12px;font-weight:800;color:var(--navy-ink);margin:0 0 7px 2px">'+gr.dest+'</div><div style="overflow-x:auto;border-radius:8px;border:1px solid var(--g200)"><table class="matrix" style="min-width:100%;font-size:12px"><thead><tr>'+head+'</tr></thead><tbody>'+rows+'</tbody></table></div></div>';
  });
  if(!blocks) return;
  const sec=document.createElement('div');
  sec.className='section';
  sec.innerHTML='<div class="sec-title">Milho — '+order.map(function(o){return o.dest;}).join(', ')+'<span class="sec-sub">'+editedWeek+' · dados exatos da planilha · USD/t</span></div>'+blocks;
  body.appendChild(sec);
}

function renderOceanFreight(){
  const body = document.getElementById('oceanFreightBody');
  if(!body) return;
  ensureOceanWeekStructure();
  const weeks = oceanWeeksDesc();
  const months = oceanMonthsDesc();
  let editedWeek = (oceanEditWeek && weeks.indexOf(oceanEditWeek)>=0) ? oceanEditWeek : weeks[0];
  let editedMonth = (oceanEditMonth && months.indexOf(oceanEditMonth)>=0) ? oceanEditMonth : (editedWeek ? editedWeek.slice(0,7) : months[0]);
  let monthWeeks = weeks.filter(w=>w.slice(0,7)===editedMonth);
  if(!editedWeek || editedWeek.slice(0,7)!==editedMonth){ editedWeek = monthWeeks[0] || weeks[0]; }
  if(editedWeek && (!editedMonth || editedWeek.slice(0,7)!==editedMonth)) editedMonth = editedWeek.slice(0,7);
  monthWeeks = weeks.filter(w=>w.slice(0,7)===editedMonth);
  oceanEditWeek = editedWeek;
  oceanEditMonth = editedMonth;

  const DEST = 'China';
  const base = (state.oceanFreight[editedWeek] && state.oceanFreight[editedWeek][DEST]) ? state.oceanFreight[editedWeek][DEST] : {};
  const vencs = CBOT_VENCIMENTOS;
  const off = (p)=> (typeof OCEAN_PORT_OFFSET[p]==='number' ? OCEAN_PORT_OFFSET[p] : 0);
  const _ofpDay = (state.oceanFreightPorto && state.oceanFreightPorto[editedWeek] && state.oceanFreightPorto[editedWeek][DEST]) || {};
  const portHasTable = (p)=> !!(_ofpDay[p] && Object.keys(_ofpDay[p]).length);
  const val = (p,v)=> (p!=='Santos' && _ofpDay[p] && typeof _ofpDay[p][v]==='number') ? _ofpDay[p][v] : (typeof base[v]==='number' ? base[v]+off(p) : null);

  const ARCOS = [
    { nome:'Arco Sul',   portos:['Santos','Paranaguá','São Francisco do Sul','Rio Grande'] },
    { nome:'Arco Norte', portos:['Itaqui','Barcarena','Santarém'] }
  ];
  const sul = ARCOS[0].portos, norte = ARCOS[1].portos;
  function avgPorts(ports){ let s=0,k=0; ports.forEach(p=>vencs.forEach(v=>{const x=val(p,v); if(typeof x==='number'){s+=x;k++;}})); return k?s/k:0; }
  function rangePorts(ports){ let mn=Infinity,mx=-Infinity; ports.forEach(p=>vencs.forEach(v=>{const x=val(p,v); if(typeof x==='number'){mn=Math.min(mn,x);mx=Math.max(mx,x);}})); return {mn:isFinite(mn)?mn:0,mx:isFinite(mx)?mx:0}; }
  const baseVals = vencs.map(v=>base[v]).filter(x=>typeof x==='number');
  const baseAvg = baseVals.length ? baseVals.reduce((a,b)=>a+b,0)/baseVals.length : 0;
  const kpis = [
    { nm:'China · base (Santos)', avg:baseAvg, mn:baseVals.length?Math.min(...baseVals):0, mx:baseVals.length?Math.max(...baseVals):0, cls:'b' },
    { nm:'Arco Sul · média',   avg:avgPorts(sul),   ...rangePorts(sul),   cls:'a' },
    { nm:'Arco Norte · média', avg:avgPorts(norte), ...rangePorts(norte), cls:'n' }
  ];
  const kpisHtml = kpis.map(k=>`<div class="kpi kpi-big ${k.cls}"><div class="nm">${k.nm}</div><div style="display:flex;align-items:baseline;gap:3px"><div class="vl-big">US$ ${money(k.avg)}</div><div class="un">/t médio</div></div><div style="font-size:10.5px;color:var(--g500);margin-top:4px;font-weight:500">Min ${money(k.mn)} · Max ${money(k.mx)}</div></div>`).join('');

  const nextW = oceanNextWeek(weeks[0]);
  const monthOpts = months.map(m=>`<option value="${m}" ${m===editedMonth?'selected':''}>${oceanMonthLabel(m)}</option>`).join('');
  const weekOpts = monthWeeks.map(w=>`<option value="${w}" ${w===editedWeek?'selected':''}>${w}</option>`).join('');
  const weekCtrl = `<div style="display:flex;align-items:center;gap:8px;flex-wrap:wrap;padding:2px 4px 12px">
    <span style="font-size:11px;font-weight:700;color:var(--g600);text-transform:uppercase;letter-spacing:.04em">Mês</span>
    <select onchange="oceanSetMonth(this.value)" title="Filtrar datas pelo mês">${monthOpts}</select>
    <span style="font-size:11px;font-weight:700;color:var(--g600);text-transform:uppercase;letter-spacing:.04em">Data</span>
    <select onchange="oceanSetWeek(this.value)" title="Datas disponíveis no mês selecionado">${weekOpts}</select>
    <input type="date" value="${editedWeek}" onchange="oceanSetWeek(this.value)" title="Escolher/editar uma data">
    <button class="btn small" onclick="oceanCreateNextWeek()" style="font-size:11px">+ Próximo dia (${nextW})</button>
    <span style="font-size:10.5px;color:var(--g500)">editando <b>${editedWeek}</b> · cada negócio usa o marítimo do dia mais recente ≤ a data do negócio</span>
  </div>`;

  let header = `<th style="position:sticky;left:0;background:var(--navy);z-index:2;text-align:left;min-width:150px">Porto → China</th>`;
  vencs.forEach(v => { header += `<th style="text-align:center;min-width:78px"><div>${v}</div><div style="font-size:9px;opacity:.7;font-weight:500;margin-top:2px;text-transform:none;letter-spacing:0">embarque ${vencToShipMonths(v)}</div></th>`; });

  let rowsHtml='';
  ARCOS.forEach(arco=>{
    rowsHtml += `<tr><td colspan="${vencs.length+1}" style="background:var(--g100);font-weight:800;font-size:10.5px;letter-spacing:.06em;text-transform:uppercase;color:var(--navy-ink);padding:6px 10px;position:sticky;left:0">${arco.nome}</td></tr>`;
    arco.portos.forEach(p=>{
      const o = off(p);
      const isBase = (p==='Santos');
      const tag = isBase ? `<span style="font-size:9px;font-weight:700;color:#0F766E;background:rgba(13,148,136,.12);padding:1px 6px;border-radius:999px;margin-left:6px">base</span>` : portHasTable(p) ? `<span style="font-size:9px;font-weight:700;color:#1D4ED8;background:rgba(29,78,216,.10);padding:1px 6px;border-radius:999px;margin-left:6px">tabela</span>` : `<span style="font-size:10px;font-weight:600;color:var(--g500);margin-left:6px">${o>0?'+':''}${money(o)}</span>`;
      let row = `<td style="position:sticky;left:0;background:var(--g50);z-index:1;font-weight:700;color:var(--navy-ink)">${p}${tag}</td>`;
      vencs.forEach(v=>{
        if(isBase){
          const bv = (typeof base[v]==='number') ? base[v] : '';
          row += `<td style="padding:4px"><input type="number" step="0.1" value="${bv}" data-ocean-week="${editedWeek}" data-ocean-dest="${DEST}" data-ocean-venc="${v}" style="width:100%;border:1px solid var(--g200);border-radius:4px;padding:6px 5px;text-align:right;font-size:11.5px;font-variant-numeric:tabular-nums;background:var(--card)" /></td>`;
        } else {
          const x = val(p,v);
          row += `<td style="text-align:right;padding:7px 8px;font-size:11.5px;font-variant-numeric:tabular-nums;color:var(--g700)">${x==null?'—':money(x)}</td>`;
        }
      });
      rowsHtml += `<tr>${row}</tr>`;
    });
  });
  const offNote = ['Paranaguá','São Francisco do Sul','Rio Grande','Itaqui','Barcarena','Santarém'].filter(p=>!portHasTable(p)).map(p=>`${p} ${off(p)>0?'+':''}${money(off(p))}`).join(' · ');

  body.style.padding = '0';
  body.innerHTML = `
    <div class="section">
      <div style="display:flex;justify-content:space-between;align-items:center;flex-wrap:wrap;gap:10px;padding:0 4px 8px">
        <div style="font-size:11px;color:var(--g500);font-weight:600">Última atualização da matriz</div>
        ${freshnessBadge('ocean', 'Ocean Freight')}
      </div>
    </div>
    <div class="section">
      <div class="sec-title">Médias por destino<span class="sec-sub">China · ${editedWeek} · Arco Sul/Norte</span></div>
      <div class="kpi-strip">${kpisHtml}</div>
    </div>
    <div class="section">
      <div class="sec-title">Matriz USD/t — frete por porto → China<span class="sec-sub">por semana · Santos = base (editável) · demais = base + offset</span></div>
      ${weekCtrl}
      <div style="overflow-x:auto;border-radius:8px;border:1px solid var(--g200)">
        <table class="matrix" style="min-width:100%;font-size:12px;border-radius:8px;overflow:hidden">
          <thead><tr>${header}</tr></thead>
          <tbody>${rowsHtml}</tbody>
        </table>
      </div>
      <div style="font-size:10.5px;color:var(--g500);margin-top:6px;padding:0 4px">Edita o <b>Santos (base)</b> da semana e salva — demais portos recalculam pelo offset. Offsets vs Santos: ${offNote}.</div>
    </div>
    <div class="section">
      <div class="sec-title">Frete Barcaça — Arco Norte<span class="sec-sub">Miritituba → Barcarena · R$/t · sazonal (~165)</span></div>
      <div style="display:flex;align-items:center;gap:10px;flex-wrap:wrap;padding:6px 4px">
        <label style="font-size:12px;color:var(--navy-ink);font-weight:700">Miritituba → Barcarena (R$/t)</label>
        <input id="barcacaBarcarena" type="number" step="1" value="${getBarcaca('Barcarena')}" style="width:120px;border:1px solid var(--g200);border-radius:4px;padding:7px 8px;text-align:right;font-size:12.5px;font-variant-numeric:tabular-nums;background:var(--card)" />
        <button class="btn primary" onclick="saveBarcaca()">Salvar Barcaça</button>
        <span style="font-size:11px;color:var(--g500)">Santarém usa o mesmo valor de Barcarena.</span>
      </div>
    </div>
  `;
  renderOceanCornAddendum(body, editedWeek);
}

function saveBarcaca(){
  const inp = document.getElementById('barcacaBarcarena');
  if(!inp) return;
  const v = parseFloat(inp.value);
  const val = isNaN(v) ? 165 : v;
  if(!state.barcaca) state.barcaca = {...BARCACA_DEFAULT};
  state.barcaca['Barcarena'] = val;
  state.barcaca['Santarem'] = val;
  state.barcaca['Santarém'] = val;
  persist();
  renderAll();
  alert('Frete barcaça salvo: R$ ' + val + '/t (Miritituba → Barcarena/Santarém).');
}

function saveOceanFreight(){
  ensureOceanWeekStructure();
  const inputs = document.querySelectorAll('#oceanFreightBody input[data-ocean-week]');
  inputs.forEach(inp => {
    const wk = inp.getAttribute('data-ocean-week');
    const dest = inp.getAttribute('data-ocean-dest');
    const venc = inp.getAttribute('data-ocean-venc');
    const val = parseFloat(inp.value);
    if(!state.oceanFreight[wk]) state.oceanFreight[wk] = {};
    if(!state.oceanFreight[wk][dest]) state.oceanFreight[wk][dest] = {};
    state.oceanFreight[wk][dest][venc] = isNaN(val) ? 0 : val;
  });
  setCurveTimestamp('ocean');
  persist();
  renderOceanFreight();
  renderAll();
  alert(t('oceanSaved')||'Matriz Ocean Freight salva com sucesso.');
}

function resetOceanFreight(){
  if(!confirm(t('oceanResetConfirm')||'Restaurar valores default do Ocean Freight? (perde edições atuais)')) return;
  state.oceanFreight = structuredClone(OCEAN_FREIGHT_DEFAULT);
  persist();
  renderOceanFreight();
  renderAll();
}

