function bqMA(vals,k){ var out=new Array(vals.length).fill(null); for(var i=0;i<vals.length;i++){ var s=0,n=0; for(var j=Math.max(0,i-k+1);j<=i;j++){ if(vals[j]!=null){s+=vals[j];n++;} } if(n>=Math.min(k,3)) out[i]=s/n; } return out; }
