function renderInlandFreight(){
  const body = document.getElementById('inlandFreightBody');
  if(!body) return;
  const portos = ['Santos', 'Paranaguá', 'Itaqui', 'Barcarena'];
  const fretesValidos = state.fretesRodo.filter(function(f){ return portos.indexOf(f.destino)>=0 && f.semana; });
  const hist = {}, weekCount = {};
  fretesValidos.forEach(function(f){
    weekCount[f.semana]=(weekCount[f.semana]||0)+1;
    if(!hist[f.origem]) hist[f.origem]={};
    if(!hist[f.origem][f.destino]) hist[f.origem][f.destino]={};
    var prev=hist[f.origem][f.destino][f.semana];
    hist[f.origem][f.destino][f.semana]=(prev==null)?f.valor:Math.min(prev,f.valor);
  });
  const allWeeks=Object.keys(weekCount).sort();
  const denseWeeks=allWeeks.filter(function(w){return weekCount[w]>=100;});
  const latest=allWeeks[allWeeks.length-1]||null;
  const prevDense=denseWeeks.length>=2?denseWeeks[denseWeeks.length-2]:(allWeeks.length>=2?allWeeks[allWeeks.length-2]:null);
  if(!inlandWeekCur||allWeeks.indexOf(inlandWeekCur)<0) inlandWeekCur=latest;
  if(!inlandWeekRef||allWeeks.indexOf(inlandWeekRef)<0) inlandWeekRef=latest;
  if(!inlandWeekBase||allWeeks.indexOf(inlandWeekBase)<0) inlandWeekBase=prevDense||latest;
  if(!inlandWeekStart||allWeeks.indexOf(inlandWeekStart)<0) inlandWeekStart=denseWeeks[0]||allWeeks[0]||latest;
  const origensList=Object.keys(hist).map(function(o){return {origem:o, count:Object.keys(hist[o]).length};}).sort(function(a,b){return b.count-a.count;}).slice(0,30);

  const fmtPct=function(p){ return (p>0?'+':'')+p.toFixed(1)+'%'; };
  const kpiColors=['b','n','a','g'];
  const kpisHtml=portos.map(function(p, idx){
    var fp=fretesValidos.filter(function(f){return f.destino===p;});
    var cls=kpiColors[idx%kpiColors.length];
    if(!fp.length) return '<div class="kpi kpi-big '+cls+'" style="opacity:.5"><div class="nm">'+p+'</div><div style="font-size:13px;color:var(--g500);margin-top:6px">sem dados</div></div>';
    var wsP=Object.keys(fp.reduce(function(a,f){a[f.semana]=1;return a;},{})).sort();
    var wCur=wsP[wsP.length-1], wPrev=wsP.length>=2?wsP[wsP.length-2]:null;
    var avgOf=function(w){ var v=fp.filter(function(f){return f.semana===w;}).map(function(f){return f.valor;}); return v.length?v.reduce(function(a,b){return a+b;},0)/v.length:null; };
    var aCur=avgOf(wCur), aPrev=wPrev?avgOf(wPrev):null;
    var nR=fp.filter(function(f){return f.semana===wCur;}).length;
    var dpct=(aPrev!=null&&aCur!=null&&aPrev!==0)?((aCur-aPrev)/aPrev*100):null;
    var dCol=dpct==null?'var(--g400)':(dpct>0?'#DC2626':(dpct<0?'#059669':'var(--g500)'));
    return '<div class="kpi kpi-big '+cls+'">'
      +'<div style="display:flex;justify-content:space-between;align-items:baseline"><div class="nm" style="margin:0">'+p+'</div><div style="font-size:9.5px;color:var(--g400);font-weight:600">'+(wCur||'')+'</div></div>'
      +'<div style="display:flex;align-items:baseline;gap:3px;margin-top:6px"><div class="vl-big">R$ '+money(aCur)+'</div><div class="un">/t me\u0301dio</div></div>'
      +'<div style="font-size:10.5px;margin-top:4px;font-weight:600;color:'+dCol+'">'+(dpct!=null?(fmtPct(dpct)+' vs '+(wPrev?wPrev.slice(-3):'\u2014')):('<span style="color:var(--g500)">'+nR+' rotas</span>'))+'</div>'
      +'</div>';
  }).join('');

  const wkOpts=function(sel){ return allWeeks.slice().reverse().map(function(w){ return '<option value="'+w+'"'+(w===sel?' selected':'')+'>'+w+(weekCount[w]>=100?'':' \u00b7parcial')+'</option>'; }).join(''); };
  const SS='padding:5px 8px;border-radius:6px;border:1px solid var(--g300);font-size:12px';
  const LL='font-size:11px;color:var(--g500);font-weight:600;display:flex;flex-direction:column;gap:3px';
  var ctrls='<div class="a-ctrls-tbl" style="display:flex;flex-wrap:wrap;gap:14px;align-items:flex-end;margin-bottom:12px">';
  ctrls+='<label style="'+LL+'">Visa\u0303o<select onchange="setInlandMode(this.value)" style="'+SS+'">'
    +'<option value="valor"'+(inlandMode==='valor'?' selected':'')+'>Valor (R$/t)</option>'
    +'<option value="compare"'+(inlandMode==='compare'?' selected':'')+'>Comparar 2 semanas (%)</option>'
    +'<option value="accum"'+(inlandMode==='accum'?' selected':'')+'>Acumulado ate\u0301 atual (%)</option>'
    +'</select></label>';
  if(inlandMode==='valor'){
    ctrls+='<label style="'+LL+'">Semana<select onchange="setInlandWeek(\'cur\',this.value)" style="'+SS+'">'+wkOpts(inlandWeekCur)+'</select></label>';
  } else if(inlandMode==='compare'){
    ctrls+='<label style="'+LL+'">Semana base<select onchange="setInlandWeek(\'base\',this.value)" style="'+SS+'">'+wkOpts(inlandWeekBase)+'</select></label>';
    ctrls+='<label style="'+LL+'">Semana ref<select onchange="setInlandWeek(\'ref\',this.value)" style="'+SS+'">'+wkOpts(inlandWeekRef)+'</select></label>';
  } else {
    ctrls+='<label style="'+LL+'">Semana inicial<select onchange="setInlandWeek(\'start\',this.value)" style="'+SS+'">'+wkOpts(inlandWeekStart)+'</select></label>';
    ctrls+='<div style="font-size:11px;color:var(--g500)">\u2192 atual: <b>'+(latest||'\u2014')+'</b></div>';
  }
  if(inlandMode!=='valor'){ ctrls+='<label style="font-size:11px;color:var(--g600);font-weight:600;display:inline-flex;align-items:center;gap:6px;cursor:pointer;margin-left:auto"><input type="checkbox" onchange="setInlandOnlyVar(this.checked)"'+(inlandOnlyVar?' checked':'')+'> Só com variação</label>'; ctrls+='<div style="font-size:10.5px;color:var(--g500);display:flex;align-items:center;gap:8px"><span style="display:inline-flex;align-items:center;gap:4px"><span style="width:12px;height:12px;border-radius:3px;background:rgba(5,150,105,.4);display:inline-block"></span>frete caiu</span><span style="display:inline-flex;align-items:center;gap:4px"><span style="width:12px;height:12px;border-radius:3px;background:rgba(220,38,38,.4);display:inline-block"></span>frete subiu</span></div>'; }
  ctrls+='</div>';

  var header='<th style="position:sticky;left:0;background:var(--navy);z-index:2;text-align:left;min-width:200px">'+(((typeof t==='function')&&t('thOrigin'))||'Origem')+'</th>'; header+='<th style="text-align:left;min-width:120px">Região</th>'; header+='<th style="text-align:center;min-width:78px">'+bqT('inlandTrendCol','12 sem')+'</th>';
  portos.forEach(function(p){ header+='<th style="text-align:center;min-width:100px">'+p+'</th>'; });
  if(inlandMode==='valor') header+='<th style="text-align:center;min-width:80px">'+(((typeof t==='function')&&t('bestPortInland'))||'Melhor')+'</th>';

  var rows=origensList.map(function(o){
    var row='<td style="position:sticky;left:0;background:var(--g50);z-index:1;font-weight:600;font-size:11.5px;color:var(--navy-ink)">'+o.origem+'</td>';
    var _oc=o.origem.split('/'); var _reg=(typeof PRACA_TO_CORREDOR!=='undefined'&&PRACA_TO_CORREDOR[(_oc[0]||'').trim()])||((_oc[1]||'').trim())||'\u2014'; row+='<td style="text-align:left;font-size:11px;color:var(--g600);font-weight:600">'+_reg+'</td>';
    var H=hist[o.origem]; var hasVar=false; var _sw12=allWeeks.slice().sort().slice(-12); var _sv12=_sw12.map(function(w){ var b=null; portos.forEach(function(p){ var x=(H&&H[p])?H[p][w]:null; if(x!=null&&(b==null||x<b)) b=x; }); return b; }); row+='<td style="text-align:center">'+((typeof bqSpark==='function')?bqSpark(_sv12):'')+'</td>';
    if(inlandMode==='valor'){
      var bestVal=Infinity, bestPort=null;
      portos.forEach(function(p){ var r=_valAsOf(H[p], inlandWeekCur); if(r&&r.valor<bestVal){bestVal=r.valor;bestPort=p;} });
      portos.forEach(function(p){ var r=_valAsOf(H[p], inlandWeekCur); if(!r){ row+='<td style="text-align:center;color:var(--g300)">\u00b7</td>'; } else { var _arr=[]; for(var _w in H[p]) if(H[p][_w]!=null) _arr.push(H[p][_w]); var _pc=((typeof bqPctile==='function')&&_arr.length>=8)?bqPctile(_arr,r.valor):null; var _bg=(_pc==null)?'':(_pc>=90?'background:var(--redbg);':(_pc>=70?'background:var(--amberbg);':(_pc<=10?'background:#DCFCE7;':(_pc<=30?'background:var(--greenbg);':'')))); var isBest=p===bestPort; var stc=isBest?'font-weight:700;color:var(--teal);background:#F0FDFA':'color:var(--g700)'; row+='<td'+(_pc!=null?' title="percentil '+_pc+' da rota (hist\u00f3rico)"':'')+' style="text-align:center;font-variant-numeric:tabular-nums;font-size:11.5px;'+_bg+stc+'">'+money(r.valor)+'<div style="font-size:9px;color:var(--g400);font-weight:500;margin-top:1px">'+r.semana.slice(-3)+'</div></td>'; } });
      row+='<td style="text-align:center;font-weight:700;color:var(--teal);font-size:11.5px">'+(bestPort||'\u2014')+'</td>';
    } else {
      var wB=inlandMode==='compare'?inlandWeekBase:inlandWeekStart;
      var wR=inlandMode==='compare'?inlandWeekRef:latest;
      portos.forEach(function(p){
        var rb=_valAsOf(H[p], wB), rr=_valAsOf(H[p], wR);
        if(!rb||!rr||rb.valor===0){ row+='<td style="text-align:center;color:var(--g300)">\u00b7</td>'; return; }
        var pct=(rr.valor-rb.valor)/rb.valor*100; if(Math.abs(pct)>=0.05) hasVar=true;
        var tip=wB+': R$'+money(rb.valor)+'  \u2192  '+wR+': R$'+money(rr.valor);
        row+='<td title="'+tip+'" style="text-align:center;font-variant-numeric:tabular-nums;font-size:11.5px;'+_inlandHeat(pct)+'">'+(pct>0?'+':'')+pct.toFixed(1)+'%</td>';
      });
    }
    return (inlandMode!=='valor' && inlandOnlyVar && !hasVar) ? '' : '<tr>'+row+'</tr>';
  }).join('');

  var subMatriz=inlandMode==='valor'?('Origem \u00d7 porto \u00b7 valor da semana '+(inlandWeekCur||'\u2014'))
    :inlandMode==='compare'?('Variac\u0327a\u0303o % \u00b7 '+(inlandWeekBase||'\u2014')+' \u2192 '+(inlandWeekRef||'\u2014'))
    :('Variac\u0327a\u0303o % acumulada \u00b7 '+(inlandWeekStart||'\u2014')+' \u2192 '+(latest||'\u2014'));

  var _wB=inlandWeekBase,_wR=inlandWeekRef,_mv=[]; if(_wB&&_wR&&_wB!==_wR){ Object.keys(hist).forEach(function(o2){ portos.forEach(function(p2){ var h2=hist[o2]&&hist[o2][p2]; if(h2&&h2[_wB]!=null&&h2[_wR]!=null&&h2[_wB]>0){ var d0=h2[_wR]-h2[_wB]; var pc2=100*d0/h2[_wB]; if(Math.abs(pc2)>=0.05) _mv.push({o:o2,p:p2,d:d0,pc:pc2}); } }); }); _mv.sort(function(x,y){return y.pc-x.pc;}); } function _mvChip(mm){ var up=mm.pc>0; var col=up?'var(--red)':'var(--green)'; var bg=up?'var(--redbg)':'var(--greenbg)'; return '<span style="display:inline-flex;gap:6px;align-items:center;border:1px solid '+col+';background:'+bg+';color:'+col+';border-radius:999px;padding:3px 10px;font-size:11px;font-weight:700;margin:2px">'+(up?'\u25b2':'\u25bc')+' '+mm.o+' \u2192 '+mm.p+' '+(mm.d>0?'+':'')+mm.d.toFixed(0)+' ('+(mm.pc>0?'+':'')+mm.pc.toFixed(1)+'%)</span>'; } var _ups=_mv.slice(0,5), _dns=_mv.filter(function(mm){return mm.pc<0;}).slice(-5).reverse(); var moversCard=(_ups.length||_dns.length)?('<div class="section idc-card" style="position:relative"><div class="sec-title">'+bqT('inlandTopMovers','Top movers da semana')+'<span class="sec-sub">'+_wB+' \u2192 '+_wR+' \u00b7 rota \u00d7 porto</span></div><div>'+_ups.map(_mvChip).join('')+'</div><div style="margin-top:4px">'+_dns.map(_mvChip).join('')+'</div></div>'):'';
  body.style.padding='0';
  body.innerHTML=''
    +'<div class="section"><div class="sec-title">'+bqT('inlandAvgByPort','M\u00e9dias por porto')+'<span class="sec-sub">'+portos.length+' portos \u00b7 '+origensList.length+' '+bqT('inlandOriginsCovered','origens cobertas')+'</span></div><div class="kpi-strip">'+kpisHtml+'</div></div>'
    +moversCard
    +'<div class="section idc-card" style="position:relative;padding:0"><div class="p-card-h"><div class="p-card-t">Inland Freight Matrix</div><div class="p-card-s">'+subMatriz+'</div></div><div style="padding:14px 16px">'
    +ctrls
    +'<div style="overflow-x:auto;overflow-y:auto;max-height:600px;border-radius:8px;border:1px solid var(--g200)"><table class="matrix" style="min-width:100%;font-size:12px;border-radius:8px;overflow:hidden"><thead><tr style="position:sticky;top:0;z-index:3">'+header+'</tr></thead><tbody>'+rows+'</tbody></table></div>'+((inlandMode==='valor')?('<div style="margin-top:8px;font-size:10.5px;color:var(--g500)">Cor = percentil do valor na pr\u00f3pria rota: <span style="background:#DCFCE7;border-radius:4px;padding:1px 6px">\u2264p10 barato</span> <span style="background:var(--greenbg);border-radius:4px;padding:1px 6px">\u2264p30</span> <span style="background:var(--amberbg);border-radius:4px;padding:1px 6px">\u2265p70</span> <span style="background:var(--redbg);border-radius:4px;padding:1px 6px">\u2265p90 caro</span></div>'):'')+'</div></div>'; try{ if(typeof brzAddCamButtons==='function') brzAddCamButtons(body); }catch(e){}
}
// F72: isolate incomplete legacy operations in READ-ONLY map analytics.
// Never create an indicative replacement when the calculation is unavailable.
let brzMapCalculationIssues=0;
let brzMapCalculationExample=[];
function brzMapSafePortComparison(d){
  try {
    const c=computePortComparison(d);
    if(!c||!Array.isArray(c.results))throw Error('Comparação de portos não disponível');
    return c;
  }catch(e){
    brzMapCalculationIssues++;
    if(brzMapCalculationExample.length<8)brzMapCalculationExample.push(String(d?.id||'sem ID'));
    if(brzMapCalculationIssues<=3)console.warn('[BRZ F72] negócio sem replacement de mapa:',d?.id,e);
    return {bestPort:null,results:[]};
  }
}
function renderMapa(){
  if(typeof L === 'undefined'){
    const c = document.getElementById('mapaContainer');
    if(c) c.innerHTML = '<div class="empty">Mapa não carregado: biblioteca Leaflet indisponível. As tabelas e filtros seguem disponíveis.</div>';
    const n = document.getElementById('mapaNarrativa');
    if(n) n.innerHTML = '<div class="note"><strong>Aviso:</strong> o mapa visual depende do Leaflet. Reabra com internet/cache liberado ou use as leituras em tabela.</div>';
    return;
  }
  // === Toolbar com filtros ===
  const produtoAtivo = getActiveProduto();
  const mesLabel = {F:'Jan', H:'Mar', K:'Mai', N:'Jul', Q:'Ago', U:'Set', X:'Nov', Z:'Dez'};
  const hoje = new Date().toISOString().slice(0,10);
  const dtHoje = new Date();
  const anoHoje = dtHoje.getFullYear();
  const mesHojeNum = dtHoje.getMonth() + 1;
  const letraToMes = produtoAtivo==='Milho' ? {H:3,K:5,N:7,U:9,Z:12} : {F:1, H:3, K:5, N:7, Q:8, U:9, X:11};

  // Janelas históricas (anteriores a hoje) — todos os contratos CBOT válidos desde 2024
  const janelasHistoricas = [];
  for(let ano = 2024; ano <= anoHoje + 2; ano++){
    for(const letra of (produtoAtivo==='Milho' ? ['H','K','N','U','Z'] : ['F','H','K','N','Q','U','X'])){
      const m = letraToMes[letra];
      const venc = letra + String(ano).slice(-2);
      const isHistorico = (ano < anoHoje) || (ano === anoHoje && m < mesHojeNum);
      const isAtivo = !isHistorico && (ano < anoHoje + 2);  // até 2 anos a frente
      if(isHistorico) janelasHistoricas.push(venc);
    }
  }

  // Janelas com dados na base
  const mapaDealsUniverse = getActiveDealsReplacement();
  const vencsComDados = new Set(mapaDealsUniverse.map(d=>d.vencCBOT));

  // Janelas ativas que SERÃO exibidas: apenas as que têm dados na base
  const vencimentosProduto = produtoAtivo==='Milho' ? CBOT_MILHO_VENCIMENTOS : CBOT_VENCIMENTOS;
  const ativasComDados = vencimentosProduto.filter(v => vencsComDados.has(v));
  // Janelas históricas que SERÃO exibidas: só as que têm dados
  const historicasComDados = janelasHistoricas.filter(v => vencsComDados.has(v));

  // === Toolbar reorganizada: 2 grupos claros ("O quê" e "Quando") ===
  // 1) Vencimento → SELECT com todas as opções (ativas em destaque, históricas separadas)
  // 2) Quando → 3 modos: Sempre | Um dia (snapshot) | Período

  // Modo atual do Quando (vem da var de estado, NÃO inferida das datas — assim
  // o usuário pode clicar em "Período" e os inputs aparecem mesmo sem datas)
  const quandoMode = mapaQuandoMode || 'sempre';

  // Monta options do select de vencimento — label inclui embarque
  const fmtVencLabel = (v) => `${v} · embarque ${vencToShipMonths(v)}`;
  let vencOptions = `<option value="todos"${mapaVenc==='todos'?' selected':''}>${t('allWindows')||'Todos vencimentos'}</option>`;
  if(ativasComDados.length){
    vencOptions += `<optgroup label="${t('activeWindows')||'Ativas'}">`;
    ativasComDados.forEach(v=>{
      vencOptions += `<option value="${v}"${mapaVenc===v?' selected':''}>${fmtVencLabel(v)}</option>`;
    });
    vencOptions += `</optgroup>`;
  }
  if(historicasComDados.length){
    vencOptions += `<optgroup label="${t('history')||'Histórico'}">`;
    historicasComDados.forEach(v=>{
      vencOptions += `<option value="${v}"${mapaVenc===v?' selected':''}>${fmtVencLabel(v)}</option>`;
    });
    vencOptions += `</optgroup>`;
  }

  // Helper: botão de segmento (Sempre / Um dia / Período)
  const segBtn = (val, label, isActive) =>
    `<button onclick="setMapaQuandoMode('${val}')" style="border:0;padding:6px 14px;font-size:11px;font-weight:600;cursor:pointer;background:${isActive?'var(--teal)':'transparent'};color:${isActive?'#fff':'var(--g700)'};border-right:${val==='periodo'?'0':'1px solid var(--g200)'}">${label}</button>`;

  const isFiltered = mapaVenc !== 'todos' || quandoMode !== 'sempre' || mapaSafraFilter !== 'todos';

  // Banner global de freshness (aparece se alguma curva está outdated)
  const fbox = document.getElementById('mapaFreshness');
  if(fbox) fbox.innerHTML = '';

  const mapaSafras = ['todos','disponivel'].concat(brzSafraLista(getActiveDeals()));
  if(!mapaSafras.includes(mapaSafraFilter)) mapaSafraFilter = 'todos';
  const _mapaSfBtns = mapaSafras.map(s=>`<button class="tab ${mapaSafraFilter===s?'active':''}" onclick="setMapaSafra('${s}')" style="font-size:10.5px;padding:4px 10px">${safraLabel(s)}</button>`).join('');

  document.getElementById('mapaToolbar').innerHTML = `
    <div style="display:flex;flex-direction:column;gap:8px;width:100%">
      <!-- Linha 0: Filtro Safra -->
      <div style="display:flex;gap:5px;align-items:center;flex-wrap:wrap">
        <span style="font-size:10.5px;color:var(--g500);font-weight:700;letter-spacing:.4px;text-transform:uppercase;min-width:76px">Safra:</span>
        <div style="display:flex;gap:4px;flex-wrap:wrap">${_mapaSfBtns}</div>
      </div>
      <!-- Linha 1: Vencimento + Modo Quando + Limpar -->
      <div style="display:flex;gap:14px;align-items:center;flex-wrap:wrap">
        <div style="display:flex;gap:8px;align-items:center">
          <span style="font-size:10.5px;color:var(--g500);font-weight:700;letter-spacing:.4px;text-transform:uppercase">${t('window')||'Vencimento'}:</span>
          <select onchange="setMapaVenc(this.value)" style="min-width:200px">
            ${vencOptions}
          </select>
        </div>
        <div style="display:flex;gap:8px;align-items:center">
          <span style="font-size:10.5px;color:var(--g500);font-weight:700;letter-spacing:.4px;text-transform:uppercase">${t('when')||'Quando'}:</span>
          <div style="display:inline-flex;border:1px solid var(--g200);border-radius:6px;overflow:hidden;background:var(--card)">
            ${segBtn('sempre',  t('always')||'Sempre',     quandoMode==='sempre')}
            ${segBtn('dia',     t('oneDay')||'Um dia',     quandoMode==='dia')}
            ${segBtn('periodo', t('period')||'Período',    quandoMode==='periodo')}
          </div>
        </div>
        ${isFiltered ? `<button class="btn small" onclick="clearMapaFiltros()" style="font-size:10.5px;padding:6px 10px;margin-left:auto">× Limpar filtros</button>` : ''}
      </div>
      <!-- Linha 2: Inputs de data — só aparecem conforme o modo -->
      ${quandoMode === 'dia' ? `
      <div style="display:flex;gap:8px;align-items:center;padding-left:78px">
        <input type="date" id="mapaDataUnica" value="${mapaDataUnica||''}" max="${hoje}" onchange="setMapaDataUnica(this.value)" style="border:1px solid var(--g200);border-radius:6px;padding:6px 10px;font-size:11.5px">
        ${mapaDataUnica?`<span style="font-size:10.5px;color:var(--g700);font-weight:600">→ ${fmtDate(mapaDataUnica)}</span>`:`<span style="font-size:10.5px;color:var(--g500);font-style:italic">Selecione um dia para ver a fotografia do mercado</span>`}
      </div>
      ` : ''}
      ${quandoMode === 'periodo' ? `
      <div style="display:flex;gap:8px;align-items:center;padding-left:78px">
        <input type="date" id="mapaDataIni" value="${mapaDataInicio||''}" max="${hoje}" onchange="setMapaDataInicio(this.value)" style="border:1px solid var(--g200);border-radius:6px;padding:6px 10px;font-size:11.5px">
        <span style="color:var(--g500);font-size:11px">${t('to')||'até'}</span>
        <input type="date" id="mapaDataFim" value="${mapaDataFim||''}" max="${hoje}" onchange="setMapaDataFim(this.value)" style="border:1px solid var(--g200);border-radius:6px;padding:6px 10px;font-size:11.5px">
        ${(mapaDataInicio && mapaDataFim)?`<span style="font-size:10.5px;color:var(--g700);font-weight:600">→ ${fmtDate(mapaDataInicio)} – ${fmtDate(mapaDataFim)}</span>`:`<span style="font-size:10.5px;color:var(--g500);font-style:italic">Defina início e fim para ver a evolução</span>`}
      </div>
      ` : ''}
    </div>`;

  // === Tabs de métrica abaixo do mapa (na verdade, em cima do container) ===
  const metrics = [
    {k:'basis', label:t('metricBasis')},
    {k:'preco', label:t('metricPrice')},
    {k:'volume', label:t('metricVolume')}
  ];
  document.getElementById('mapaTabs').innerHTML = metrics.map(m=>`<button class="tab ${mapaMetric===m.k?'active':''}" onclick="setMapaMetric('${m.k}')">${m.label}</button>`).join('');

  // === Filtrar negócios ===
  let dealsFiltro = mapaDealsUniverse.slice();
  // Filtro de safra
  if(mapaSafraFilter !== 'todos'){
    dealsFiltro = dealsFiltro.filter(d => brzSafraMatch(d, mapaSafraFilter));
  }
  if(mapaVenc !== 'todos'){
    dealsFiltro = dealsFiltro.filter(d => d.vencCBOT === mapaVenc);
  }
  if(mapaDataUnica){
    // Snapshot do dia: mostra apenas negócios fechados nesta data específica
    dealsFiltro = dealsFiltro.filter(d => d.data === mapaDataUnica);
  } else {
    if(mapaDataInicio){
      dealsFiltro = dealsFiltro.filter(d => d.data >= mapaDataInicio);
    }
    if(mapaDataFim){
      dealsFiltro = dealsFiltro.filter(d => d.data <= mapaDataFim);
    }
  }

  // === Agregar por corredor ===
  // Para cada negócio: melhor porto → rep.basis.
  // Se volume real existir, média ponderada por volume. Se volume = 0, média simples por negócio.
  const agg = {};  // corredor → {basisVolSum, precoVolSum, volSum, calcWeightSum, count, deals[], modais{}, portos{}}
  brzMapCalculationIssues=0; brzMapCalculationExample=[];
  // Mostra o mapa imediatamente, antes de cálculos de milhares de negócios.
  function showMapLayer(data,col){
    try{renderMapaLeaflet(data,col)}catch(e){console.error('[BRZ F72] Leaflet',e);
      const target=document.getElementById('mapaContainer');
      if(target)target.setAttribute('data-brz-map-error',String(e?.message||e).slice(0,180));
    }
  }
  showMapLayer({},()=> '#bfc8c4');
  const renderSequence=window.__BRZ_MAP_RENDER_SEQUENCE=(window.__BRZ_MAP_RENDER_SEQUENCE||0)+1;
  const progress=document.getElementById('mapaSub');
  if(progress)progress.textContent='Calculando corredores · 0 / '+dealsFiltro.length;
  const batchSize=40;
  function handleMapDeal(d){
    const cmp = brzMapSafePortComparison(d);
    const best = cmp.results.find(r => r.porto === cmp.bestPort)?.best;
    if(!best) return;
    const k = d.corredor;
    if(!agg[k]) agg[k] = {basisVolSum:0, precoVolSum:0, volSum:0, calcWeightSum:0, count:0, deals:[], portos:{}, modais:{}};
    const a = agg[k];
    const v = n(d.volume);
    const calcWeight = v > 0 ? v : 1;
    a.basisVolSum += best.replacementBasis * calcWeight;
    a.precoVolSum += n(d.preco) * calcWeight;
    a.volSum += v;
    a.calcWeightSum += calcWeight;
    a.count++;
    a.deals.push({id:d.id, data:d.data, origem:d.origem, comprador:d.comprador, vendedor:d.vendedor, vol:v, preco:n(d.preco), basis:best.replacementBasis, porto:cmp.bestPort, modal:best.modal});
    a.portos[cmp.bestPort] = (a.portos[cmp.bestPort]||0) + calcWeight;
    a.modais[best.modal] = (a.modais[best.modal]||0) + calcWeight;
  }

  function finalizeMap(){
    if(renderSequence!==window.__BRZ_MAP_RENDER_SEQUENCE)return;
  // === Calcular escala de cor ===
  const vals = Object.values(agg).map(a => {
    if(mapaMetric === 'basis') return a.basisVolSum / (a.calcWeightSum || a.volSum || 1);
    if(mapaMetric === 'preco') return a.precoVolSum / (a.calcWeightSum || a.volSum || 1);
    return a.volSum;
  });
  let minV = vals.length ? Math.min(...vals) : 0;
  let maxV = vals.length ? Math.max(...vals) : 1;
  if(minV === maxV) maxV = minV + 1;

  function colorFor(val){
    let t;  // 0 ruim (vermelho) → 1 bom (verde)
    if(mapaMetric === 'basis'){
      t = 1 - (val - minV)/(maxV - minV);  // basis baixo = bom
    } else {
      t = (val - minV)/(maxV - minV);  // preço/volume alto = "interessante"
    }
    t = Math.max(0, Math.min(1, t));
    let r,g,b;
    if(t < 0.5){
      const k = t/0.5;
      r = Math.round(180 + (220-180)*k);
      g = Math.round(40 + (170-40)*k);
      b = Math.round(30 + (40-30)*k);
    } else {
      const k = (t-0.5)/0.5;
      r = Math.round(220 + (35-220)*k);
      g = Math.round(170 + (130-170)*k);
      b = Math.round(40 + (75-40)*k);
    }
    return `rgb(${r},${g},${b})`;
  }

  // === Desenho final Leaflet ===
  showMapLayer(agg, colorFor);

  // === Card "O QUE ACONTECEU" no período ===
  // A falha de uma análise não derruba as outras nem apaga o mapa.
  const safePanel=(label,element,render)=>{
    try{return render()}catch(e){
      console.error('[BRZ F72] '+label,e);
      const node=document.getElementById(element);
      if(node){const notice=document.createElement('div');notice.className='note';
        notice.setAttribute('role','status');
        notice.textContent='Dados insuficientes para '+label+'. '+String(e?.message||e).slice(0,180);
        node.replaceChildren(notice);}
    }
  };
  safePanel('Resumo','mapaSummary',()=>renderMapaSummary(dealsFiltro,agg));
  safePanel('Corredor','mapaCorredorDetail',()=>renderMapaCorredorDetail(agg));
  safePanel('VPL','mapaVplTabela',()=>renderMapaVplTabela(dealsFiltro));
  safePanel('Análise','mapaNarrativa',()=>renderMapaNarrativa(dealsFiltro,agg));
  safePanel('Tabela','mapaTableBody',()=>renderMapaTable(agg));

  // === Subtitle dinâmico ===
  const sub = [];
  sub.push(`${dealsFiltro.length} ${t('dealsLower')}`);
  if(mapaSafraFilter !== 'todos') sub.push(safraLabel(mapaSafraFilter));
  if(mapaVenc !== 'todos') sub.push(`${t('windowSing')} ${mapaVenc}`);
  if(mapaDataUnica) sub.push(`${t('snapshotOfDayPrefix')} ${mapaDataUnica}`);
  else if(mapaDataInicio || mapaDataFim) sub.push(`${t('periodPrefix')} ${mapaDataInicio||'…'} ${t('to')} ${mapaDataFim||'…'}`);
  if(brzMapCalculationIssues)sub.push(brzMapCalculationIssues+' operações sem cálculo (não estimadas)');
  document.getElementById('mapaSub').textContent = sub.join(' · ');
  }
  function nextBatch(offset){
    if(renderSequence!==window.__BRZ_MAP_RENDER_SEQUENCE)return;
    const stop=Math.min(offset+batchSize,dealsFiltro.length);
    for(let i=offset;i<stop;i++)handleMapDeal(dealsFiltro[i]);
    if(progress)progress.textContent='Calculando corredores · '+stop+' / '+dealsFiltro.length;
    if(stop<dealsFiltro.length){
      setTimeout(()=>nextBatch(stop),0);
    }else finalizeMap();
  }
  nextBatch(0);
}


/* Singleton — o mapa Leaflet só pode ser criado uma vez */
let _leafletMap = null;
let _leafletLayer = null;  // grupo de markers
let _mapaUiState = {panelHidden:false, tableHidden:false, fullscreen:false};

function renderMapaLeaflet(agg, colorFor){
  const container = document.getElementById('mapaContainer');
  if(!container) return;

  // Espera o Leaflet carregar do CDN (assíncrono)
  if(typeof L === 'undefined'){
    container.innerHTML = '<div class="empty" style="padding:40px">Carregando mapa…</div>';
    setTimeout(()=>renderMapaLeaflet(agg, colorFor), 200);
    return;
  }

  // Se container ainda não tem altura (aba acabou de ficar visível),
  // espera o próximo frame para inicializar
  if(container.clientHeight < 50){
    requestAnimationFrame(()=>renderMapaLeaflet(agg, colorFor));
    return;
  }

  // Inicialização lazy (1ª vez)
  if(!_leafletMap){
    _leafletMap = L.map(container, {
      center: [-14.5, -52],
      zoom: 4,
      zoomControl: true,
      attributionControl: true,
      scrollWheelZoom: true,
      worldCopyJump: false
    });
    L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png', {
      attribution: '&copy; OpenStreetMap',
      maxZoom: 11,
      minZoom: 3
    }).addTo(_leafletMap);
    _leafletLayer = L.layerGroup().addTo(_leafletMap);
    var _applyZoomCls=function(){try{var _c=_leafletMap.getContainer();if(_c)_c.classList.toggle('mapZoomLow',_leafletMap.getZoom()<6);}catch(e){}};
    _leafletMap.on('zoomend',_applyZoomCls); _applyZoomCls();
  } else {
    _leafletLayer.clearLayers();
  }

  // Força recalc do tamanho do mapa em múltiplos timings — resolve quirks
  // de quando o container aparece após troca de aba ou resize do painel
  requestAnimationFrame(()=>{
    _leafletMap.invalidateSize();
    setTimeout(()=>_leafletMap.invalidateSize(), 150);
    setTimeout(()=>_leafletMap.invalidateSize(), 400);
  });

  // Portos (estrelas azuis)
  Object.entries(MAP_DATA.portos).forEach(([nome, [lat,lng]])=>{
    const m = L.circleMarker([lat,lng], {
      radius: 8, fillColor: 'var(--blue)', color: '#fff', weight: 2, fillOpacity: 1
    });
    m.bindTooltip(`<b>Porto de ${nome}</b>`, {permanent:false, direction:'top', className:'leaflet-tooltip-custom'});
    _leafletLayer.addLayer(m);
  });

  // Pins dos corredores
  Object.entries(MAP_DATA.corredores).forEach(([corr, [lat,lng]])=>{
    const a = agg[corr];
    let radius, color, label;
    if(!a){
      // Sem dados — pin cinza pequeno
      radius = 5;
      color = '#bfc8c4';
      label = corr + ' (sem dados)';
      const m = L.circleMarker([lat,lng], {
        radius, fillColor: color, color: '#fff', weight: 1.5, fillOpacity: 0.6
      });
      m.bindTooltip(label, {permanent:false, direction:'top'});
      m.on('click', ()=>{ mapaCorredorSelecionado = corr; renderMapa(); });
      _leafletLayer.addLayer(m);
      return;
    }
    const basis = a.basisVolSum / (a.calcWeightSum || a.volSum || 1);
    const preco = a.precoVolSum / (a.calcWeightSum || a.volSum || 1);
    const val = mapaMetric==='basis' ? basis : (mapaMetric==='preco' ? preco : a.volSum);
    color = colorFor(val);
    const isSelected = mapaCorredorSelecionado === corr;
    radius = isSelected ? 13 : 11;

    let mainText;
    if(mapaMetric==='basis') mainText = (basis>=0?'+':'') + basis.toFixed(0);
    else if(mapaMetric==='preco') mainText = preco.toFixed(0);
    else mainText = (a.volSum/1000).toFixed(1) + 'k';

    // DivIcon — pin redondo com número dentro + label do corredor acima
    const html = `
      <div style="position:relative;transform:translate(-50%,-50%);text-align:center">
        <div style="background:${color};color:#fff;width:${radius*2}px;height:${radius*2}px;border-radius:50%;border:${isSelected?'3px':'2px'} solid ${isSelected?'var(--g900)':'#fff'};display:flex;align-items:center;justify-content:center;font-weight:800;font-size:10px;box-shadow:0 2px 6px rgba(0,0,0,.3)">
          ${mainText}
        </div>
        <div class="mapaPinName" style="position:absolute;top:-18px;left:50%;transform:translateX(-50%);background:rgba(255,255,255,.92);padding:1px 6px;border-radius:6px;font-size:9.5px;font-weight:700;color:var(--g900);white-space:nowrap;border:1px solid #D1D5DB;box-shadow:0 1px 3px rgba(0,0,0,.1)">${corr}</div>
      </div>`;
    const icon = L.divIcon({html, className:'mapaPin', iconSize:[0,0], iconAnchor:[0,0]});
    const marker = L.marker([lat,lng], {icon, riseOnHover:true});

    const tooltip = `<div style="line-height:1.5">
      <b style="font-size:12px">${corr}</b><br>
      <b>${a.count}</b> negócios · <b>${tons(a.volSum)}</b> t<br>
      Preço médio: <b>R$ ${money(preco)}</b><br>
      Rep. Basis: <b style="color:${basis<=0?'var(--green)':basis<=50?'var(--amber)':'var(--red)'}">${basis>=0?'+':''}${fmtBasis(basis)} ¢/bu</b>
    </div>`;
    marker.bindTooltip(tooltip, {permanent:false, direction:'top', sticky:true});
    marker.on('click', ()=>{ mapaCorredorSelecionado = corr; renderMapa(); });
    _leafletLayer.addLayer(marker);
  });

  // Legenda flutuante (recria a cada render)
  if(_leafletMap._legendControl){ _leafletMap.removeControl(_leafletMap._legendControl); }
  const legLabels = {
    basis: ['Basis baixo (competitivo)', 'Basis alto (caro)'],
    preco: ['Preço alto', 'Preço baixo'],
    volume: ['Volume alto', 'Volume baixo']
  };
  const [verdeLab, vermLab] = legLabels[mapaMetric];
  const Legend = L.Control.extend({
    options: {position:'bottomleft'},
    onAdd: function(){
      const div = L.DomUtil.create('div','');
      div.style.background = '#fff';
      div.style.padding = '10px 12px';
      div.style.borderRadius = '8px';
      div.style.boxShadow = '0 2px 8px rgba(0,0,0,.18)';
      div.style.fontFamily = 'Inter,sans-serif';
      div.style.fontSize = '10px';
      div.innerHTML = `
        <div style="font-weight:700;color:var(--g900);margin-bottom:5px;font-size:11px">${mapaMetric==='basis'?'Replacement Basis':mapaMetric==='preco'?'Preço médio':'Volume'} · ${mapaVenc==='todos'?'todos vencimentos':mapaVenc}</div>
        <div style="display:flex;align-items:center;gap:6px">
          <span style="color:var(--green);font-weight:700">${verdeLab}</span>
          <div style="display:flex;gap:1px">
            <span style="background:rgb(35,130,75);width:18px;height:10px;display:inline-block"></span>
            <span style="background:rgb(120,160,60);width:18px;height:10px;display:inline-block"></span>
            <span style="background:rgb(220,170,40);width:18px;height:10px;display:inline-block"></span>
            <span style="background:rgb(200,100,35);width:18px;height:10px;display:inline-block"></span>
            <span style="background:rgb(180,40,30);width:18px;height:10px;display:inline-block"></span>
          </div>
          <span style="color:var(--red);font-weight:700">${vermLab}</span>
        </div>`;
      return div;
    }
  });
  _leafletMap._legendControl = new Legend();
  _leafletMap._legendControl.addTo(_leafletMap);
}

/* ═══ Botões de expansão do mapa ═══ */
function mapaTogglePanel(){
  _mapaUiState.panelHidden = !_mapaUiState.panelHidden;
  const right = document.getElementById('mapaRightCol');
  if(_mapaUiState.panelHidden){
    right.style.display = 'none';
  } else {
    right.style.display = '';
  }
  if(_leafletMap) setTimeout(()=>_leafletMap.invalidateSize(), 200);
}
function mapaToggleTable(){
  _mapaUiState.tableHidden = !_mapaUiState.tableHidden;
  document.getElementById('mapaTableWrap').style.display = _mapaUiState.tableHidden ? 'none' : '';
  if(_leafletMap) setTimeout(()=>_leafletMap.invalidateSize(), 200);
}
function mapaFullscreen(){
  const screen = document.getElementById('mapa');
  if(!_mapaUiState.fullscreen){
    screen.classList.add('mapaFullscreen');
    document.body.style.overflow = 'hidden';
    _mapaUiState.fullscreen = true;
    const btn = document.getElementById('btnFullscreen');
    if(btn) btn.textContent = '✕ Sair';
  } else {
    screen.classList.remove('mapaFullscreen');
    document.body.style.overflow = '';
    _mapaUiState.fullscreen = false;
    const btn = document.getElementById('btnFullscreen');
    if(btn) btn.textContent = '⛶ Expandir';
  }
  if(_leafletMap) setTimeout(()=>_leafletMap.invalidateSize(), 350);
}


/* Card de resumo "o que aconteceu" — comparativo período atual vs anterior */
function renderMapaSummary(deals, agg){
  const box = document.getElementById('mapaSummary');
  if(deals.length === 0){
    box.innerHTML = `<div class="card" style="padding:14px"><div class="empty">${t('noDealsInWindow')}</div></div>`;
    return;
  }

  // Agregado total do período
  const totalVol = Object.values(agg).reduce((a,b)=>a+b.volSum,0);
  const totalWeight = Object.values(agg).reduce((a,b)=>a+(b.calcWeightSum || b.volSum || b.count || 0),0);
  const totalDeals = Object.values(agg).reduce((a,b)=>a+b.count,0);
  const basisMedio = Object.values(agg).reduce((a,b)=>a+b.basisVolSum,0) / (totalWeight||1);
  const precoMedio = Object.values(agg).reduce((a,b)=>a+b.precoVolSum,0) / (totalWeight||1);

  // CBOT e câmbio médio dos negócios filtrados: volume real como peso; se volume = 0, média simples por negócio.
  let cbotSum=0, cambioSum=0, w=0;
  deals.forEach(d=>{ const ww = n(d.volume) > 0 ? n(d.volume) : 1; cbotSum += n(d.cbot)*ww; cambioSum += n(d.cambio)*ww; w += ww; });
  const cbotMed = w ? cbotSum/w : 0;
  const cambioMed = w ? cambioSum/w : 0;

  // Compara com período anterior (mesmo número de dias, anteriores)
  let comparativo = '';
  if(mapaDataInicio && mapaDataFim){
    const dias = (new Date(mapaDataFim) - new Date(mapaDataInicio)) / 86400000;
    const iniAnt = new Date(new Date(mapaDataInicio).getTime() - (dias+1)*86400000).toISOString().slice(0,10);
    const fimAnt = new Date(new Date(mapaDataInicio).getTime() - 86400000).toISOString().slice(0,10);
    const dealsAnt = getActiveDealsReplacement().filter(d => d.data >= iniAnt && d.data <= fimAnt && (mapaVenc==='todos' || d.vencCBOT===mapaVenc));
    if(dealsAnt.length){
      let bAnt=0, pAnt=0, cAnt=0, xAnt=0, wAnt=0;
      dealsAnt.forEach(d=>{
        const cmp = brzMapSafePortComparison(d);
        const best = cmp.results.find(r=>r.porto===cmp.bestPort)?.best;
        const v = n(d.volume);
        const ww = v > 0 ? v : 1;
        if(best){ bAnt += best.replacementBasis*ww; }
        pAnt += n(d.preco)*ww;
        cAnt += n(d.cbot)*ww;
        xAnt += n(d.cambio)*ww;
        wAnt += ww;
      });
      const bMedAnt = wAnt ? bAnt/wAnt : 0, pMedAnt = wAnt ? pAnt/wAnt : 0, cMedAnt = wAnt ? cAnt/wAnt : 0, xMedAnt = wAnt ? xAnt/wAnt : 0;
      const dBasis = basisMedio - bMedAnt;
      const dPreco = precoMedio - pMedAnt;
      const dCbot = cbotMed - cMedAnt;
      const dCambio = cambioMed - xMedAnt;
      comparativo = `
        <div style="font-size:11px;color:var(--muted);margin-top:9px;line-height:1.6">
          <b style="color:var(--g900)">${t('vsPrefix')} ${iniAnt} ${t('to')} ${fimAnt}:</b><br>
          <span style="color:${dBasis<=0?'var(--green)':'var(--red)'}">${dBasis>=0?'▲':'▼'} ${t('repBasisShort')} ${dBasis>=0?'+':''}${money(dBasis)} ¢</span> ·
          <span style="color:${dPreco>=0?'var(--green)':'var(--red)'}">${dPreco>=0?'▲':'▼'} ${t('priceShort')} ${dPreco>=0?'+':''}R$ ${money(dPreco)}</span><br>
          CBOT ${dCbot>=0?'+':''}${money(dCbot)} ¢/bu · ${t('fxRate')} ${dCambio>=0?'+':''}R$ ${money(dCambio)}
        </div>`;
    }
  }

  // Basis Paranaguá (FOB - CBOT) e Basis CFR China (CFR - CBOT)
  // Agora ponderado por deal usando ocean freight da matriz por vencimento
  let fobPng = 0, fobPngW = 0;
  let cfrChinaW = 0, cfrChinaV = 0;
  let freteMaritimoMedio = 0, freteMaritimoVol = 0;
  deals.forEach(d=>{
    const cmp = brzMapSafePortComparison(d);
    const pgua = cmp.results.find(r=>r.porto==='Paranaguá')?.best;
    if(pgua){
      const vol = n(d.volume);
      const ww = vol > 0 ? vol : 1;
      fobPng += pgua.replacementFOB*ww;
      fobPngW += ww;
      const seaUsd = brzOceanUsdT(d, null);
      if(seaUsd!=null){
        const cfrCbu = pgua.replacementFOB + (seaUsd * 0.06 / 2.2046 * 100);
        cfrChinaW += cfrCbu * ww;
        cfrChinaV += ww;
        freteMaritimoMedio += seaUsd * ww;
        freteMaritimoVol += ww;
      }
    }
  });
  const fobPngMed = fobPngW ? fobPng/fobPngW : 0;
  const cfrChina = cfrChinaV ? cfrChinaW/cfrChinaV : 0;
  const freteMaritimo = freteMaritimoVol ? freteMaritimoMedio/freteMaritimoVol : 45;
  // Convertendo pra basis (prêmio sobre CBOT)
  const basisPng = fobPngMed - cbotMed;
  const basisCfr = cfrChina - cbotMed;

  box.innerHTML = `
    <div style="background:var(--card);border:1px solid var(--g200);border-radius:10px;padding:18px;box-shadow:var(--shadow-sm)">
      <div class="sec-title" style="font-size:12px;margin-bottom:12px">${t('whatHappened')}</div>
      <div style="display:grid;grid-template-columns:1fr 1fr;gap:10px">
        <div class="metric"><label>${t('deals')}</label><strong>${totalDeals}</strong></div>
        <div class="metric"><label>${t('volume')}</label><strong>${tons(totalVol)} t</strong></div>
        <div class="metric"><label>${t('avgPrice')}</label><strong>R$ ${money(precoMedio)}</strong></div>
        <div class="metric"><label>${t('avgRepBasis')}</label><strong style="color:${basisMedio<=0?'var(--green)':basisMedio<=50?'var(--amber)':'var(--red)'}">${basisMedio>=0?'+':''}${fmtBasis(basisMedio)} ¢</strong></div>
        <div class="metric"><label>${t('avgCbot')}</label><strong>${money(cbotMed)} ¢/bu</strong></div>
        <div class="metric"><label>${t('avgFx')}</label><strong>R$ ${money(cambioMed)}</strong></div>
        ${fobPngMed?`<div class="metric"><label>${t('basisParanagua')}</label><strong style="color:${basisPng<=0?'var(--green)':basisPng<=80?'var(--amber)':'var(--red)'}">${basisPng>=0?'+':''}${fmtBasis(basisPng)} ¢</strong></div>`:''}
        ${fobPngMed?`<div class="metric"><label>${t('basisCfrChina')} (+${money(freteMaritimo)} USD/t)</label><strong style="color:${basisCfr<=0?'var(--green)':basisCfr<=200?'var(--amber)':'var(--red)'}">${basisCfr>=0?'+':''}${fmtBasis(basisCfr)} ¢</strong></div>`:''}
      </div>
      ${comparativo}
    </div>`;
}

/* Detalhe do corredor selecionado (drill-down ao clicar no pin) */
function renderMapaCorredorDetail(agg){
  const box = document.getElementById('mapaCorredorDetail');
  if(!mapaCorredorSelecionado){
    box.innerHTML = '';
    return;
  }
  const corr = mapaCorredorSelecionado;
  const a = agg[corr];
  if(!a){
    box.innerHTML = `<div class="card" style="padding:14px">
      <div style="display:flex;justify-content:space-between;align-items:center"><div class="title" style="margin:0">${corr}</div><button class="btn small ghost" onclick="mapaCorredorSelecionado=null;renderMapa()">×</button></div>
      <div class="empty" style="padding:14px">${t('noDealsInCorridor')}</div>
    </div>`;
    return;
  }
  const basis = a.basisVolSum / (a.calcWeightSum || a.volSum || 1);
  const preco = a.precoVolSum / (a.calcWeightSum || a.volSum || 1);
  const portoTop = Object.entries(a.portos).sort((a,b)=>b[1]-a[1])[0];
  const modalTop = Object.entries(a.modais).sort((a,b)=>b[1]-a[1])[0];

  box.innerHTML = `<div class="card" style="padding:14px">
    <div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:9px">
      <div class="title" style="margin:0">${corr}</div>
      <button class="btn small ghost" onclick="mapaCorredorSelecionado=null;renderMapa()" style="padding:2px 8px">×</button>
    </div>
    <div style="display:grid;grid-template-columns:1fr 1fr;gap:7px;margin-bottom:10px">
      <div class="metric"><label>${t('deals')}</label><strong>${a.count}</strong></div>
      <div class="metric"><label>${t('volume')}</label><strong>${tons(a.volSum)} t</strong></div>
      <div class="metric"><label>${t('avgPrice')}</label><strong>R$ ${money(preco)}</strong></div>
      <div class="metric"><label>${t('repBasisShort')}</label><strong style="color:${basis<=0?'var(--green)':basis<=50?'var(--amber)':'var(--red)'}">${basis>=0?'+':''}${fmtBasis(basis)} ¢</strong></div>
      <div class="metric"><label>${t('mainPort')}</label><strong>${portoTop ? portoTop[0] : '—'} (${a.volSum > 0 ? tons(portoTop ? portoTop[1] : 0) + ' t' : (portoTop ? Math.round(portoTop[1]) : 0) + ' neg'})</strong></div>
      <div class="metric"><label>${t('mainModal')}</label><strong>${modalTop ? modalTop[0] : '—'}</strong></div>
    </div>
    <div style="font-size:11.5px;color:var(--muted);font-weight:500;margin-bottom:6px">${t('windowDeals')}</div>
    <div style="max-height:200px;overflow-y:auto;border:1px solid var(--line);border-radius:8px">
      <table class="table" style="font-size:10.5px">
        <thead><tr><th>${t('thId')}</th><th>${t('thDate')}</th><th>${t('thOrigin')}</th><th class="num">${t('thVol')}</th><th class="num">${t('thPrice')}</th><th class="num">${t('repBasisShort')}</th></tr></thead>
        <tbody>${a.deals.sort((a,b)=>b.data.localeCompare(a.data)).slice(0,15).map(x=>`<tr>
          <td><span class="tag neutral" style="font-size:9.5px">${x.id}</span></td>
          <td>${fmtDate(x.data)}</td>
          <td title="${x.origem.replace(/"/g,'&quot;')}" style="max-width:140px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap">${cleanOrigem(x.origem)}</td>
          <td class="num">${tons(x.vol)}</td>
          <td class="num">R$ ${money(x.preco)}</td>
          <td class="num">${x.basis>=0?'+':''}${fmtBasis(x.basis)}</td>
        </tr>`).join('')}</tbody>
      </table>
    </div>
  </div>`;
}

/* Tabela de mudanças por corredor — análise com decomposição quando há período */
/* ═══════════════════════════════════════════════════════
   TABELA VPL — Replacement por Corredor Comercial × Dia
   - Linhas: dias com fechamento na base
   - Colunas: 6 corredores comerciais + Prêmio FOB PGA (cada um com Velha/Nova)
   - Cálculo: VPL no preço (i=15% a.a., n=meses até pagamento)
═══════════════════════════════════════════════════════ */

/* Mapeia cada corredor geográfico para um corredor comercial + porto fixo.
   Para MT (que está em "MT Norte" e "MT Médio Norte"), a coluna comercial
   é determinada pela cidade-base do negócio via MT_CIDADE_PARA_COLUNA. */
const MT_CIDADE_PARA_COLUNA = {
  // Oeste MT → Itaqui
  'Sapezal':'oesteMT', 'Campo Novo do Parecis':'oesteMT', 'Brasnorte':'oesteMT',
  'Tangará da Serra':'oesteMT', 'Diamantino':'oesteMT', 'Tapurah':'oesteMT',
  'Campos de Júlio':'oesteMT', 'Comodoro':'oesteMT',
  // Norte MT → Barcarena
  'Sinop':'norteMT', 'Sorriso':'norteMT', 'Matupá':'norteMT',
  'Peixoto de Azevedo':'norteMT', 'Guarantã do Norte':'norteMT',
  'Vera':'norteMT', 'Nova Ubiratã':'norteMT',
  // 163 → Santos (eixo BR-163 central)
  'Lucas do Rio Verde':'163', 'Nova Mutum':'163',
  'Itanhangá':'163', 'Santa Rita do Trivelato':'163',
  // Nordeste/Leste → Sul MT
  'Querência':'sulMT', 'Água Boa':'sulMT', 'Canarana':'sulMT',
  'Confresa':'sulMT', 'Ribeirão Cascalheira':'sulMT', 'Barra do Garça':'sulMT',
  'Nova Xavantina':'sulMT', 'São José do Xingu':'sulMT',
};

/* Decide a coluna comercial pra um negócio do MT, baseado na cidade-base */
function decideMTColuna(deal){
  const cidade = extractCidadeBase(deal.origem);
  if(MT_CIDADE_PARA_COLUNA[cidade]) return MT_CIDADE_PARA_COLUNA[cidade];
  // Fallback por corredor geográfico
  if(deal.corredor === 'MT Médio Norte') return '163';  // padrão
  if(deal.corredor === 'MT Norte') return 'norteMT';   // padrão
  if(deal.corredor === 'MT Nordeste') return 'sulMT';
  if(deal.corredor === 'MT Leste') return 'sulMT';
  if(deal.corredor === 'MT Sul') return 'sulMT';
  if(deal.corredor === 'MT Noroeste') return 'oesteMT';
  return 'sulMT';
}

const CORREDOR_COMERCIAL_MAP = { 'MA Leste': {comercial:'matopiba', portoFixo:null},
  // MT é resolvido dinamicamente por cidade — esses são apenas placeholders
  'MT Norte':          {comercial:'_MT_DYNAMIC_', portoFixo:null},
  'MT Médio Norte':    {comercial:'_MT_DYNAMIC_', portoFixo:null},
  'MT Nordeste':       {comercial:'_MT_DYNAMIC_', portoFixo:null},
  'MT Leste':          {comercial:'_MT_DYNAMIC_', portoFixo:null},
  'MT Sul':            {comercial:'_MT_DYNAMIC_', portoFixo:null},
  'MT Noroeste':       {comercial:'_MT_DYNAMIC_', portoFixo:null},
  // Goiás → Santos
  'GO Sul':            {comercial:'goias', portoFixo:'Santos'},
  'GO Sudoeste':       {comercial:'goias', portoFixo:'Santos'},
  'GO Leste':          {comercial:'goias', portoFixo:'Santos'},
  'GO Sudeste':        {comercial:'goias', portoFixo:'Santos'},
  'GO Oeste':          {comercial:'goias', portoFixo:'Santos'},
  'GO Norte':          {comercial:'goias', portoFixo:'Santos'},
  'GO Centro':         {comercial:'goias', portoFixo:'Santos'},
  // MS + PR → Paranaguá
  'MS Sul':            {comercial:'msPr', portoFixo:'Paranaguá'},
  'MS Norte':          {comercial:'msPr', portoFixo:'Paranaguá'},
  'PR Oeste':          {comercial:'msPr', portoFixo:'Paranaguá'},
  'PR Campos Gerais':  {comercial:'msPr', portoFixo:'Paranaguá'},
  'PR Sudoeste':       {comercial:'msPr', portoFixo:'Paranaguá'},
  'PR Norte':          {comercial:'msPr', portoFixo:'Paranaguá'},
  'PR Centro':         {comercial:'msPr', portoFixo:'Paranaguá'},
  'PR Sul':            {comercial:'msPr', portoFixo:'Paranaguá'},
  // Matopiba → Arco Norte (Itaqui/Barcarena dinâmico)
  'MA Norte':          {comercial:'matopiba', portoFixo:null},
  'MA Oeste':          {comercial:'matopiba', portoFixo:null},
  'MA Sul':            {comercial:'matopiba', portoFixo:null},
  'MA Centro':         {comercial:'matopiba', portoFixo:null},
  'PI Sul':            {comercial:'matopiba', portoFixo:null},
  'PI Norte':          {comercial:'matopiba', portoFixo:null},
  'TO Sul':            {comercial:'matopiba', portoFixo:null},
  'TO Norte':          {comercial:'matopiba', portoFixo:null},
  'PA Sul':            {comercial:'matopiba', portoFixo:null},
  'PA Norte':          {comercial:'matopiba', portoFixo:null},
  'BA Oeste':          {comercial:'matopiba', portoFixo:null},
  // RS → Rio Grande (placeholder)
  'RS Norte':          {comercial:'rs', portoFixo:'Rio Grande'},
  'RS Nordeste':       {comercial:'rs', portoFixo:'Rio Grande'},
  'RS Sul':            {comercial:'rs', portoFixo:'Rio Grande'},
};

/* Resolve o (corredor comercial, porto fixo) pra um negócio */
function getCorredorComercial(deal){
  const map = CORREDOR_COMERCIAL_MAP[deal.corredor];
  if(!map) return null;
  if(map.comercial === '_MT_DYNAMIC_'){
    const col = decideMTColuna(deal);
    const portoMap = {
      'oesteMT': 'Itaqui',
      'norteMT': 'Barcarena',
      '163':     'Santos',
      'sulMT':   'Santos'
    };
    return {comercial: col, portoFixo: portoMap[col]};
  }
  return map;
}

const CORREDORES_COMERCIAIS = [
  {key:'oesteMT',     label:'Oeste MT',      sub:'→ Itaqui',     i18nKey:'westMt',   i18nKeySub:'arrowItaqui'},
  {key:'norteMT',     label:'Norte MT',      sub:'→ Barcarena',  i18nKey:'northMt',  i18nKeySub:'arrowBarcarena'},
  {key:'163',         label:'BR-163',        sub:'→ Santos',     i18nKey:'br163',    i18nKeySub:'arrowSantos'},
  {key:'sulMT',       label:'Sul MT',        sub:'→ Santos',     i18nKey:'southMt',  i18nKeySub:'arrowSantos'},
  {key:'goias',       label:'Goiás',         sub:'→ Santos',     i18nKey:'goias',    i18nKeySub:'arrowSantos'},
  {key:'msPr',        label:'MS + PR',       sub:'→ Paranaguá',  i18nKey:'msPr',     i18nKeySub:'arrowParanagua'},
  {key:'matopiba',    label:'Matopiba',      sub:'→ Arco Norte', i18nKey:'matopiba', i18nKeySub:'arrowNorthArc'},
  {key:'rs',          label:'RS',            sub:'→ Rio Grande', i18nKey:'rs',       i18nKeySub:'arrowRioGrande'},
];

/* Classifica safra em 'velha' (Disp, 25/26, 2026) ou 'nova' (26/27, 2027) */
/* Extrai o mês/ano do EMBARQUE do negócio (a partir do campo retirada + vencCBOT) */
function getDataEmbarque(deal){
  const txt = String(deal.retirada||'').toLowerCase();
  const mesNomes = {janeiro:1,fevereiro:2,'marco':3,'março':3,abril:4,maio:5,junho:6,julho:7,agosto:8,setembro:9,outubro:10,novembro:11,dezembro:12,
                    jan:1,fev:2,mar:3,abr:4,mai:5,jun:6,jul:7,ago:8,set:9,out:10,nov:11,dez:12};
  let mes = null, ano = null;
  // Data dd/mm/aaaa → pega a última data
  const matches = [...txt.matchAll(/\b(\d{1,2})\/(\d{1,2})(?:\/(\d{2,4}))?\b/g)];
  if(matches.length){
    const last = matches[matches.length-1];
    mes = parseInt(last[2]);
    if(last[3]){
      ano = parseInt(last[3]);
      if(ano < 100) ano += 2000;
    }
  }
  if(!mes){
    for(const nome in mesNomes){
      if(txt.includes(nome)){ mes = mesNomes[nome]; break; }
    }
  }
  if(!mes){
    // Caso "Imediato/Disp" → embarque = mês do fechamento
    if(/\b(imediat|dispon|\bdisp\b)/.test(txt)){
      const dt = new Date(deal.data + 'T00:00:00');
      return new Date(dt.getFullYear(), dt.getMonth(), 15);
    }
    // Fallback: usa o vencimento CBOT
    const venc = deal.vencCBOT||brzContratoFrente('ZS');
    const letraMes = {F:1,H:3,K:5,N:7,Q:8,U:9,X:11};
    mes = letraMes[venc[0]] || 7;
  }
  if(!ano){
    const venc = deal.vencCBOT||brzContratoFrente('ZS');
    ano = 2000 + parseInt(venc.slice(1));
  }
  return new Date(ano, mes-1, 15);  // dia 15 do mês de embarque (meio do mês)
}

/* Classifica safra pela DATA DO EMBARQUE.
   Regra: Velha < 02/01/2027 ; Nova >= 02/01/2027.
   A cada virada de ano-safra (em janeiro/2 do próximo), o corte muda automaticamente:
   - 02/01/2027 → safra 25/26 vira velha; 26/27 vira nova
   - 02/01/2028 → safra 26/27 vira velha; 27/28 vira nova
   Por simplicidade, fixamos o corte na "próxima safra esperada" (corte = 02/01 do ano-safra atual + 1). */
function classificaSafraComercial(safraOrDeal){
  /* V4AV: velha/nova pela safra canônica (ano da safra > ano corrente = nova) */
  if(safraOrDeal && typeof safraOrDeal === 'object') return brzSafraClasse(safraOrDeal);
  var t=String(safraOrDeal||''), m=t.match(/(\d{2})\s*\/\s*(\d{2})/)||t.match(/20(\d{2})\s*\/\s*20(\d{2})/);
  if(m) return (2000+Number(m[2]))>brzAnoReferencia()?'nova':'velha';
  var y=t.match(/20(\d{2})/); return (y && 2000+Number(y[1])>brzAnoReferencia())?'nova':'velha';
}

/* Parser de data de pagamento a partir do campo 'retirada' do negócio.
   REGRA: Retirada é sempre o MÊS INTEIRO de embarque. Pagamento = primeiro dia útil do mês SEGUINTE.
   Exceção: "Imediato"/"Disponível"/"Disp" → pagamento ~5 dias após data de fechamento. */


/* Retorna o próximo dia útil (pula sábado/domingo) a partir de uma data */


/* VPL: trazer preço pago a valor presente conforme regra do prompt.
   - Safra velha: n = meses entre (mês de embarque) e (mês atual/spot)
   - Safra nova:  n = meses entre (mês de embarque) e (fevereiro do ano do embarque)
   - Casos: n < 0 → n = 0 (sem desconto); "Imediato/Disp" → n = 0
   precoVPL = preco / (1 + i)^(n/12)  onde i=15% a.a. */
function aplicaVPL(deal){
  const preco = n(deal.preco);
  if(!preco) return {preco, n:0};

  // "Imediato/Disp" → n=0
  const retTxt = String(deal.retirada||'').toLowerCase();
  if(/\b(imediat|dispon|\bdisp\b)/.test(retTxt)){
    return {preco, n:0};
  }

  const dtEmbarque = getDataEmbarque(deal);
  const safra = classificaSafraComercial(deal);
  let nMeses;

  if(safra === 'velha'){
    // n = (mês embarque) - (mês atual / hoje)
    const hoje = new Date();
    nMeses = (dtEmbarque.getFullYear()*12 + dtEmbarque.getMonth()) -
             (hoje.getFullYear()*12 + hoje.getMonth());
  } else {
    // n = (mês embarque) - fevereiro do ano do embarque
    nMeses = (dtEmbarque.getMonth() + 1) - 2;  // getMonth() é 0-indexed; fev = mês 2 (1-indexed)
  }

  if(nMeses < 0) nMeses = 0;  // embarque já passou

  const i = 0.15;
  const precoVPL = preco / Math.pow(1 + i, nMeses/12);
  return {preco:precoVPL, n:nMeses};
}

/* Acha o melhor porto pra um corredor comercial dado um negócio + porto fixo (se houver) */
function calcReplacementVPL(deal, portoFixo){
  // 1) Aplica VPL no preço conforme safra/regra do prompt
  const {preco:precoVPL, n:nMeses} = aplicaVPL(deal);

  // 2) Recalcula replacement com preço descontado
  const dealVPL = {...deal, preco:precoVPL};
  const cmp = brzMapSafePortComparison(dealVPL);

  // 3) Escolhe o porto: se portoFixo, usa ele; senão, melhor porto da comparação
  let porto;
  if(portoFixo){
    const r = cmp.results.find(r=>r.porto===portoFixo);
    if(!r?.best) return null;
    porto = r;
  } else {
    if(!cmp.bestPort) return null;
    porto = cmp.results.find(r=>r.porto===cmp.bestPort);
  }

  return {
    basis: porto.best.replacementBasis,
    fob: porto.best.replacementFOB,
    porto: porto.porto,
    modal: porto.best.modal,
    nMeses,
    precoOriginal: n(deal.preco),
    precoVPL
  };
}

function renderMapaVplTabela(dealsFiltro){
  const box = document.getElementById('mapaVplTabela');
  if(!box) return;
  if(dealsFiltro.length === 0){
    box.innerHTML = '';
    return;
  }

  // 1) Para cada negócio, calcula replacement VPL no corredor comercial dele
  // Regra de volume: se houver volume real em alguma linha do filtro, pondera por volume.
  // Se todos os volumes estiverem zerados, usa média simples por negócio para não zerar a tabela VPL.
  // Correção importante: a base histórica antiga tem volume = 0 em muitos negócios.
  // Antes, quando qualquer negócio novo tinha volume informado, todos os dias antigos
  // com volume zerado eram ignorados e a tabela VPL ficava vazia.
  // Agora a ponderação é por dia: dias com volume real usam volume; dias sem volume usam média simples por negócio.
  const volumeRealPorDia = {};
  dealsFiltro.forEach(d=>{ if(n(d.volume) > 0) volumeRealPorDia[d.data] = true; });
  const hasAnyRealVolume = Object.keys(volumeRealPorDia).length > 0;
  const weightOf = (deal) => volumeRealPorDia[deal.data] ? Math.max(n(deal.volume), 0) : 1;
  const grid = {};  // dia → {corrComercial → {velha:{basisW,vol,count}, nova:{basisW,vol,count}}}
  const allDias = new Set();
  const fobPgaPorDia = {};  // dia → {fobW, cbotW, vol, count}

  dealsFiltro.forEach(deal=>{
    const map = getCorredorComercial(deal);
    if(!map) return;  // corredor não está mapeado
    const safra = classificaSafraComercial(deal);
    const rep = calcReplacementVPL(deal, map.portoFixo);
    if(!rep) return;

    const dia = deal.data;
    allDias.add(dia);
    if(!grid[dia]) grid[dia] = {};
    if(!grid[dia][map.comercial]) grid[dia][map.comercial] = {velha:{basisW:0,vol:0,fobW:0,count:0}, nova:{basisW:0,vol:0,fobW:0,count:0}};
    const v = weightOf(deal);
    if(v <= 0) return;
    grid[dia][map.comercial][safra].basisW += rep.basis * v;
    grid[dia][map.comercial][safra].fobW += rep.fob * v;
    grid[dia][map.comercial][safra].vol += v;
    grid[dia][map.comercial][safra].count += 1;

    // Prêmio FOB PGA: forçar cálculo via Paranaguá pra todos os negócios
    const {preco:precoVPL} = aplicaVPL(deal);
    const cmp = brzMapSafePortComparison({...deal, preco:precoVPL});
    const pgua = cmp.results.find(r=>r.porto==='Paranaguá')?.best;
    if(pgua){
      if(!fobPgaPorDia[dia]) fobPgaPorDia[dia] = {fobW:0, cbotW:0, vol:0, count:0};
      fobPgaPorDia[dia].fobW += pgua.replacementFOB * v;
      fobPgaPorDia[dia].cbotW += n(deal.cbot) * v;
      fobPgaPorDia[dia].vol += v;
      fobPgaPorDia[dia].count += 1;
    }
  });

  if(allDias.size === 0){
    box.innerHTML = `<div style="background:transparent;border:0;padding:16px;font-size:11.5px;color:var(--muted);text-align:center">${t('vplNoData')}</div>`;
    return;
  }

  // 2) Ordena dias (mais recente primeiro)
  const dias = [...allDias].sort().reverse();

  // 3) Monta cabeçalho com sub-colunas Velha/Nova
  let header1 = `<th rowspan="2" style="position:sticky;left:0;background:var(--navy);z-index:2;text-align:left">${t('day')}</th>`;
  let header2 = '';
  CORREDORES_COMERCIAIS.forEach(c=>{
    const corrLabel = t(c.i18nKey||'') !== (c.i18nKey||'') ? t(c.i18nKey) : c.label;
    const corrSub = t(c.i18nKeySub||'') !== (c.i18nKeySub||'') ? t(c.i18nKeySub) : c.sub;
    header1 += `<th colspan="2" style="border-left:1px solid rgba(255,255,255,.15);text-align:center">${corrLabel}<div style="font-size:9.5px;color:rgba(255,255,255,.65);font-weight:500">${corrSub}</div></th>`;
    header2 += `<th style="border-left:1px solid rgba(255,255,255,.15);font-size:9.5px;color:rgba(255,255,255,.85)">${t('oldCrop')}</th><th style="font-size:9.5px;color:rgba(255,255,255,.85)">${t('newCrop')}</th>`;
  });
  header1 += `<th rowspan="2" style="border-left:1px solid rgba(255,255,255,.15);text-align:center">${t('pgaPremiumFobCbot')}<div style="font-size:9.5px;color:rgba(255,255,255,.65);font-weight:500">${t('fobMinusCbot')}</div></th>`;

  // 4) Linhas
  const rows = dias.map(dia=>{
    let row = `<td style="position:sticky;left:0;background:var(--card);z-index:1;font-weight:700">${fmtDate(dia)}</td>`;
    CORREDORES_COMERCIAIS.forEach(c=>{
      const cell = grid[dia]?.[c.key];
      ['velha','nova'].forEach((safra,i)=>{
        const d = cell?.[safra];
        if(!d || d.vol === 0){
          row += `<td style="${i===0?'border-left:1px solid var(--line);':''}color:#D1D5DB;text-align:center">·</td>`;
          return;
        }
        const basis = d.basisW / d.vol;
        const tagClass = basis<=0?'green':basis<=50?'amber':'red';
        const cellBase = volumeRealPorDia[dia] ? `${tons(d.vol)} t` : `${d.count || d.vol.toFixed(0)} negócios`;
        row += `<td style="${i===0?'border-left:1px solid var(--line);':''}text-align:center;cursor:pointer;font-variant-numeric:tabular-nums" onclick="openVplMiniChart('${dia}','${c.key}','${safra}')" title="${t('clickToSeeTrend')} · ${cellBase}">
          <span class="tag ${tagClass}" style="font-size:10.5px;padding:2px 6px">${basis>=0?'+':''}${fmtBasis(basis)}</span>
        </td>`;
      });
    });
    // Prêmio FOB PGA do dia
    const fpga = fobPgaPorDia[dia];
    if(fpga && fpga.vol > 0){
      const fobMed = fpga.fobW/fpga.vol;
      const cbotMed = fpga.cbotW/fpga.vol;
      const premio = fobMed - cbotMed;
      const tagClass = premio<=0?'green':premio<=50?'amber':'red';
      row += `<td style="border-left:1px solid var(--line);text-align:center"><span class="tag ${tagClass}" style="font-size:10.5px;padding:2px 6px">${premio>=0?'+':''}${money(premio)}</span></td>`;
    } else {
      row += `<td style="border-left:1px solid var(--line);color:#D1D5DB;text-align:center">·</td>`;
    }
    return `<tr>${row}</tr>`;
  }).join('');

  // 5) Vencimentos ativos vs antigos
  // Ativo = venc CBOT cujo mês ainda não passou (mês de hoje ou futuro)
  // Antigo = venc CBOT cujo mês já passou (vira botão de sazonalidade)
  const dtHoje = new Date();
  const anoHoje = dtHoje.getFullYear();
  const mesHoje = dtHoje.getMonth() + 1;
  const vencsNaBase = [...new Set(dealsFiltro.map(d=>d.vencCBOT))].sort();
  const produtoAtivo = getActiveProduto();
  const mesLabel = {F:'Jan', H:'Mar', K:'Mai', N:'Jul', Q:'Ago', U:'Set', X:'Nov', Z:'Dez'};
  const letraMes = {F:1,G:2,H:3,J:4,K:5,M:6,N:7,Q:8,U:9,V:10,X:11,Z:12}; /* V4AW: Z (milho) incluído */

  function isVencAtivo(v){
    const letra = v.charAt(0);
    const ano = 2000 + parseInt(v.slice(1));
    const mes = letraMes[letra] || 7;
    // Ativo se está no mesmo mês ou no futuro
    if(ano > anoHoje) return true;
    if(ano < anoHoje) return false;
    return mes >= mesHoje;
  }

  const vencsAtivos = vencsNaBase.filter(isVencAtivo);
  const vencsAntigos = vencsNaBase.filter(v => !isVencAtivo(v));

  box.innerHTML = `
    <div style="background:var(--card);border:0;border-bottom:1px solid var(--line);padding:20px 28px">
      <div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:11px;gap:10px;flex-wrap:wrap">
        <div style="font-size:13px;font-weight:700;color:var(--g900)">${t('vplTitle')}</div>
        <div style="font-size:11px;color:var(--muted)">${dias.length} ${dias.length>1?t('daysPlur'):t('daysSing')} · ${dealsFiltro.length} ${t('dealsLower')} · ${hasAnyRealVolume ? 'volume quando informado / média simples nos dias sem volume' : 'média simples por negócio'}</div>
      </div>
      <div style="overflow-x:auto;max-width:100%;border:1px solid var(--g200);border-radius:4px">
        <table class="table" style="font-size:11px;min-width:100%">
          <thead>
            <tr>${header1}</tr>
            <tr>${header2}</tr>
          </thead>
          <tbody>${rows}</tbody>
        </table>
      </div>

      ${vencsAtivos.length ? `
      <div style="margin-top:11px;display:flex;gap:6px;align-items:center;flex-wrap:wrap">
        <span style="font-size:11.5px;color:var(--g700);font-weight:600">${t('activeShipments')}</span>
        ${vencsAtivos.map(v=>{
          const ship = vencToShipMonths(v);
          return `<button onclick="openVplSazonalidade('${v}')" title="${t('viewShipmentTrend')} ${ship}" style="display:inline-flex;align-items:center;gap:6px;background:var(--green);color:#fff;border:0;padding:5px 10px;font-size:11px;font-weight:600;border-radius:4px;cursor:pointer">
            <span>${v}</span>
            <span style="opacity:.85;font-weight:500;font-size:10.5px">embarque ${ship}</span>
          </button>`;
        }).join('')}
      </div>
      ` : ''}

      ${vencsAntigos.length ? `
      <div style="margin-top:8px;display:flex;gap:6px;align-items:center;flex-wrap:wrap">
        <span style="font-size:11.5px;color:var(--g500);font-weight:500">${t('pastShipments')}</span>
        ${vencsAntigos.map(v=>{
          const ship = vencToShipMonths(v);
          return `<button onclick="openVplSazonalidade('${v}')" title="${t('shipmentSeasonality')} ${ship}" style="display:inline-flex;align-items:center;gap:6px;background:var(--g200);color:var(--g700);border:0;padding:5px 10px;font-size:11px;font-weight:500;border-radius:4px;cursor:pointer">
            <span>${v}</span>
            <span style="opacity:.75;font-weight:400;font-size:10.5px">embarque ${ship}</span>
          </button>`;
        }).join('')}
        <span style="color:var(--g500);font-size:10px;font-style:italic">${t('overlayPriorYears')}</span>
      </div>
      ` : ''}

      ${!vencsAtivos.length && !vencsAntigos.length ? `<div style="margin-top:10px;font-size:10.5px;color:var(--muted);font-style:italic">${t('noMaturities')}</div>` : ''}
    </div>`;
}

/* Popover mini-chart: tendência do replacement daquela célula nos últimos N dias */
function openVplMiniChart(dia, corrKey, safra){
  // Coleta dados históricos: para todos os dias da base, calcula o basis daquele corredor+safra
  const corrConfig = CORREDORES_COMERCIAIS.find(c=>c.key===corrKey);
  const corrLabel = corrConfig ? (t(corrConfig.i18nKey) !== corrConfig.i18nKey ? t(corrConfig.i18nKey) : corrConfig.label) : corrKey;
  const safraLabel = safra==='velha' ? t('oldCropFull') : t('newCropFull');

  // Pega TODOS os negócios da base que se encaixam em (corredor + safra), independente do dia
  const dealsRelevantes = getActiveDeals().filter(d=>{
    const map = getCorredorComercial(d);
    if(!map || map.comercial !== corrKey) return false;
    if(classificaSafraComercial(d) !== safra) return false;
    return true;
  });

  // Agrega por dia
  const volumeRealPorDia = {};
  dealsRelevantes.forEach(d=>{ if(n(d.volume) > 0) volumeRealPorDia[d.data] = true; });
  const weightOf = (deal) => volumeRealPorDia[deal.data] ? Math.max(n(deal.volume), 0) : 1;
  const porDia = {};
  dealsRelevantes.forEach(d=>{
    const map = getCorredorComercial(d);
    const rep = calcReplacementVPL(d, map.portoFixo);
    if(!rep) return;
    const w = weightOf(d);
    if(w <= 0) return;
    if(!porDia[d.data]) porDia[d.data] = {basisW:0, vol:0, count:0};
    porDia[d.data].basisW += rep.basis * w;
    porDia[d.data].vol += w;
    porDia[d.data].count++;
  });

  const series = Object.keys(porDia).sort().filter(dt => porDia[dt].vol > 0).map(dt=>({
    data: dt,
    basis: porDia[dt].basisW / porDia[dt].vol,
    vol: porDia[dt].vol,
    count: porDia[dt].count
  }));

  if(series.length === 0){
    alert(`${t('noHistoryFor')} ${corrLabel} · ${safraLabel}`);
    return;
  }

  // SVG sparkline
  const W = 560, H = 200, PADL = 50, PADR = 20, PADT = 28, PADB = 36;
  const minB = Math.min(...series.map(s=>s.basis));
  const maxB = Math.max(...series.map(s=>s.basis));
  const rangeB = maxB === minB ? 1 : (maxB - minB);

  const xScale = i => PADL + (i*(W-PADL-PADR)/Math.max(series.length-1,1));
  const yScale = b => H - PADB - ((b-minB)/rangeB) * (H-PADT-PADB);

  let svg = `<svg viewBox="0 0 ${W} ${H}" style="width:100%;height:auto;background:var(--card);border-radius:8px">`;
  // Eixos
  for(let i=0;i<=3;i++){
    const y = PADT + i*(H-PADT-PADB)/3;
    const v = maxB - i*rangeB/3;
    svg += `<line x1="${PADL}" y1="${y}" x2="${W-PADR}" y2="${y}" stroke="var(--line)" stroke-width="1"/>`;
    svg += `<text x="${PADL-6}" y="${y+4}" text-anchor="end" font-size="10" fill="var(--muted)">${v.toFixed(0)}¢</text>`;
  }
  // Linha
  if(series.length >= 2){
    const path = series.map((s,i)=>(i===0?'M':'L')+xScale(i)+','+yScale(s.basis)).join(' ');
    svg += `<path d="${path}" fill="none" stroke="var(--g900)" stroke-width="2.5" stroke-linejoin="round"/>`;
  }
  // Pontos
  series.forEach((s,i)=>{
    const x = xScale(i), y = yScale(s.basis);
    const baseTxt = volumeRealPorDia[s.data] ? `${tons(s.vol)} t` : `${s.count} ${t('dealsLower')}`;
    svg += `<circle cx="${x}" cy="${y}" r="4" fill="${s.data===dia?'var(--green)':'var(--g900)'}" stroke="#fff" stroke-width="2"><title>${fmtDate(s.data)} · ${t('repBasisShort')} ${s.basis>=0?'+':''}${fmtBasis(s.basis)} ¢ · ${baseTxt}</title></circle>`;
    if(s.data === dia){
      svg += `<text x="${x}" y="${y-9}" text-anchor="middle" font-size="10" fill="var(--green)" font-weight="700">${s.basis>=0?'+':''}${fmtBasis(s.basis)}</text>`;
    }
  });
  // Eixo X
  series.forEach((s,i)=>{
    if(series.length>8 && i%Math.ceil(series.length/8)!==0 && i!==series.length-1) return;
    const dt = new Date(s.data+'T00:00:00');
    const lab = `${String(dt.getDate()).padStart(2,'0')}/${String(dt.getMonth()+1).padStart(2,'0')}`;
    svg += `<text x="${xScale(i)}" y="${H-PADB+18}" text-anchor="middle" font-size="10" fill="var(--muted)">${lab}</text>`;
  });
  svg += `<text x="${PADL}" y="18" font-size="11" font-weight="700" fill="var(--g900)">${corrLabel} · ${safraLabel} — ${t('repBasisOverTime')}</text>`;
  svg += '</svg>';

  // Modal simples
  const existing = document.getElementById('vplMiniChartModal');
  if(existing) existing.remove();
  const modal = document.createElement('div');
  modal.id = 'vplMiniChartModal';
  modal.style.cssText = 'position:fixed;inset:0;background:rgba(15,30,28,.55);z-index:999;display:flex;align-items:center;justify-content:center;padding:20px;cursor:pointer';
  modal.onclick = (e)=>{ if(e.target===modal) modal.remove(); };
  modal.innerHTML = `
    <div style="background:var(--card);border-radius:6px;padding:24px;max-width:640px;width:100%;cursor:default" onclick="event.stopPropagation()">
      <div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:14px">
        <div>
          <div style="font-size:13px;font-weight:700;color:var(--g900)">${t('trend')}</div>
          <div style="font-size:14px;color:var(--g900);font-weight:700;margin-top:3px">${corrLabel} · ${safraLabel}</div>
        </div>
        <button class="btn small" onclick="document.getElementById('vplMiniChartModal').remove()">${t('closeBtn')}</button>
      </div>
      ${svg}
      <div style="font-size:10.5px;color:var(--muted);margin-top:8px;text-align:center">${t('highlightedPoint')} ${fmtDate(dia)} · ${series.length} ${series.length>1?t('daysPlur'):t('daysSing')} ${t('withData')}</div>
    </div>`;
  document.body.appendChild(modal);
}

function openVplSazonalidade(venc){
  alert(`${t('shipmentSeasonality')} ${venc} — ${t('seasonalityWarning')}`);
}


/* ═══════════════════════════════════════════════════════
   CARD-NARRATIVA — análise do período em 5 drivers
   Resposta à pergunta: "O que aconteceu neste período/dia, e por quê?"
═══════════════════════════════════════════════════════ */
function renderMapaNarrativa(dealsAtu, aggAtu){
  const box = document.getElementById('mapaNarrativa');
  if(!box) return;

  // Sem período / sem snapshot → mostra call-to-action sem inventar análise
  if(!mapaDataUnica && !(mapaDataInicio && mapaDataFim)){
    box.innerHTML = `
      <div style="background:transparent;border:0;border-left:3px solid var(--g900);padding:14px 18px;text-align:left">
        <div style="font-size:13px;font-weight:700;color:var(--g900);margin-bottom:6px">${t('marketAnalysis')}</div>
        <div style="font-size:13px;color:var(--g900);line-height:1.5">
          ${t('selectPeriodCta')}
        </div>
      </div>`;
    return;
  }

  // Sem negócios no recorte
  if(dealsAtu.length === 0){
    box.innerHTML = `
      <div style="background:transparent;border:0;border-left:3px solid var(--amber);padding:14px 18px">
        <div style="font-size:12px;color:#92400e">⚠ ${t('noDealsInSelection')}</div>
      </div>`;
    return;
  }

  // Modo 1: Snapshot do dia — descreve o estado naquele dia
  if(mapaDataUnica){
    renderMapaNarrativaSnapshot(dealsAtu, aggAtu, box);
    return;
  }

  // Modo 2: Período — decompõe variação em drivers
  renderMapaNarrativaPeriodo(dealsAtu, aggAtu, box);
}

/* Narrativa do snapshot de um dia */
function renderMapaNarrativaSnapshot(dealsAtu, aggAtu, box){
  // Médias ponderadas do dia
  // Importante: cbot/câmbio usam TODOS os deals (w);
  //             preço/frete/fobbins/basis usam só deals COM best port (wBest);
  //             FOB Paranaguá usa só deals que tiveram Paranaguá calculável (fobPgaVol)
  let cbotW=0, camW=0, prW=0, frW=0, fbW=0, basisW=0, fobPgaW=0, fobPgaVol=0;
  let w=0, wBest=0;
  let countComBest = 0, countSemBest = 0;
  dealsAtu.forEach(d=>{
    const cmp = brzMapSafePortComparison(d);
    const best = cmp.results.find(r=>r.porto===cmp.bestPort)?.best;
    const v = n(d.volume);
    if(best){
      basisW += best.replacementBasis*v;
      prW += best._priceCbu*v;
      frW += best._freightCbu*v;
      fbW += best._fobbinsCbu*v;
      wBest += v;
      countComBest++;
    } else {
      countSemBest++;
    }
    const pgua = cmp.results.find(r=>r.porto==='Paranaguá')?.best;
    if(pgua){ fobPgaW += pgua.replacementFOB*v; fobPgaVol += v; }
    cbotW += n(d.cbot)*v;
    camW += n(d.cambio)*v;
    w += v;
  });
  const basisMed = wBest ? basisW/wBest : null;
  const prMed = wBest ? prW/wBest : null;
  const frMed = wBest ? frW/wBest : null;
  const fbMed = wBest ? fbW/wBest : null;
  const cbotMed = w ? cbotW/w : 0;
  const camMed = w ? camW/w : 0;
  const fobPgaMed = fobPgaVol ? fobPgaW/fobPgaVol : null;
  // CFR China ponderado por deal (cada deal usa ocean freight da sua janela)
  let cfrW = 0, cfrV = 0, seaW = 0;
  dealsAtu.forEach(d=>{
    const cmp = brzMapSafePortComparison(d);
    const pgua = cmp.results.find(r=>r.porto==='Paranaguá')?.best;
    if(pgua){
      const v = n(d.volume);
      const seaUsd = brzOceanUsdT(d, null);
      if(seaUsd!=null){
        const cfrCbu = pgua.replacementFOB + (seaUsd * 0.06 / 2.2046 * 100);
        cfrW += cfrCbu * v;
        seaW += seaUsd * v;
        cfrV += v;
      }
    }
  });
  const cfrChina = cfrV ? cfrW/cfrV : null;
  const seaFreight = cfrV ? seaW/cfrV : 45;

  // Corredores ativos
  const corrs = Object.entries(aggAtu).sort((a,b)=>b[1].volSum - a[1].volSum);
  const totalVol = corrs.reduce((acc,[,a])=>acc+a.volSum, 0);

  // Destaques: melhor e pior basis do dia (só corredores com basis calculável)
  const ranked = corrs.map(([c,a])=>({c, basis:a.basisVolSum/(a.calcWeightSum || a.volSum || 1), vol:a.volSum, count:a.count}));
  ranked.sort((a,b)=>a.basis - b.basis);
  const maisCompetitivo = ranked[0];
  const maisCaro = ranked[ranked.length-1];

  // Aviso sobre negócios excluídos da análise (sem frete e sem coordenada pra estimativa)
  const avisoExcluidos = countSemBest > 0
    ? `<div style="font-size:10.5px;color:#92400e;background:var(--amberbg);border:1px solid #fcd9b6;border-radius:8px;padding:8px 10px;margin-bottom:12px"><b>⚠ ${countSemBest} negócio${countSemBest>1?'s':''}</b> sem frete cadastrado nem estimativa TKU disponível — não entraram no FOB/Basis/Preço-interior médios. CBOT e câmbio incluem todos.</div>`
    : '';

  // Helper de render de valor (null-safe)
  const v = (n, sufix='') => (n===null||n===undefined||isNaN(n)) ? '—' : `${money(n)}${sufix}`;

  // Quantos negócios escoaram efetivamente por Paranaguá (no melhor porto)
  const negViaParanagua = dealsAtu.filter(d=>{
    const cmp = brzMapSafePortComparison(d);
    return cmp.bestPort === 'Paranaguá';
  }).length;
  const negComFretePga = dealsAtu.filter(d=>{
    const cmp = brzMapSafePortComparison(d);
    return cmp.results.find(r=>r.porto==='Paranaguá')?.best;
  }).length;

  box.innerHTML = `
    <div style="background:var(--card);border:0;border-bottom:1px solid var(--line);padding:20px 28px">
      <div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:12px">
        <div>
          <div style="font-size:13px;font-weight:700;color:var(--g900)">${t('snapshotOfDayPrefix')} ${mapaDataUnica}</div>
          <div style="font-size:13px;color:var(--g900);margin-top:3px">${t('marketStateDate')} ${mapaVenc!=='todos'?t('forWindow')+' <b>'+mapaVenc+'</b>':''}</div>
        </div>
        <div style="font-size:11px;color:var(--muted);text-align:right">
          <b>${dealsAtu.length}</b> ${t('dealsLower')} · ${tons(totalVol)} t · ${corrs.length} ${t('corridorsLower')}<br>
          ${countComBest}/${dealsAtu.length} ${t('withComputableFob')}
        </div>
      </div>

      ${avisoExcluidos}

      <div style="display:grid;grid-template-columns:repeat(6,1fr);gap:10px;margin-bottom:14px">
        <div class="metric"><label>${t('avgCbot')}</label><strong>${v(cbotMed,' ¢/bu')}</strong><div style="font-size:9.5px;color:var(--muted);margin-top:2px">${dealsAtu.length} ${t('dealsLower')}</div></div>
        <div class="metric"><label>${t('avgFx')}</label><strong>R$ ${v(camMed)}</strong><div style="font-size:9.5px;color:var(--muted);margin-top:2px">${dealsAtu.length} ${t('dealsLower')}</div></div>
        <div class="metric"><label>${t('interiorPrice')}</label><strong>${v(prMed,' ¢/bu')}</strong><div style="font-size:9.5px;color:var(--muted);margin-top:2px">${countComBest} ${t('dealsLower')}</div></div>
        <div class="metric"><label>${t('logisticsFreight')}</label><strong>${v(frMed,' ¢/bu')}</strong><div style="font-size:9.5px;color:var(--muted);margin-top:2px">${countComBest} ${t('dealsLower')}</div></div>
        <div class="metric"><label>${t('basisParanagua')}</label><strong>${fobPgaMed!==null?(fobPgaMed-cbotMed>=0?'+':'')+money(fobPgaMed-cbotMed)+' ¢':'—'}</strong><div style="font-size:9.5px;color:var(--muted);margin-top:2px">${negComFretePga}/${dealsAtu.length} ${t('withPgaRoute')}</div></div>
        <div class="metric"><label>${t('basisCfrChina')} (+${seaFreight} USD/t)</label><strong>${cfrChina!==null?(cfrChina-cbotMed>=0?'+':'')+money(cfrChina-cbotMed)+' ¢':'—'}</strong><div style="font-size:9.5px;color:var(--muted);margin-top:2px">${t('viaParanagua')}</div></div>
      </div>

      ${basisMed !== null ? `
      <div style="font-size:12.5px;line-height:1.6;color:var(--g900);border-top:1px solid var(--line);padding-top:11px">
        <b>${t('todaysReading')}</b> ${t('avgRepBasis')} (${countComBest} ${t('dealsLower')} ${t('withComputableFob')}) ${t('atPrefix')} <b style="color:${basisMed<=0?'var(--green)':basisMed<=50?'var(--amber)':'var(--red)'}">${basisMed>=0?'+':''}${fmtBasis(basisMed)} ¢/bu</b>.
        ${t('mostCompetitive')} <b>${maisCompetitivo.c}</b> (${maisCompetitivo.basis>=0?'+':''}${fmtBasis(maisCompetitivo.basis)} ¢, ${tons(maisCompetitivo.vol)} t)
        ${maisCaro.c !== maisCompetitivo.c ? ` ${t('mostExpensive')} <b>${maisCaro.c}</b> (${maisCaro.basis>=0?'+':''}${fmtBasis(maisCaro.basis)} ¢)` : ''}.
        ${t('avgFobComposition')} ${t('interiorPriceLower')} <b>${money(prMed)} ¢</b> + ${t('freightLower')} <b>${money(frMed)} ¢</b> + ${t('fobbinsLower')} <b>${money(fbMed)} ¢</b> = FOB <b>${money(prMed+frMed+fbMed)} ¢</b> vs CBOT <b>${money(cbotMed)} ¢</b>.
      </div>
      ` : `
      <div style="font-size:12px;color:var(--muted);padding:11px;background:var(--soft);border-radius:8px;border-top:1px solid var(--line)">
        ⚠ ${t('noFreightWarning')}
      </div>
      `}
    </div>`;
}

/* Narrativa do período: decomposição em 5 drivers vs período anterior */
function renderMapaNarrativaPeriodo(dealsAtu, aggAtu, box){
  // Período anterior do mesmo tamanho
  const dias = (new Date(mapaDataFim) - new Date(mapaDataInicio)) / 86400000;
  const iniAnt = new Date(new Date(mapaDataInicio).getTime() - (dias+1)*86400000).toISOString().slice(0,10);
  const fimAnt = new Date(new Date(mapaDataInicio).getTime() - 86400000).toISOString().slice(0,10);
  const dealsAnt = getActiveDeals().filter(d => d.data >= iniAnt && d.data <= fimAnt && (mapaVenc==='todos' || d.vencCBOT===mapaVenc));

  // Médias atual
  let cbotW=0, camW=0, prW=0, frW=0, fbW=0, basisW=0, fobPgaW=0, fobPgaVol=0, wAtu=0;
  dealsAtu.forEach(d=>{
    const cmp = brzMapSafePortComparison(d);
    const best = cmp.results.find(r=>r.porto===cmp.bestPort)?.best;
    const v = n(d.volume);
    if(best){
      basisW += best.replacementBasis*v;
      prW += best._priceCbu*v;
      frW += best._freightCbu*v;
      fbW += best._fobbinsCbu*v;
    }
    const pgua = cmp.results.find(r=>r.porto==='Paranaguá')?.best;
    if(pgua){ fobPgaW += pgua.replacementFOB*v; fobPgaVol += v; }
    cbotW += n(d.cbot)*v;
    camW += n(d.cambio)*v;
    wAtu += v;
  });
  const basisAtu = basisW/wAtu, prAtu = prW/wAtu, frAtu = frW/wAtu;
  const cbotAtu = cbotW/wAtu, camAtu = camW/wAtu;
  const fobPgaAtu = fobPgaVol ? fobPgaW/fobPgaVol : null;
  // CFR Atu ponderado por deal (cada um usa ocean freight da janela)
  let cfrAtuW = 0, cfrAtuV = 0, seaAtuW = 0;
  dealsAtu.forEach(d=>{
    const cmp = brzMapSafePortComparison(d);
    const pgua = cmp.results.find(r=>r.porto==='Paranaguá')?.best;
    if(pgua){
      const v = n(d.volume);
      const seaUsd = brzOceanUsdT(d, null);
      if(seaUsd!=null){
        cfrAtuW += (pgua.replacementFOB + seaUsd*0.06/2.2046*100) * v;
        seaAtuW += seaUsd * v;
        cfrAtuV += v;
      }
    }
  });
  const cfrAtu = cfrAtuV ? cfrAtuW/cfrAtuV : null;
  const seaFreight = cfrAtuV ? seaAtuW/cfrAtuV : 45;  // média ponderada pra display

  // Médias anterior (se houver dado)
  let dCbot=null, dCam=null, dPr=null, dFr=null, dBasis=null, dFobPga=null, dCfr=null;
  let basisAnt=null, fobPgaAnt=null, cfrAnt=null;
  if(dealsAnt.length){
    let cbW=0, cmW=0, prAW=0, frAW=0, bsW=0, fpW=0, fpV=0, wA=0;
    dealsAnt.forEach(d=>{
      const cmp = brzMapSafePortComparison(d);
      const best = cmp.results.find(r=>r.porto===cmp.bestPort)?.best;
      const v = n(d.volume);
      if(best){
        bsW += best.replacementBasis*v;
        prAW += best._priceCbu*v;
        frAW += best._freightCbu*v;
      }
      const pgua = cmp.results.find(r=>r.porto==='Paranaguá')?.best;
      if(pgua){ fpW += pgua.replacementFOB*v; fpV += v; }
      cbW += n(d.cbot)*v;
      cmW += n(d.cambio)*v;
      wA += v;
    });
    const cbotAnt = cbW/wA, camAnt = cmW/wA, prAnt = prAW/wA, frAnt = frAW/wA;
    basisAnt = bsW/wA;
    fobPgaAnt = fpV ? fpW/fpV : null;
    // CFR Ant ponderado por deal (igual ao atual)
    let cfrAntW = 0, cfrAntV = 0;
    dealsAnt.forEach(d=>{
      const cmp = brzMapSafePortComparison(d);
      const pgua = cmp.results.find(r=>r.porto==='Paranaguá')?.best;
      if(pgua){
        const v = n(d.volume);
        const seaUsd = brzOceanUsdT(d, null);
        if(seaUsd!=null){
          cfrAntW += (pgua.replacementFOB + seaUsd*0.06/2.2046*100) * v;
          cfrAntV += v;
        }
      }
    });
    cfrAnt = cfrAntV ? cfrAntW/cfrAntV : null;

    dCbot = cbotAtu - cbotAnt;
    dCam = camAtu - camAnt;
    dPr = prAtu - prAnt;
    dFr = frAtu - frAnt;
    dBasis = basisAtu - basisAnt;
    if(fobPgaAtu !== null && fobPgaAnt !== null) dFobPga = fobPgaAtu - fobPgaAnt;
    if(cfrAtu !== null && cfrAnt !== null) dCfr = cfrAtu - cfrAnt;
  }

  // Corredor com maior variação no período (precisa de cálculo por corredor)
  let maisAlta = null, maisQueda = null;
  Object.entries(aggAtu).forEach(([corr, a])=>{
    const basisAtuC = a.basisVolSum/(a.calcWeightSum || a.volSum || 1);
    const dealsAntC = dealsAnt.filter(d=>d.corredor===corr);
    if(!dealsAntC.length) return;
    let bs=0, wA=0;
    dealsAntC.forEach(d=>{
      const cmp = brzMapSafePortComparison(d);
      const best = cmp.results.find(r=>r.porto===cmp.bestPort)?.best;
      const v = n(d.volume);
      if(best) bs += best.replacementBasis*v;
      wA += v;
    });
    const basisAntC = bs/wA;
    const delta = basisAtuC - basisAntC;
    if(!maisAlta || delta > maisAlta.delta) maisAlta = {corr, delta, basisAtu:basisAtuC, basisAnt:basisAntC};
    if(!maisQueda || delta < maisQueda.delta) maisQueda = {corr, delta, basisAtu:basisAtuC, basisAnt:basisAntC};
  });

  // Função pra mostrar variação como tag
  const tag = (val, unidade='¢', invertCor=false) => {
    if(val === null || val === undefined) return '<span style="color:var(--muted)">—</span>';
    const positivo = val >= 0;
    const cor = invertCor ? (positivo ? 'var(--red)' : 'var(--green)') : (positivo ? 'var(--green)' : 'var(--red)');
    const seta = positivo ? '▲' : '▼';
    return `<span style="color:${cor};font-weight:700">${seta} ${positivo?'+':''}${money(val)} ${unidade}</span>`;
  };

  // Narrativa do driver dominante
  let driverPrincipal = '—';
  if(dBasis !== null){
    const candidatos = [
      {n:t('interior'), val:dPr, peso:Math.abs(dPr)},
      {n:t('freight'), val:dFr, peso:Math.abs(dFr)},
      {n:'CBOT', val:dCbot, peso:Math.abs(dCbot)*0.7},
      {n:t('fxLabel'), val:dCam, peso:Math.abs(dCam)*100}
    ];
    candidatos.sort((a,b)=>b.peso - a.peso);
    driverPrincipal = candidatos[0].n;
  }

  // Frase principal
  let fraseTopo;
  if(dBasis === null){
    fraseTopo = `${t('periodFrom')} ${mapaDataInicio} ${t('to')} ${mapaDataFim} ${t('noComparison')} (${iniAnt} ${t('to')} ${fimAnt}) — ${t('descriptiveOnly')}.`;
  } else {
    const direcao = dBasis >= 0 ? t('rose') : t('fell');
    const direcaoSentido = dBasis >= 0 ? t('worsened') : t('improved');
    fraseTopo = `${t('between')} <b>${mapaDataInicio}</b> ${t('and')} <b>${mapaDataFim}</b>, ${t('avgRepBasisVerb')} <b style="color:${dBasis<=0?'var(--green)':'var(--red)'}">${direcao} ${money(Math.abs(dBasis))} ¢/bu</b> ${direcaoSentido}. ${t('mainDriver')}: <b>${driverPrincipal}</b>.`;
  }

  // Curva de mercado da janela específica (se o usuário filtrou uma janela)
  let curvaJanela = null;
  if(mapaVenc !== 'todos'){
    curvaJanela = state.curva[mapaVenc] || CURVA_DEFAULT[mapaVenc];
  }
  const cbotJanelaLabel = mapaVenc !== 'todos' ? `CBOT ${mapaVenc}` : `${t('avgCbot')} (${t('allWindowsLower')})`;
  const camJanelaLabel = mapaVenc !== 'todos' ? `${t('fxRate')} ${CBOT_TO_DOLAR_MES[mapaVenc]||''}` : t('avgFx');

  box.innerHTML = `
    <div style="background:var(--card);border:0;border-bottom:1px solid var(--line);padding:20px 28px">
      <div style="display:flex;justify-content:space-between;align-items:flex-start;margin-bottom:12px">
        <div style="flex:1">
          <div style="font-size:13px;font-weight:700;color:var(--g900)">${t('periodAnalysis')}</div>
          <div style="font-size:13.5px;color:var(--g900);margin-top:6px;line-height:1.55">${fraseTopo}</div>
        </div>
        <div style="font-size:10.5px;color:var(--muted);text-align:right;margin-left:14px">
          ${dealsAtu.length} ${t('currentDeals')} · ${dealsAnt.length} ${t('priorDeals')}<br>
          ${mapaVenc!=='todos'?t('windowSing')+' <b>'+mapaVenc+'</b>':t('allWindowsLower')}
        </div>
      </div>

      ${dBasis === null ? `
        <div style="font-size:12px;color:var(--muted);padding:10px;background:var(--soft);border-radius:8px">⚠ ${t('noPriorPeriod')} (${iniAnt} ${t('to')} ${fimAnt}) ${mapaVenc!=='todos'?t('forThisWindow'):''}${t('driverDecompRequires')}</div>
      ` : `
      <div style="display:grid;grid-template-columns:repeat(6,1fr);gap:8px;margin-bottom:14px">
        <div class="metric" style="background:var(--card);border:1px solid var(--line)">
          <label>${cbotJanelaLabel}</label>
          <strong style="font-size:14px">${money(cbotAtu)} ¢</strong>
          <div style="font-size:10px;margin-top:3px">${tag(dCbot, '¢')}</div>
          ${curvaJanela ? `<div style="font-size:9px;color:var(--muted);margin-top:2px">${t('curveLabel')}: ${money(curvaJanela.cbot)}¢</div>` : ''}
        </div>
        <div class="metric" style="background:var(--card);border:1px solid var(--line)">
          <label>${camJanelaLabel}</label>
          <strong style="font-size:14px">R$ ${money(camAtu)}</strong>
          <div style="font-size:10px;margin-top:3px">${tag(dCam, '')}</div>
          ${curvaJanela ? `<div style="font-size:9px;color:var(--muted);margin-top:2px">${t('curveLabel')}: R$ ${money(curvaJanela.cambio)}</div>` : ''}
        </div>
        <div class="metric" style="background:var(--card);border:1px solid var(--line)"><label>${t('interiorPrice')}</label><strong style="font-size:14px">${money(prAtu)} ¢</strong><div style="font-size:10px;margin-top:3px">${tag(dPr, '¢', true)}</div></div>
        <div class="metric" style="background:var(--card);border:1px solid var(--line)"><label>${t('logisticsFreight')}</label><strong style="font-size:14px">${money(frAtu)} ¢</strong><div style="font-size:10px;margin-top:3px">${tag(dFr, '¢', true)}</div></div>
        <div class="metric" style="background:var(--card);border:1px solid var(--line)"><label>${t('basisParanagua')}</label><strong style="font-size:14px">${fobPgaAtu!==null?(fobPgaAtu-cbotAtu>=0?'+':'')+money(fobPgaAtu-cbotAtu)+' ¢':'—'}</strong><div style="font-size:10px;margin-top:3px">${tag(dFobPga!==null && dCbot!==null ? dFobPga-dCbot : null, '¢', true)}</div></div>
        <div class="metric" style="background:var(--card);border:1px solid var(--line)"><label>${t('basisCfrChina')}</label><strong style="font-size:14px">${cfrAtu!==null?(cfrAtu-cbotAtu>=0?'+':'')+money(cfrAtu-cbotAtu)+' ¢':'—'}</strong><div style="font-size:10px;margin-top:3px">${tag(dCfr!==null && dCbot!==null ? dCfr-dCbot : null, '¢', true)}</div></div>
      </div>

      <div style="display:grid;grid-template-columns:1fr 1fr;gap:10px;font-size:11.5px;line-height:1.55">
        ${maisAlta ? `<div style="padding:10px 12px;background:var(--amberbg);border:1px solid #fcd9b6;border-radius:8px"><b style="color:#92400e">${t('biggestRise')} ${maisAlta.corr}</b> ${t('rose')} <b>${money(Math.abs(maisAlta.delta))} ¢</b> (${t('from')} ${fmtBasis(maisAlta.basisAnt)} → ${fmtBasis(maisAlta.basisAtu)})</div>` : ''}
        ${maisQueda && maisQueda.corr !== (maisAlta&&maisAlta.corr) ? `<div style="padding:10px 12px;background:var(--greenbg);border:1px solid #BBF7D0;border-radius:6px"><b style="color:var(--green)">${t('biggestDrop')} ${maisQueda.corr}</b> ${t('fell')} <b>${money(Math.abs(maisQueda.delta))} ¢</b> (${t('from')} ${fmtBasis(maisQueda.basisAnt)} → ${fmtBasis(maisQueda.basisAtu)})</div>` : ''}
      </div>
      `}
    </div>`;
}


/* Tabela de mudanças por corredor — análise com decomposição quando há período */
function renderMapaTable(agg){
  const semPeriodo = !(mapaDataInicio && mapaDataFim);

  const items = Object.entries(agg).map(([corr, a])=>{
    const basis = a.basisVolSum/(a.calcWeightSum || a.volSum || 1);
    const preco = a.precoVolSum/(a.calcWeightSum || a.volSum || 1);

    let delta = null, comentario = '';

    if(semPeriodo){
      // Mensagem call-to-action — sem fingir análise sem dado comparativo
      comentario = `⚙️ ${t('selectPeriodCorridor')}`;
    } else {
      // Calcula período anterior do mesmo tamanho
      const dias = (new Date(mapaDataFim) - new Date(mapaDataInicio)) / 86400000;
      const iniAnt = new Date(new Date(mapaDataInicio).getTime() - (dias+1)*86400000).toISOString().slice(0,10);
      const fimAnt = new Date(new Date(mapaDataInicio).getTime() - 86400000).toISOString().slice(0,10);
      const dealsAnt = getActiveDealsReplacement().filter(d => d.corredor === corr && d.data >= iniAnt && d.data <= fimAnt && (mapaVenc==='todos' || d.vencCBOT===mapaVenc));

      if(dealsAnt.length === 0){
        // Período anterior vazio — faz análise descritiva do basis atual decomposta em componentes
        let _prAtu=0, _frAtu=0, _fbAtu=0, _cbotAtu=0, _camAtu=0;
        a.deals.forEach(d=>{
          const dl = getActiveDealsReplacement().find(x=>String(x.id)===String(d.id));
          if(!dl) return;
          const cmp = brzMapSafePortComparison(dl);
          const best = cmp.results.find(r=>r.porto===cmp.bestPort)?.best;
          if(best){
            _prAtu += best._priceCbu * d.vol;
            _frAtu += best._freightCbu * d.vol;
            _fbAtu += best._fobbinsCbu * d.vol;
          }
          _cbotAtu += n(dl.cbot) * d.vol;
          _camAtu += n(dl.cambio) * d.vol;
        });
        _prAtu /= a.volSum; _frAtu /= a.volSum; _fbAtu /= a.volSum;
        _cbotAtu /= a.volSum; _camAtu /= a.volSum;

        // Identifica qual parcela mais "pesa" no basis (preço ou frete)
        const portoTop = Object.entries(a.portos).sort((a,b)=>b[1]-a[1])[0][0];
        const janelaLabel = mapaVenc !== 'todos' ? mapaVenc : t('allWindowsLower');
        const status = basis <= 0 ? t('competitive') : basis <= 30 ? t('lowBasis') : basis <= 70 ? t('moderate') : t('highBasis');
        comentario = `${corr} → ${portoTop} ${t('forShipment')} ${janelaLabel}: ${a.count} ${t('dealsLower')}, ${t('basisLabel')} ${status} ${basis>=0?'+':''}${Math.round(basis)} c/b. ` +
          `${t('compositionLabel')} ${t('soyLower')} ${_prAtu.toFixed(0)}c + ${t('freightLower')} ${_frAtu.toFixed(0)}c + ${t('fobbinsLower')} ${_fbAtu.toFixed(0)}c = FOB ${(_prAtu+_frAtu+_fbAtu).toFixed(0)}c vs CBOT ${_cbotAtu.toFixed(0)}c.`;
        delta = null;  // sem comparativo
      } else {
        // Decompõe replacement em preço + frete + fobbins no ATUAL
        let _prAtu=0, _frAtu=0, _fbAtu=0, _cbotAtu=0, _camAtu=0;
        a.deals.forEach(d=>{
          const dl = getActiveDealsReplacement().find(x=>String(x.id)===String(d.id));
          if(!dl) return;
          const cmp = brzMapSafePortComparison(dl);
          const best = cmp.results.find(r=>r.porto===cmp.bestPort)?.best;
          if(best){
            _prAtu += best._priceCbu * d.vol;
            _frAtu += best._freightCbu * d.vol;
            _fbAtu += best._fobbinsCbu * d.vol;
          }
          _cbotAtu += n(dl.cbot) * d.vol;
          _camAtu += n(dl.cambio) * d.vol;
        });
        _prAtu /= a.volSum; _frAtu /= a.volSum; _fbAtu /= a.volSum;
        _cbotAtu /= a.volSum; _camAtu /= a.volSum;

        // E no ANTERIOR
        let bAnt=0, pAnt=0, prAnt=0, frAnt=0, fbAnt=0, cbotAnt=0, camAnt=0, wAnt=0;
        dealsAnt.forEach(d=>{
          const cmp = brzMapSafePortComparison(d);
          const best = cmp.results.find(r=>r.porto===cmp.bestPort)?.best;
          const v = n(d.volume);
          if(best){
            bAnt += best.replacementBasis*v;
            prAnt += best._priceCbu*v;
            frAnt += best._freightCbu*v;
            fbAnt += best._fobbinsCbu*v;
          }
          pAnt += n(d.preco)*v;
          cbotAnt += n(d.cbot)*v;
          camAnt += n(d.cambio)*v;
          wAnt += v;
        });
        const bAntMed = bAnt/wAnt;
        const prAntMed = prAnt/wAnt;
        const frAntMed = frAnt/wAnt;
        const cbotAntMed = cbotAnt/wAnt;
        const camAntMed = camAnt/wAnt;

        delta = basis - bAntMed;
        const dPreco = _prAtu - prAntMed;
        const dFrete = _frAtu - frAntMed;
        const dCbot = _cbotAtu - cbotAntMed;
        const dCam = _camAtu - camAntMed;

        // Identifica o driver dominante (qual parcela explicou mais a variação)
        const drivers = [
          {nome:t('interiorPriceLower'), val:dPreco, abs:Math.abs(dPreco)},
          {nome:t('freightLower'), val:dFrete, abs:Math.abs(dFrete)},
          {nome:'CBOT', val:-dCbot, abs:Math.abs(dCbot)},
          {nome:t('fxLabel'), val:dCam, abs:Math.abs(dCam)*10}
        ].sort((a,b)=>b.abs-a.abs);

        // Porto principal e janela específica
        const portoTop = Object.entries(a.portos).sort((a,b)=>b[1]-a[1])[0][0];
        const janelaLabel = mapaVenc !== 'todos' ? mapaVenc : t('allWindowsLower');

        // Frase no formato do prompt
        const sinal = delta >= 0 ? t('rose') : t('fell');
        const justificativaPartes = [];
        if(Math.abs(dPreco) > 0.5){
          const sentido = (delta >= 0 && dPreco >= 0) || (delta < 0 && dPreco < 0);
          if(sentido) justificativaPartes.push(`${delta>=0?t('soyPriceIncreaseShort'):t('soyPriceDecreaseShort')} (${dPreco>=0?'+':''}${dPreco.toFixed(1)}c)`);
        }
        if(Math.abs(dFrete) > 0.5){
          const sentido = (delta >= 0 && dFrete >= 0) || (delta < 0 && dFrete < 0);
          if(sentido) justificativaPartes.push(`${delta>=0?t('freightRiseShort'):t('freightDropShort')} (${dFrete>=0?'+':''}${dFrete.toFixed(1)}c)`);
        }
        if(Math.abs(dCbot) > 3){
          const sentido = (delta >= 0 && dCbot < 0) || (delta < 0 && dCbot >= 0);
          if(sentido) justificativaPartes.push(`${t('cbotMovementShort')} (${dCbot>=0?'+':''}${dCbot.toFixed(0)}c)`);
        }

        const riseOrFall = delta >= 0 ? t('theRise') : t('theFall');
        const dueTo = justificativaPartes.length===1 ? t('dueTo') : t('mainlyDueTo');
        const motivoFrase = justificativaPartes.length
          ? `${riseOrFall} ${dueTo} ${justificativaPartes.join(' ' + t('andConnector') + ' ')}.`
          : t('variationSpread');

        comentario = `${corr} → ${portoTop} ${t('forShipment')} ${janelaLabel} ${sinal} ${Math.abs(delta).toFixed(1)} ${t('cbVsPrior')}. ${motivoFrase}`;
      }
    }

    return {corr, count:a.count, vol:a.volSum, preco, basis, delta, comentario};
  });

  items.sort((a,b)=>b.vol - a.vol);

  document.getElementById('mapaTableBody').innerHTML = items.map(x=>`<tr style="cursor:pointer" onclick="mapaCorredorSelecionado='${x.corr}';renderMapa()">
    <td><b>${x.corr}</b></td>
    <td><span class="tag neutral">${mapaVenc==='todos'?'Todas':mapaVenc}</span></td>
    <td class="num">${x.count}</td>
    <td class="num">${tons(x.vol)}</td>
    <td class="num">R$ ${money(x.preco)}</td>
    <td class="num"><span class="tag ${x.basis<=0?'green':x.basis<=50?'amber':'red'}">${x.basis>=0?'+':''}${fmtBasis(x.basis)} ¢</span></td>
    <td class="num">${x.delta===null?'<span style="color:var(--muted)">—</span>':`<span class="tag ${x.delta<=0?'green':'red'}">${x.delta>=0?'▲':'▼'} ${money(Math.abs(x.delta))} ¢</span>`}</td>
    <td style="font-size:10.5px;color:${semPeriodo?'var(--muted)':'var(--text)'};max-width:340px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;${semPeriodo?'font-style:italic':''}" title="${x.comentario.replace(/"/g,'&quot;')}">${x.comentario}</td>
  </tr>`).join('') || '<tr><td colspan="8" class="empty">Sem dados</td></tr>';
}

