function toggleRightPanel(force){
  const grid = document.getElementById('contentGrid');
  const collapsed = (force===true) ? true : (force===false) ? false : !grid.classList.contains('panel-closed');
  grid.classList.toggle('panel-closed', collapsed);
  updatePanelHandle();
}
function openRightPanel(){
  document.getElementById('contentGrid').classList.remove('panel-closed');
  updatePanelHandle();
}
function updatePanelHandle(){
  const grid = document.getElementById('contentGrid');
  const collapsed = grid.classList.contains('panel-closed');
  document.getElementById('panelHandleIcon').textContent = collapsed?'⟩':'⟨';
  document.getElementById('openPanelBtn').style.display = collapsed?'block':'none';
}

/* ═══════════════════════════════════════════════════════
   DIVISOR ARRASTÁVEL — redimensiona painel direito
═══════════════════════════════════════════════════════ */
const PANEL_WIDTH_KEY = 'brzPanelWidth';
const PANEL_MIN = 280;
const PANEL_MAX_RATIO = 0.65;  // até 65% da largura da janela

function applyPanelWidth(px){
  const max = Math.floor(window.innerWidth * PANEL_MAX_RATIO);
  const w = Math.max(PANEL_MIN, Math.min(max, px));
  document.documentElement.style.setProperty('--panel-width', w + 'px');
  return w;
}

function loadPanelWidth(){
  const saved = parseInt(BRZ_STORAGE.getItem(PANEL_WIDTH_KEY) || '460', 10);
  applyPanelWidth(saved);
}

function initPanelResizer(){
  const resizer = document.getElementById('panelResizer');
  if(!resizer) return;
  let dragging = false;
  let startX = 0;
  let startWidth = 0;

  const onMouseDown = (e) => {
    dragging = true;
    startX = e.clientX;
    startWidth = parseInt(getComputedStyle(document.documentElement).getPropertyValue('--panel-width')) || 400;
    document.body.classList.add('resizing');
    resizer.classList.add('dragging');
    e.preventDefault();
  };

  const onMouseMove = (e) => {
    if(!dragging) return;
    // Arrastar para esquerda aumenta o painel (delta = startX - clientX)
    const delta = startX - e.clientX;
    const newWidth = applyPanelWidth(startWidth + delta);
    e.preventDefault();
  };

  const onMouseUp = () => {
    if(!dragging) return;
    dragging = false;
    document.body.classList.remove('resizing');
    resizer.classList.remove('dragging');
    const current = parseInt(getComputedStyle(document.documentElement).getPropertyValue('--panel-width')) || 400;
    BRZ_STORAGE.setItem(PANEL_WIDTH_KEY, current);
  };

  // Duplo-clique para resetar
  resizer.addEventListener('dblclick', ()=>{
    applyPanelWidth(400);
    BRZ_STORAGE.setItem(PANEL_WIDTH_KEY, 400);
  });

  resizer.addEventListener('mousedown', onMouseDown);
  document.addEventListener('mousemove', onMouseMove);
  document.addEventListener('mouseup', onMouseUp);

  // Touch
  resizer.addEventListener('touchstart', (e)=>{
    if(e.touches[0]) onMouseDown({clientX: e.touches[0].clientX, preventDefault:()=>{}});
  }, {passive:true});
  document.addEventListener('touchmove', (e)=>{
    if(dragging && e.touches[0]) onMouseMove({clientX: e.touches[0].clientX, preventDefault:()=>e.preventDefault()});
  }, {passive:false});
  document.addEventListener('touchend', onMouseUp);

  // Janela redimensiona — reaplica respeitando o max
  window.addEventListener('resize', ()=>{
    const current = parseInt(BRZ_STORAGE.getItem(PANEL_WIDTH_KEY) || '400', 10);
    applyPanelWidth(current);
  });
}

