function exportCSV(kind){
  let rows = [];
  if(kind==='negocios') rows = getActiveDeals().filter(function(d){return !d.naoAbrirMercado && !d.foraMercado;});
  if(kind==='fretesRodo') rows = state.fretesRodo;
  if(kind==='fretesFerro') rows = state.fretesFerro.map(f=>({regiao:f.regiao, origem:f.origem, destino:f.destino, ...f.meses, obs:f.obs}));
  if(!rows.length){ alert('Sem dados.'); return; }
  const h = [...new Set(rows.flatMap(r=>Object.keys(r)))];
  const csv = [h.join(';'), ...rows.map(r=>h.map(k=>csvEsc(r[k])).join(';'))].join('\n');
  blob(csv, kind+'_brz.csv','text/csv;charset=utf-8;');
}

function htmlEscapeScriptJson(value){
  return JSON.stringify(value)
    .replace(/<\//g, '<\\/')
    .replace(/<!--/g, '<\\!--');
}
function downloadHtmlSnapshot(){
  try{
    persist();
    const snapshotState = {
      ...state,
      negocios: (state.negocios || []).map(d => ({...d})),
      precos: [], // preços ficam no script dataPrecos para evitar duplicação no snapshot
      fretesRodo: (state.fretesRodo || FRETES_RODO_BASE || []).map(d => ({...d})),
      fretesFerro: (state.fretesFerro || FRETES_FERRO_BASE || []).map(d => ({...d})),
      curva: structuredClone(state.curva || CURVA_DEFAULT),
      cbot: {...(state.cbot || CBOT_DEFAULT)},
      cbotMilho: {...(state.cbotMilho || CBOT_MILHO_DEFAULT)},
      curvaMilho: structuredClone(state.curvaMilho || {}),
      dolar: {...(state.dolar || DOLAR_DEFAULT)},
      oceanFreight: structuredClone(state.oceanFreight || OCEAN_FREIGHT_DEFAULT),
      simulacoes: Array.isArray(state.simulacoes) ? state.simulacoes : []
    };

    const clone = document.documentElement.cloneNode(true);
    function setJson(id, value){
      let el = clone.querySelector('#' + id);
      if(!el){
        el = document.createElement('script');
        el.id = id;
        el.type = 'application/json';
        const anchor = clone.querySelector('#dataFerro') || clone.querySelector('#dataRodo') || clone.querySelector('#dataDeals');
        if(anchor && anchor.parentNode) anchor.parentNode.insertBefore(el, anchor.nextSibling);
        else clone.querySelector('body').appendChild(el);
      }
      el.textContent = htmlEscapeScriptJson(value);
    }

    setJson('dataDeals', snapshotState.negocios);
    // dataPrecos NAO e sobrescrito: o snapshot mantem os precos ja embutidos no clone (getPrecosBase le o script embutido dataPrecos).
    setJson('dataRodo', snapshotState.fretesRodo);
    setJson('dataFerro', snapshotState.fretesFerro);
    setJson('dataState', snapshotState);

    // Re-injeta a tela de entrada (splash) no snapshot exportado.
    (function(){
      var _body = clone.querySelector('body');
      if(_body && !clone.querySelector('#brz-splash')){
        var _w = document.createElement('div');
        _w.innerHTML = '<div id="brz-splash" data-no-i18n role="status" aria-label="Carregando Replacement BRZ"><div class="brz-grid"></div><div class="brz-inner"><div class="brz-eyebrow">Reposição · Grãos · Exportação</div><div class="brz-word">Replacement <b>BRZ</b><span class="brz-dots"><i>.</i><i>.</i><i>.</i></span></div><div class="brz-bar"><i></i></div></div></div>';
        if(_w.firstElementChild) _body.insertBefore(_w.firstElementChild, _body.firstChild);
      }
    })();

    // Garante que todo HTML exportado abra na aba Inicial e com a lateral direita fechada.
    clone.querySelectorAll('.screen').forEach(el => el.classList.remove('active'));
    const initialScreen = clone.querySelector('#inicial');
    if(initialScreen) initialScreen.classList.add('active');

    clone.querySelectorAll('.menu button, .topmenu button').forEach(btn => btn.classList.remove('active'));
    const initialBtn = clone.querySelector('.topmenu button[data-screen="inicial"], .menu button[data-screen="inicial"]');
    if(initialBtn) initialBtn.classList.add('active');

    const contentClone = clone.querySelector('#contentGrid');
    if(contentClone) contentClone.classList.add('panel-closed');

    const titleClone = clone.querySelector('#pageTitle');
    if(titleClone){
      titleClone.textContent = 'Inicial';
      titleClone.setAttribute('data-i18n','pageTitleInicial');
    }

    const stamp = new Date().toISOString().slice(0,19).replace(/[T:]/g,'-');
    let html = '<!DOCTYPE html>\n' + clone.outerHTML;
    html = html.replace(/const\s+STORAGE_KEY\s*=\s*['"][^'"]+['"]\s*;/, `const STORAGE_KEY = 'BRZ_REPLACEMENT_FAST_ABSOLUTE_PRICE_${stamp}';`);
    html = html.replace(/<title>(.*?)<\/title>/, `<title>BRZ Replacement Engine — Snapshot ${stamp}</title>`);

    blob(html, `BRZ_Replacement_atualizado_${stamp}.html`, 'text/html;charset=utf-8');
    alert('HTML atualizado exportado com sucesso. Este arquivo já contém os dados atuais embutidos.');
  }catch(e){
    console.error('Erro ao exportar HTML atualizado:', e);
    alert('Não foi possível exportar o HTML atualizado. Abra o console para ver o erro.');
  }
}

function downloadBackup(){ blob(JSON.stringify(state,null,2),'brz_replacement_backup.json','application/json'); }
function blob(c,f,t){ const b = new Blob([c],{type:t}); const u = URL.createObjectURL(b); const a = document.createElement('a'); a.href=u; a.download=f; a.click(); URL.revokeObjectURL(u); }
