/* ═══ V4AV 05/11/2026 · SAFRA dinâmica (regra safra.calendario no dataRules) ═══
   Chaves: soja 'AA_BB' (ex. 25_26) · milho/sorgo 'verao_AA_BB' e 'safrinha_AAAA'.
   Safra vem do mês FÍSICO da entrega. Soja: jan a dez/Y = safra (Y−1)/Y.
   Milho e sorgo: jan a mai/Y = Verão (Y−1)/Y · jun a dez/Y = Safrinha Y.
   'disponivel' é atributo (entrega no mês do negócio ou spot), não safra. */
function brzSafraPorFisico(produto, ano, mes){
  var p=(typeof normalizeProduto==='function')?normalizeProduto(produto):String(produto||'');
  var cut=Number(brzRegraParam('safra.calendario','milhoVeraoAteMes',5));
  var yy=function(y){ return String(y%100).padStart(2,'0'); };
  if(p==='Soja') return yy(ano-1)+'_'+yy(ano);
  if(mes<=cut) return 'verao_'+yy(ano-1)+'_'+yy(ano);
  return 'safrinha_'+ano;
}
function brzFisicoDeal(d){
  if(!d) return null;
  var jf=brzEmbParse(d.janelaFisica||''); if(jf) return {ano:2000+jf.yy, mes:jf.mes+1};
  var e=brzEmbParse(d.embarque||''); if(e){ var i=(2000+e.yy)*12+e.mes-1; return {ano:Math.floor(i/12), mes:i%12+1}; }
  return null;
}
function brzSafraKeyDeal(d){
  if(d && d.safraKey) return d.safraKey;
  var f=brzFisicoDeal(d); if(!f) return 'outro';
  return brzSafraPorFisico(d.grupoProduto==='Milho'?'Milho':d.produto, f.ano, f.mes);
}
function brzSafraLabel(k){
  k=String(k||'');
  if(k==='todos') return 'Todas safras';
  if(k==='disponivel') return 'Disponível (spot)';
  if(k==='outro') return 'Outras';
  var m;
  if((m=/^(\d{2})_(\d{2})$/.exec(k))) return 'Safra '+m[1]+'/'+m[2];
  if((m=/^verao_(\d{2})_(\d{2})$/.exec(k))) return 'Verão '+m[1]+'/'+m[2];
  if((m=/^safrinha_(\d{4})$/.exec(k))) return 'Safrinha '+m[1];
  return k;
}
function brzSafraOrdem(k){
  var m;
  if((m=/^(\d{2})_(\d{2})$/.exec(k))) return (2000+Number(m[2]))*10;
  if((m=/^verao_(\d{2})_(\d{2})$/.exec(k))) return (2000+Number(m[2]))*10+1;
  if((m=/^safrinha_(\d{4})$/.exec(k))) return Number(m[1])*10+5;
  return 999999;
}
function brzSafraAno(k){ var o=brzSafraOrdem(k); return o<999999?Math.floor(o/10):null; }
function brzSafraLista(rows){
  var s={}; (rows||[]).forEach(function(d){ var k=brzSafraKeyDeal(d); if(k && k!=='outro') s[k]=1; });
  return Object.keys(s).sort(function(a,b){ return brzSafraOrdem(a)-brzSafraOrdem(b); });
}
function brzAnoReferencia(){ var md=(typeof brzMarketDate==='function')?brzMarketDate():null; return md?Number(md.slice(0,4)):new Date().getFullYear(); }
function brzSafraClasse(dOrKey){
  var k=(typeof dOrKey==='string')?dOrKey:brzSafraKeyDeal(dOrKey); var a=brzSafraAno(k);
  return (a!=null && a>brzAnoReferencia())?'nova':'velha';
}
function brzSafraTag(k){
  if(k==='disponivel') return 'green';
  var a=brzSafraAno(k), r=brzAnoReferencia(); if(a==null) return 'neutral';
  return a<r?'neutral':(a===r?'amber':'blue');
}
function brzSafraMatch(d,f){
  if(!f||f==='todos') return true;
  if(f==='disponivel') return !!(d&&d.disponivel);
  return brzSafraKeyDeal(d)===f;
}

/* ═══ Sub-aba REGRAS (Outros → Regras) · V4AR 05/11/2026 ═══ */
var BRZ_RG_GRUPOS=['Meses','Câmbio','Curvas','Calendário','Frete','Porto e basis','Marítimo','Escopo','Preço'];
var _rgDraft=null;
function _rgEsc(s){ return String(s==null?'':s).replace(/[&<>"]/g,function(c){return {'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;'}[c];}); }
function _rgClone(o){ return JSON.parse(JSON.stringify(o)); }
function _rgDraftGet(id){ if(!_rgDraft) _rgDraft={}; if(!_rgDraft[id]){ var r=brzRegra(id); _rgDraft[id]=_rgClone(r.params||{}); } return _rgDraft[id]; }
var _rgDraftTexto={};
function _rgDirty(){ return (_rgDraft && Object.keys(_rgDraft).length>0) || Object.keys(_rgDraftTexto).length>0; }
function _rgDirtyCount(){ return (_rgDraft?Object.keys(_rgDraft).length:0)+Object.keys(_rgDraftTexto).length; }
function rgSetTexto(el){ var id=el.dataset.rg, r=brzRegra(id); var v=String(el.value); if(r && v===String(r._textoCanonico!=null?r._textoCanonico:r.texto)) delete _rgDraftTexto[id]; else _rgDraftTexto[id]=v; _rgBar(); }
